window.__D("text/torat-chaim/c029",{"p":[[2300550050,"<b>בעז\"ה פ' משפטים</b>\n<span data-k=\"pg\">852</span> ּ<b>כי</b> תקנה עבד<sup data-n=\"1663\">1</sup> עברי<sup data-n=\"1664\">2</sup> כו', הנה י\"ל תחילה אמר אשר תשים דקאי במשה שימשיך לכנ\"י וזהו לפניהם<sup data-n=\"1665\">3</sup> דקאי בבנ\"י וא\"כ הל\"ל כי יקנו לשון רבים כמ\"ש לפניה\"ם לשון רבים ולמה א' כי תקנה לשון יחיד דמשמע דקאי במשה. והענין הוא דבאמת א\"ל<sup data-n=\"1666\">4</sup> דכי תקנה זה קאי במשה וקאי על מ\"ש בתחלה אשר תשים אתה דוקא וח[ו]זר ומפרש [לו] למשה דוקא כי תקנה עבד עברי כו' ולכך לא א' כי יקנו לשון רבים דלא קאי אלפניהם דסמ[י]ך לי' אלא על מ\"ש בתחלה<sup data-n=\"1667\">5</sup> ואלה המשפטים אשר תשים לשון יחיד. ולהבין איך יתכן ענין זה דכי תקנה במשה דוקא, הנה י\"ל תחלה",[["1663","1","<b>כי תקנה עבד עברי</b>: מיוסד על חלק השני מד\"ה ואלה המשפטים שנדפס במאמרי אדה\"ז תקס\"ה ח\"א ע' רנד ואילך (נוסחא שני' והיא הנחת כ\"ק אדה\"א). שם ע' רנז ואילך (נוסח א' — והיא הנחת הר\"מ בן כ\"ק אדה\"ז) נדפסה גם לעיל רעח, סע\"ב. והנחה אחרת ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>. וראה הנסמן במ\"מ לשם בריש המאמר. מאמר זה הוא המשך לד\"ה ואלה המשפטים שנדפס לפנ\"ז. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["1664","2","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."],["1665","3","<b>אשר תשים. . לפניהם</b>: משפטים שם, א."],["1666","4","<b>א\"ל</b>: (א)ד: יש לפרש."],["1667","5","<b>בתחלה</b>: שם: ברישא."]]],[2300550082,"שרש ענין הקנין מהו, דהנה ידוע ומבואר [במ\"א] בענין קונה שמים וארץ<sup data-n=\"1668\">6</sup> וקונה הכל<sup data-n=\"1669\">7</sup> כו' מהו ההפרש בין בריאה לקנין דמ\"ש בראשית ברא<sup data-n=\"1670\">8</sup> כו' וכן בורא שמים וארץ<sup data-n=\"1671\">9</sup> כו' (כידוע דג' לשונות בורא יוצר [ו]עושה הן ג' עולמות דבי\"ע והקנין בבחי' אצי'<sup data-n=\"1672\">10</sup> שהוא רק מהעלם לגילוי) דהבריאה<sup data-n=\"1673\">*11</sup> לא שייך רק בדבר שהוא מחודש מעיקרו דוקא דהיינו בדבר שנתחדש יש מאין ממש כמ\"ש אם בריאה יברא [ה'] ופצתה האדמה<sup data-n=\"1674\">11</sup> שזהו דבר חידוש יש מאין שנתחדש<sup data-n=\"1675\">12</sup>, וכידוע בענין חידוש יש מאין דהיינו שלא הי' הדבר במציאות[ו] כלל בתחלה רק עתה הנה הוא מתהווה ומתחדש מציאותו יש מאין כו'. אבל הקנין הוא עד\"מ הקונה הסחורה שמוציאה מרשות המוכר לרשותו שאין זה התחדשות כלל בגוף הדבר לומר שנתחדש מציאותו ברשות הקונה, שהוא הדבר<sup data-n=\"1676\">13</sup> כמו שהי' בהווייתו היתה ברשות המוכר בלי שום שינוי כלל רק שינוי הרשות בלבד כו' רק מה שהיתה ביד המוכר נק' העלם [ה]דבר <span data-k=\"pg\">תכו</span> ּ וכאשר בא לידי הקונה נק' גילוי ההעלם אחר שהוציאה לרשותו כו'. וכמשל זה נק' בשם קנין למעלה<sup data-n=\"1677\">*14</sup> שהוא למעלה מבחי' הבריאה דהבריאה הוא יש מאין כנ\"ל והוא התהוות העולמות מאין ליש שנק' מחודש, אבל באצי' עצמו מה שנאצלו [ה]ע\"ס מן המאציל זהו נק' בשם קנין לבד דהיינו שיצאו מן ההעלם לגילוי בלבד, וכידוע דע\"ס דאצי' היו כלולים בהעלם עצמו' המאציל ונק' ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"1678\">14</sup> וכאשר באו לידי גילוי במציאות ע\"ס זהו כמו הקנין שהדבר יוצא מרשות לרשות לבד כי אין כאן התחדשות כלל בגוף הדבר כו' (וכמו<sup data-n=\"1679\">15</sup> קונה שמים וארץ דודאי שו\"א באו בבחי' חידוש הבריאה יש מאין ולא בבחי' קנין מהעלם לגילוי לבד, הענין הוא דלגבי עצמו' המאציל שוה אצי' ובריאה<sup data-n=\"1680\">16</sup> דכמו שהאצי' הוא בא רק מהעלם לגילוי בבחי' קנין כך קונה שו\"א לפי שאין שם בחי' מעלה ומטה כלל כמשי\"ת כו'<sup data-n=\"1681\">17</sup> ). וזהו כי תקנה עבד עברי דקאי במשה דוקא לפי שמשה הוא הקונה להביא ההעלם לגילוי כמשי\"ת, וע\"כ א' למשה דוקא כי תקנה ע\"ע שמלבד שהוא הקונה למעלה עוד זאת יעשה במה שממשיך הדעת מאצי' לבריאה לנשמות דבי\"ע כנ\"ל<sup data-n=\"1682\">18</sup> שגם הם יהיו בבחי' אדם דאצי' שהוא נק' בשם קנין אע\"פ שמצד עצמן הן נשמות דבריאה בחידוש יש מאין ולא בבחי' קנין אבל באמצעות הדעת דאצי' שממשיך בהם יוכלו לבא לבחי' קנין גם הם וד\"ל.",[["1668","6","<b>קונה שמים וארץ</b>: לך יד, יט. כב. ראה מאמרי אדה\"ז כאן ע' רנד (נוסחא שני') וע' רנז (נוסח א')."],["1669","7","<b>וקונה הכל</b>: תפילת העמידה."],["1670","8","<b>בראשית ברא</b>: בראשית א, א."],["1671","9","<b>בורא שמים וארץ</b>: וכ\"ה במאמרי אדה\"ז כאן. לעיל רעח, ב. ישעי' מב, ה [ושם: בורא השמים. . הארץ]. מה, יח [ושם: בורא השמים. . הארץ]. סה יז [ושם: בורא שמים. . וארץ]."],["1672","10","<b>בורא יוצר [ו]עושה. . דבי\"ע והקנין. . אצי'</b>: פע\"ח (שער ר\"ח) שי\"ט, פ\"ג."],["1673","*11","<b>דהבריאה</b>: מכאן נעתק בהמשך תרס\"ו ע' קסא (בשנוי קל)."],["1674","11","<b>אם בריאה יברא. . האדמה</b>: קרח טז, ל [ושם ואם — וכ\"ה במאמרי אדה\"ז תקס\"ה כאן ע' רנד. אבל בהמשך תרס\"ו הובא כבפנים]."],["1675","12","<b>יש מאין שנתחדש</b>: אד: שנתחדש מאין. אבל בהמשך תרס\"ו הובא כבפנים."],["1676","13","<b>שהוא הדבר</b>: שם: שהרי היא."],["1677","*14","<b>למעלה</b>: ע\"כ נעתק בהמשך תרס\"ו שם."],["1678","14","<b>ע\"ס. . בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["1679","15","<b>וכמו</b>: אד: ומ\"ש."],["1680","16","<b>שוה אצי' ובריאה</b>: ראה גם לעיל פ' בשלח קלה, א הערה 105."],["1681","17","<b>כו'</b>: שם: בעז\"ה."],["1682","18","<b>כנ\"ל</b>: בד\"ה ואלה המשפטים — שנדפס לפנ\"ז."]]],[2300550114,"<b>ויובן</b> [ביאור] זה ע\"פ הידוע ההפרש שבין נשמות דאצי' לנשמות דבריאה ע\"פ ויבא יוסף הביתה<sup data-n=\"1683\">19</sup> לעשות מלאכתו ות\"א למיבדק כתבי חושבנא<sup data-n=\"1684\">20</sup> וזה פלא גדול דהילוך<sup data-n=\"1685\">21</sup> יוכל להיות דבר והיפוכו כא' שהרי יוסף הי' בחי' מרכבה להיות שהי' שרש נשמתו באצי' ממש, ופי' מרכבה הוא בחי' הביטול והדביקות תמידית באמיתי' כל חושי גופו ג\"כ ואיך הי' להיפך להטריד עצמו בכל עומק העסקי' בכתבי חושבנא ואיך לא הי' מבלבלים אותו כלל מאמיתי' דביקותו וביטולו כו', אלא צ\"ל שאין עניני עוה\"ז תופסים מקום כלל עד שלא יבלבלו מחשבתו ודביקותו כלל ויכול להיות דבוק רק למעלה באמיתי' הביטול ובאותה שעה עצמו חושב בעומק החשבון בכל פרטי הצטרכות העסקי', וא\"ז<sup data-n=\"1686\">22</sup> רק במי שנשמתו באצי' ממש ולא במי שנשמתו מאצי' שמלובש בבריאה. והטעם מובן להיות שהארת אצי' בבריאה הרי כבר נסתר ונתצמצם אור האצי' ע\"י מסך כו' להיות התהוות הבריאה יש מאין, ומאחר שנעשה בבחי' יש עכ\"פ ע\"כ מי שנשמתו מע\"ס דבריאה לא יוכל להיות מרכבה לאצי' כ\"א ע\"י מס\"נ בעת הכושר ולא תמידי', ומכ\"ש<sup data-n=\"1687\">23</sup> באותו עת שנטרד בעניני עוה\"ז כי תופסים מקום אצלו במח' ואיך יוכל להיות מח[שבתו] פנוי' לגמרי בדביקות אמיתי' להיות בבחי' מרכבה ממש. אך מי שנשמתו באצי' עצמו שהוא בבחי' אוא\"ס דאיהו וחיוהי חד<sup data-n=\"1688\">24</sup> שאין הבריאה והיצי' תופסים מקום כלל שיצטרך לפשוט עצמו משם ע\"י הכנה במס\"נ או לפנות מטרדות עוה\"ז ע\"כ גם בהיותו טרוד מאד בכתבי דחושבנא הוא דבוק למעלה כי למעלה ולמטה שוין בלתי יתבלבל מזה כלל וכלל. וע\"כ לא הי' בחי' מרכבה רק כמו האבות<sup data-n=\"1689\">25</sup> שהיו בבחי' האצי' עצמו וכמ\"ש באברהם אשר התהלכתי לפניו<sup data-n=\"1690\">26</sup> התהלך לפני<sup data-n=\"1691\">27</sup> בבחי' דביקות וביטול תמידי בלי הפסק אפי' בהיותו עוסק בצרכי ביתו ועבודה בשדה כו' וכן ויתהלך חנוך<sup data-n=\"1692\">28</sup> את האלקי' <span data-k=\"pg\">854</span> ּ וכה\"ג משה ואהרן, אבל נשמות ששרשם מבחי' האצי' שמלובש בבריאה בהפסק המסך כו' יש בהם שינויים לפעמים עולים במס\"נ בדביקות אמיתי' מבריאה לאצי' שנק' מבחי'<sup data-n=\"1693\">29</sup> גדלות המוחין וזהו מצד הסתר אור האצי' צריכים להפשטת הגשמיי' ביותר כמו שאר הנביאים זולת משה כו', ולפעמים הם בבחי' הקטנות וזהו לפ\"ע הזדככות החומר שלהם בשינוי העיתים כו' שהוא",[["1683","19","<b>ויבא יוסף הביתה</b>: וישב לט, יא [בהוספת תיבת: יוסף — ראה מאמרי אדה\"ז תקס\"ה שבהערה הבאה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680088\" data-slug=\"torat-chaim\" data-id=\"2300680088\">תו\"ח ויחי רמג, ג</a>]."],["1684","20","<b>ויבא יוסף. . כתבי חושבנא</b>: תרגום אונקלוס וישב שם. ראה מאמרי אדה\"ז תקס\"ה (כאן בהביאור) ע' רסז (נוסחא שני') — וכנראה שזהו המובא בסמוך בפנים). מאמרי אדה\"א ויקרא ח\"א ע' ריא וע' רסה. וש\"נ. נ\"ך ע' קצ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680088\" data-slug=\"torat-chaim\" data-id=\"2300680088\">תו\"ח ויחי רמג, ג</a> ובהערה 49."],["1685","21","<b>דהילוך</b>: אד: דאיך."],["1686","22","<b>וא\"ז</b>: ד: ואין זה."],["1687","23","<b>ומכ\"ש</b>: אד: וכ\"ש."],["1688","24","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["1689","25","<b>מרכבה. . האבות</b>: נסמן לעיל פ' יתרו רנא, ג."],["1690","26","<b>אשר התהלכתי לפניו</b>: ח\"ש כד, מ."],["1691","27","<b>התהלך לפני</b>: לך יז, א."],["1692","28","<b>ויתהלך חנוך</b>: בראשית ה, כד."],["1693","29","<b>מבחי'</b>: א: בבחי'. ד: בחי'."]]],[2300550146,"מפני שהעולם הבריאה תופס מקום אצלם כו'. משא\"כ ביוסף ומשה [וכו'] וכן דוד א' אם זכרתיך על יצועי<sup data-n=\"1694\">30</sup> שאז הוא בבחי' הקטנות ג\"כ באשמורות אהגה בך דדוד הי' מרכבה<sup data-n=\"1695\">31</sup> ל[מל' ד]אצי' ממש<sup data-n=\"1696\">32</sup> דקטנות וגדלות שוין ממש. וז\"ש ואלה הגבורים אשר לדוד<sup data-n=\"1697\">33</sup> אשר יעזרו לדוד בלא לב ולב<sup data-n=\"1698\">34</sup> פי' לא לב ולב שוין כו' וכמ\"ש בק\"ש ובשכבך ובקומך<sup data-n=\"1699\">35</sup> יהי' שניהם בשוה כי יש בכאו\"א מישראל בשרשו מבחי' אור האצי' עצמו. וזהו כי תקנה ע\"ע כנ\"ל דע\"י המשכות הדעת דמשה יוכלו גם נשמות דבי\"ע להיות כמו בבחי' האצי' ממש להיות בבחי' קנין כו' וד\"ל.\n<b>והנה</b> י\"ל בטעם הדבר דאיך יתכן שע\"י בחי' המשכת הדעת שע\"י משה יוכלו כל נשמות להיות בבחי' קנין שבבחי' האצי' אפי' בנפש דעשי' בקטן שבישראל כו', אך צריך להבין תחלה מהו ענין ע\"ע. דהנה ידוע בטעם קריאת [שם] עברי משום דאאע\"ה בעה\"נ הי' כמ\"ש בעבה\"נ ישבו אבותיכם<sup data-n=\"1700\">36</sup> וא' בזהר בעה\"נ ההוא נהר דאשתמודע כו' והוא מ\"ש ונהר יוצא מעדן<sup data-n=\"1701\">37</sup> מעה\"נ זה דוקא, וביאור הענין ידוע דנהר שיוצא מעדן הוא בחי' פנימי' בינה ששם מתגלה מפנימי' ע\"י<sup data-n=\"1702\">38</sup> שנק' עדן סתימאה<sup data-n=\"1703\">39</sup> כו' שע\"ז א' עין לא ראתה<sup data-n=\"1704\">40</sup>, אך בנהר זה שיוצא מעדן הוא שנמצא שרש וראש לכל השתלשלו' עו\"ע כמו עד\"מ הנהר הגדול שהוא מקור כללי לכל הנהרות ובריכות מים שמסתעפים הימנה לכל צד וכמ\"כ נהר שיוצא מעדן הוא נהר א' כללי וממנו יפרד והי' לארבעה ראשים שהן ד' נהרות כוללים כידוע. וכאשר חטא אדה\"ר בעה\"ד טו\"ר נמשך התערובות טו\"ר<sup data-n=\"1705\">41</sup> בכל הד' נהרות שיצאו ונפרד[ו] מבחי' הנהר הראשון בכל חלקי העולם כי נפלו שם מרפ\"ח ניצוצי'<sup data-n=\"1706\">42</sup> והבירור הי' בס\"ר נש\"י שיצא[ו] מן נהר נילוס<sup data-n=\"1707\">43</sup> כידוע וקבלו התורה פב\"פ כו', כי שרש הס\"ר היו מאברהם שנא' [בו] ואקח אותו מעה\"נ<sup data-n=\"1708\">44</sup> ונק' אברהם העברי<sup data-n=\"1709\">45</sup>. והענין הוא שהי' נשמתו מלמעלה מן הנה\"ר שיוצא מעדן ונק' עב\"ר הנהר [דעובר] לישנא דאקדומי הוא כמו עובר לעשייתן<sup data-n=\"1710\">46</sup> כו' והוא בחי' ההעלם דעדן סתימאה הנ\"ל דעדיין לא בא בגילוי בנהר כלל, והוא בבחי' עצמ[ו]' אוא\"ס ב\"ה שלמעלה מעלה מכל עיקר ומקור ההשתל' דאבי\"ע כו' שאין שם בחי' מעלה ומטה כלל (והוא בבחי' העיגולים שלמעלה מבחי' יושר כמשל עיגול",[["1694","30","<b>אם זכרתיך על יצועי</b>: תהלים סג, ז. ראה גם לעיל פ' בשלח קצה, ב. לקמן פ' תצוה שיט, ב. ויקהל תג, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680209\" data-slug=\"torat-chaim\" data-id=\"2300680209\">תו\"ח ויחי רמה, ג</a> ובהערה 18."],["1695","31","<b>דדוד הי' מרכבה</b>: ראה פרדס (שער עה\"כ) שכ\"ג, מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["1696","32","<b>ממש</b>: אד: עצמו."],["1697","33","<b>ואלה הגבורים אשר לדוד</b>: שמו\"ב כג, ח [ושם: אלה שמות הגבורים]. דהי\"א יא, י [ושם: ואלה ראשי הגבורים]. שם, יא [ושם: ואלה מספר הגבורים]. מאמרי אדה\"א ויקרא ח\"א ע' ריב. דרושי חתונה ח\"ב ע' תקס. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680209\" data-slug=\"torat-chaim\" data-id=\"2300680209\">תו\"ח ויחי רמה, ג</a>. לקמן פ' תצוה שיט, סע\"ב."],["1698","34","<b>אשר יעזרו לדוד </b>[א: ליתא]<b> בלא לב ולב</b>: דהי\"א יב, לג [ושם: ולעדר בלא לב — ראה מאמרי אדה\"א בראשית ע' כ. דרושי חתונה־ ויקרא שם]. ראה גם לעיל פ' בשלח קצה, ב. לקמן פ' תצוה שיט, ב."],["1699","35","<b>ובשכבך ובקומך</b>: ואתחנן ו. ז. עקב יא, יט. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. לעיל פ' תצוה שם. לקמן פ' ויקהל תג, א."],["1700","36","<b>בעבה\"נ ישבו אבותיכם</b>: יהושע כד, ב. ראה זהר אמור צט, א."],["1701","37","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1702","38","<b>פנימי' בינה. . מפנימי' ע\"י</b>: ראה גם הנסמן לעיל פ' יתרו רסט, ג."],["1703","39","<b>עדן סתימאה</b>: ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["1704","40","<b>עדן. . עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["1705","41","<b>חטא אדה\"ר. . התערובות טו\"ר</b>: ראה לעיל פ' שמות מ, ב. וש\"נ."],["1706","42","<b>מרפ\"ח ניצוצי'</b>: נסמן לעיל ערב, סע\"ד."],["1707","43","<b>בס\"ר נש\"י. . נהר נילוס</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' עב. וש\"נ. תו\"ח ח\"ש קכא, ג ובהערה 40. לעיל הערה 41."],["1708","44","<b>ואקח אותו מעה\"נ</b>: יהושע כד, ג [ושם: ואקח את אביכם את אברהם מעבר הנהר]."],["1709","45","<b>אברהם </b>[ד: אברם]<b> העברי</b>: לך יד, יג."],["1710","46","[דעובר]<b> לישנא דאקדומי הוא. . עובר לעשייתן</b>: פסחים ז, ב."]]],[2300550178,"כדור הארץ<sup data-n=\"1711\">47</sup> שאין בו מעלה ומטה<sup data-n=\"1712\">48</sup> שהרי השוכני' בכדור הארץ מתחת רגלינו לא יפלו למטה כו' כי הכל שוין בו, משא\"כ בבחי' היושר שבציור <span data-k=\"pg\">תכז</span> ּ אדם יש בו חילוקי מדריגות ראש ורגל כו' וד\"ל. ועוד יובן זה מענין הידיעה והשגחה כללי' מבחי' ד\"ע וד\"ת הוא השגחה אלקי' שבא בסדר השתלשלו' מע\"ס דאצי' או\"כ עד למטה שעיניו משוטטות<sup data-n=\"1713\">49</sup> כו' ועיניו פקוחות<sup data-n=\"1714\">50</sup> [ע]ל כל [כו'], אבל שתיהם<sup data-n=\"1715\">51</sup> הידיעה וההשגחה שוה מה שיודע ומשגיח על האדם השפל עם מה<sup data-n=\"1716\">52</sup> שיודע ומשגיח בעולמות העליונ[י'] בגעה\"ע ותחתון שוה ומשוה קטן וגדול כולם נסקרי' כא' נשמות בג\"ע עם הדצ\"ח הגשמי, אין זאת מידיעה שבאה בהשתלשלו' אלא באה מידיעה [דד\"ע] שלמעלה מעלה מסדר ההשתל' דאבי\"ע שקטן וגדול שוין ממש והוא בחי' העיגולים שאין שם מעלה ומטה כלל. וזהו לפניך [ממש] נגלו כל תעלומות<sup data-n=\"1717\">53</sup> וסתרי כל חי בשוה מגדול ועד קטן שבקטנים כו' וד\"ל, ושם נאמר אדם ובהמה תושיע ה'<sup data-n=\"1718\">54</sup> אדם ובהמה בשוה ממש תושיע בלי הפסק<sup data-n=\"1719\">55</sup> כלל בין אדם לבהמה ששוה ומשוה קטן וגדול כנ\"ל.\n<b>וזהו</b> כי תקנה ע\"ע הוא הנשמה אלקי' שנק' עברי שבא מעב\"ר הנה\"ר שיוצא מעדן שישראל עלו במח'<sup data-n=\"1720\">56</sup> סתימאה בעדן הנ\"ל, וזהו כי תקנה בבחי' הקנין שבא יבא מן ההעלם לגילוי בלבד כי כבר הי' הנה\"א<sup data-n=\"1721\">57</sup> בעב\"ר הנהר רק שיומשך מהעלם לגילוי בלבד הוא ע\"י משה דוקא, כי הנה שרש נשמת משה הוא מן המ\"ע כו' כמ\"ש [בו] כי מן המים משיתיהו<sup data-n=\"1722\">58</sup>. והענין הוא כמ\"ש יהי רקיע בתוך המים<sup data-n=\"1723\">59</sup> כו' שהוא הבדלה בין מ\"ע דתהו למ\"ת דתיקון וזהו כענין עבר הנהר, שהנהר הוא הנמשך בגילוי מן ההעלם ומ\"ע שמעל לרקיע הוא בבחי' העיגולים דתהו שאין בהם מעלה ומטה ושום התחלקות [ו]שם שוין קטן וגדול כנ\"ל שכולם שם בתכלית הביטול דמ\"ה בתכלית. וזהו כי מן המים משיתיהו שעיקר טעם קריאת שם משה אינו ע\"ש המים עצמן אלא ע\"ש המש[י]כה מן המ\"ע כו', וכתרגומו משיתיהו שחלתי'<sup data-n=\"1724\">61</sup> כו', והוא שמיטת החסד<sup data-n=\"1725\">60</sup> שקדמה לשמיטה זו שאנו בה כמ\"ש בס' התמונה<sup data-n=\"1726\">62</sup> ובלשון המקובלים האחרוני' נק' בשם תהו ותיקון והכל ענין א' וב' נשמות דחנוך ומשה<sup data-n=\"1727\">63</sup> ירדו מעולם התהו לעולם התיקון כו'. וע\"כ יש ביכולת משה להשפיע לכל א' מישראל גם בפחות שבפחותים שיהי' בבחי' הדעת דאדם שנק' זרע אדם כו' ולאהפכא חשוכא לנהורא בפנימי' המדות דאוי\"ר כנ\"ל לפי ששם שוין קטן וגדול, וזהו אשר תשים אתה דוקא לפי",[["1711","47","<b>עיגול כדור הארץ</b>: נסמן לעיל פ' בשלח רמ, א."],["1712","48","<b>כדור הארץ שאין בו מעלה ומטה</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעה וע' תעז."],["1713","49","<b>שעיניו משוטטות</b>: דהי\"ב טז, ט. זכרי' ד, י."],["1714","50","<b>ועיניו </b>[ אד: ועיניך]<b> פקוחות</b>: ירמי' לב, יט."],["1715","51","<b>שתיהם</b>: אד: שתהי'."],["1716","52","<b>מה</b>: שם: הידיעה."],["1717","53","<b>לפניך. . נגלו כל תעלומות</b>: מוסף לר\"ה (ברכת זכרונות)."],["1718","54","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז."],["1719","55","<b>הפסק</b>: אד: הפרש."],["1720","56","<b>שישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב."],["1721","57","<b>הנה\"א</b>: אד: הנשמה האלקית."],["1722","58","<b>משה. . המ\"ע. . כי מן המים משיתיהו</b>: שמות ב, י. ראה לעיל פ' שמות מג, א. וש\"נ."],["1723","59","<b>יהי רקיע בתוך המים</b>: בראשית א, ו."],["1724","61","<b>וכתרגומו משיתיהו שחלתי'</b>: ת\"א שמות ב, י."],["1725","60","<b>משה. . שמיטת החסד</b>: ראה לעיל מג, ד ואילך. א, ג. וש\"נ."],["1726","62","<b>בס' התמונה</b>: נסמן לעיל מג, א."],["1727","63","<b>וב' נשמות דחנוך ומשה</b>: ראה לעיל מג, ד ואילך (ובהנסמן בריש המאמר שם). רעט, א."]]],[2300550210,"שמשה הוא המשפיע וממשיך לכ\"א מבחי' ד\"ע כנ\"ל הטעם. ולזה א' כי תקנה לשון יחיד שקנין זה הוא ע\"י משה דוקא, וזהו בב' אופנים א' מצד הנשה\"א<sup data-n=\"1728\">64</sup> שכבר היתה בעה\"נ כנ\"ל וא\"צ רק להביא' משם מן ההעלם לגילוי, והב' מצד הגוף שמסתיר על הנשמ' [ו]נק' בהמה שבאדם [הנה] גם בזה נמשך הדעת דאדם, להיות מזרע בהמה זרע אדם ע\"י המשכת מזון העשב כנ\"ל שהוא ג\"כ ע\"י משה כמ\"ש ונתתי עש\"ב בשד\"ך לבהמת\"ך<sup data-n=\"1729\">65</sup> כו', וקנין זה הוא שמביא מעולם הפירוד לעולם היחוד. וזהו פי' הפשוט דכי תקנ\"ה ע\"ע דישראל [נק'] עבדים<sup data-n=\"1730\">*66</sup> מצד הגוף ונק' בנים מצד הנשמה ששרשה בעה\"נ מטעם הנ\"ל דעלו במח' כו' וזהו פי' ע\"ע, וכי תקנה קאי על שניהם רק שהנשמה נקנית מן ההעלם דאוא\"ס בעצמו מלמעלמ\"ט ומה שנק' עבד מצד הגוף [נ]קנה מלמטלמ\"ע <span data-k=\"pg\">856</span> ּ והכל א' דמה שיש כח ועוז לבהמה להיות באדם זהו בא רק מצד שרש הנשמה בעה\"נ ששם אדם ובהמה שוין. וזהו שאנו רואים שיש כח גדול בנשמה יותר מן המלאך שהנשמה יכול[ה] לירד בגוף גשמי ולהפוך חשך לאור משא\"כ המלאך כידוע בענין הנפילים [היו<sup data-n=\"1731\">66</sup> כו'] מפני שהמלאך בחי' בריאה יש מאין בדבור שאין בכחו רק לפ\"ע הצמצום במדה כו', אבל הנשמה גם בירידתה בחשך החומרי אין בה שינוי מכמו שהיתה במקורה להיותה באה רק<sup data-n=\"1732\">67</sup> בבחי' קנין מרשות לרשות לבד כו' וד\"ל. ונמצא יש כאן ב' טעמים לענין דכי תקנה ע\"ע כו', [ה]א' מצד נש\"י ששרשם למעלה [מ]עבה\"נ [ששם שוין קטן וגדול אדם ובהמה כו'. והב' מצד משה עצמו שהוא נמשך מן המ\"ע דהיינו ג\"כ מבחי' התהו שקדם הרבה לעולם התיקון<sup data-n=\"1733\">68</sup> והוא בחי' העיגולי' הנ\"ל] ששם שוין קטן וגדול כו'. וב' הטעמים כא' טובים והכל א' דמשום ב' הטעמים [הללו] א' למשה דוקא אשר תשים אתה לפניהם מבחי' הדעת עד הקטן שבהם וזהו כי תקנה ע\"ע אתה הקונ\"ה, ולכך לא א[מר] כי יקנ\"ו לשון רבים משום דארישא קאי אאשר תשים ולא אלפניהם [דסמיך לי'] כנ\"ל וד\"ל.\n<b>שש</b> שנים יעבוד, פי' שש שנים היינו שיתא א\"ש דהוי עלמא<sup data-n=\"1734\">69</sup> כו', וביאור הענין הנה כתיב ואברהם זקן בא בימים<sup data-n=\"1735\">70</sup> ופי' בזהר באינון יומין עילאין שהן בחי' הלבושי' כו' ע\"ש. ולהבין הטעם שהימים נק' לבושי', הנה כתיב והיתה נפש אדוני<sup data-n=\"1736\">71</sup> צרורה בצרור החיים, פי' צרור היינו כמו עד\"מ הצרור שצוררים הכסף בכיס של עור לשמירה כו', כך כל נשמה אלקי' יש לה לבוש זך",[["1728","64","<b>הנשה\"א</b>: אד: הנשמה האלקית."],["1729","65","<b>ונתתי עש\"ב בשד\"ך לבהמת\"ך</b>: עקב יא, טו."],["1730","*66","<b>דישראל [נק'] עבדים</b>: ראה גם סידור שחרית נג, סע\"ב ואילך. שע\"ת יב, סע\"ב. לקמן פ' ויקהל תו, ד."],["1731","66","<b>הנפילים [היו</b>: בראשית ו, ד. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשס ובנסמן במ\"מ לשם."],["1732","67","<b>רק</b>: אד: ליתא."],["1733","68","<b>התהו שקדם. . התיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ."],["1734","69","<b>שיתא א\"ש דהוי עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["1735","70","<b>ואברהם זקן בא בימים</b>: ח\"ש כד, א. ראה זהר שם קכט, א. ויחי רכד, סע\"א. לעיל פ' בשלח קעו, א. וש\"נ."],["1736","71","<b>והיתה נפש אדוני</b>: שמו\"א כה, כט. ראה אגה\"ק סכ\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380518\" data-slug=\"likkutei-torah\" data-id=\"4001380518\">לקו\"ת שלח נא, ג</a>. הנסמן בהערה 1."]]],[2300550242,"שנק' צרור החיים שתצרר בו ותתעלם שעי\"ז תוכל לקבל אור [ו]זיו השכינה בג\"ע מפני שא\"א שתשיג אור האלקי כמות שהיא<sup data-n=\"1737\">72</sup> בלי מסך ולבוש המסת[י]ר ואם הי' מסתיר לגמרי לא הי' זה<sup data-n=\"1738\">73</sup> השגה כלל, אלא הענין הוא דזה הלבוש הוא לבוש זך ובהיר שע\"י תראה ותשיג אור אלקי כמו עד\"מ שא\"א להסתכל באור צח ובהיר ביותר כ\"א ע\"י לבוש ומסך זך כו'. וזהו הלבוש שנעשה ממעשה המצות בעוה\"ז דוקא כמו ממצות הצדקה להחיות רוח שפלים<sup data-n=\"1739\">74</sup> כו' וכתיב והלך לפניך צדקיך<sup data-n=\"1740\">75</sup> כו' שנעשה לבוש צח שתלביש בו הנשמה וכה\"ג כל התו\"מ שנעשי' בעוה\"ז דוקא מבירורי' דרפ\"ח כו', וכל יום ויום שעושה מצוה א' מן המצות נק' ימים אלה בשם לבושין כי הימים באים מלמעלה מן הזמן בתוך הזמן לברר בכ\"י ויום מרפ\"ח ניצוצין כו', וכל יום שאין בו מעשה מצות לא נעש[ה] בו בחי' לבוש וז\"ש ימים יוצרו ולא אח\"ד בהם<sup data-n=\"1741\">76</sup> כו' וכמ\"ש במ\"א. וז\"ש ואברהם זקן בא בימים ביומין עילאין שבאי' בזמן הי' בהם יחו\"ע דמעשה המצות ברוחני' שאאע\"ה קיים כל התומ\"צ<sup data-n=\"1742\">77</sup> ברוחניות וכמ\"ש עקב אשר שמע אברהם בקולי<sup data-n=\"1743\">78</sup> כו' וכמ\"ש במ\"א. וכך יובן גם כאן במ\"ש שש שנים יעבוד הע\"ע הנ\"ל, דהנה הע\"ע יצא מן ההעלם דעצמו' דא\"ס ב\"ה לידי גילוי בבחי' קנין כנ\"ל ולמה יצאו מעה\"נ, היינו כמו שרשם הראשון אברהם שהי' כל ימיו בעבודת הבירורי' דרפ\"ח כו' כך בכל נשמה בפרט שנק' עברי ונק' עבד עבודתו בכל יום לעשות מצות שנק' לבושי' כנ\"ל. וזהו שש שנים יעבוד הע\"ע והן וא\"ש דהוי עלמא כידוע שהן ו' יומין<sup data-n=\"1744\">79</sup> עילאין דאצי' בלבד שכלולין בהם כל הדורות מאדם עד משיח <span data-k=\"pg\">תכח</span> ּ ועוה\"ב וכל נשמה לפי מספר ימיו הקצובים לו בוא\"ש [י]עשה לבושי' ממצות מעשיות שזהו כל עיקר כוונת המאציל ב\"ה וד\"ל.\n<b>ופי'</b> יעבוד עבודה זו ל' תיקון וע\"ע הנ\"ל יתקן אותו כמו עורות עבודים<sup data-n=\"1745\">80</sup> כו' שהוא להלבין קליפת העור כו', והענין הוא כידוע דהמצות מעשיות נעשים למטה בדברים גשמי' בק\"נ כמו במצות טלית ותפילין בצמר וקלף גשמי וכה\"ג כל המ\"ע, ואע\"פ שזהו רצה\"ע ממש ונק' מצות ה' ממש, עכ\"ז כדי שיעלו לה' למעלה להיות בבחי' כלי ממש לגילוי אור האלקי עד שיהיו נק' מצותיו ממש כמ\"ש אשר קדשנו במצותיו<sup data-n=\"1746\">81</sup> שיהי' נק' מצות ה' ממש כו' והוא בבחי' רמ\"ח אברים דמלכא כידוע ברמ\"ח פקודין<sup data-n=\"1747\">82</sup> דמ\"ע כו', הנה צריך תחלה לעבוד ולתקן אותם דהיינו להיות מופשטים מבחי' גשמיות דנוג\"ה מכמו שהן למטה בהתלבשות הגשמיי' (ואפי' מצות אהוי\"ר שבלב ומצות",[["1737","72","<b>כמות שהיא</b>: אד: כמו שהוא."],["1738","73","<b>זה</b>: שם: ליתא."],["1739","74","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["1740","75","<b>והלך לפניך צדקיך</b>: ישעי' נח, ח."],["1741","76","<b>ימים יוצרו. . בהם</b>: תהלים קלט, טז. ראה לעיל פ' יתרו רעו, ג. וש\"נ."],["1742","77","<b>שאאע\"ה קיים כל התומ\"צ</b>: ראה יומא כח, ב."],["1743","78","<b>עקב אשר שמע אברהם בקולי</b>: תולדות כו, ה."],["1744","79","<b>וא\"ש. . ו' יומין</b>: ראה רמב\"ן בראשית ב, ג. מאמרי אדה\"א דברים ח\"א ע' רז. וש\"נ."],["1745","80","<b>עבודה. . עורות עבודים</b>: נסמן לעיל פ' יתרו רסח, ב."],["1746","81","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא."],["1747","82","<b>רמ\"ח אברים. . ברמ\"ח פקודין</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."]]],[2300550273,"יחו\"ע ויחו\"ת שבק\"ש בהשגה שבמוח צריך ג\"כ הפשטה מגשמיות דמוח ולב כשיעלה למעלה וכן מצות ת\"ת שלמטה כו'). וזהו הנק' עיבוד ותיקון, ובמה הם מתתקנים ומזדככים ה\"ז בא ע\"י העלאת אהוי\"ר בעבודה שבלב זו תפלה<sup data-n=\"1748\">83</sup> דוקא שעי\"ז עולין כל המצות שעושין כל היום בהזדככות וליבון מגשמיות לרוחניות עד רום המעלות, לפי שהאהוי\"ר נק' גדפין<sup data-n=\"1749\">84</sup> עד\"מ כנפי העוף שפורחים בהם למעלה ותומ\"צ נק' גופא כנ\"ל וכמו שבגדפין מגביהי' ומעלי' את גוף [העוף] כך אוי\"ר מעלין למצות כו' (והוא בחי' הכוונה ורעו\"ד שיש בכל מעשה המצות מחמת העבודה שבלב שנשאר רושם על כל היום בעשותו המצוה שבזה עולין מגשמי' ויעלו לרצון לפני ה', או ע\"י האוי\"ר של יום המחר עולין כל המעשה מצות<sup data-n=\"1750\">85</sup> שעשה אתמול בגדפין שמעלין בו, ואמנם גם מצות אהוי\"ר עצמן צריך תיקון כנ\"ל). וזהו כעדר הרחלים שעלו מן הרחצה<sup data-n=\"1751\">86</sup> כו', פי' עד\"מ עדר הרחלים שצמרם מתטנף ואינם ראוים ללבוש כמו [שהן מפני הילוכם במקומות המטונפים הרי הרועה הנאמן מוליכם למי הנהר להרחיצם היטב עד שיהיו כמו] צמר נקי ב\"י<sup data-n=\"1752\">87</sup> כו'. וכך הנמשל בנשמות<sup data-n=\"1753\">88</sup> שנק' צאן<sup data-n=\"1754\">89</sup> כמ\"ש אז תעבורנה הצאן<sup data-n=\"1755\">90</sup> ע\"י מונה שהנשמה בעוה\"ז אע\"פ שעשתה כמה מצות מפני שהוא בגשמיות דק\"נ בעולם השפל החומרי צריך רחיצה במים עליונים ע\"י הרועה הנאמן שהוא בחי' משה רע\"מ<sup data-n=\"1756\">91</sup> שהוא ממשיך הדעת לכנ\"י ממקורו שנא' בו כי מן המים משיתיהו ממ\"ע דבחי' עיגולי' כנ\"ל, וזהו שעלו מן הרחצה. אך עיקר הרחיצה ע\"י האהבה שנמשך כמים בעבודה שבלב זו תפלה דוקא, ואע\"פ שתפלה דרבנן<sup data-n=\"1757\">92</sup> וק\"ש דאוריי' האהוי\"ר שבלב מרחיצין יותר מטעם הנ\"ל ששרשן בבחי' מ\"ע דמשה לפי שנתחב\"ס וסוב\"ת<sup data-n=\"1758\">93</sup> דוקא, ובאוי\"ר שבא במעשה דוקא הוא נק' סוף הכל וכמ\"ש סו\"ף דבר כו' את האלקי' ירא ואת מצותיו שמור<sup data-n=\"1759\">94</sup> בפו\"מ וסוף דבר זה נעוץ בתחלת הכל שהוא בחי' מ\"ע דמשה שלמעלה מעלה מכל ההשתל' ע\"כ הם מלבנים ביותר וד\"ל.\n<b>וזהו</b> כי תקנה ע\"ע דקאי במשה שהוא הקונה מהעלם דעצמו' המאציל לגילוי והוא אשר ממשיך בחי' הד\"ע בכל נפש מישראל שיהי' בבחי' אדם ונק' עבד להיות עבודתו בכל יום ויום לתקן ולעשות מצות שנק' לבושים כנ\"ל באברהם שנק' עבדי<sup data-n=\"1760\">95</sup> שבא בימים שהן הלבושי', וע\"כ א' למשה כי תקנה ע\"ע לעשות לבושין דמצות שש שנים שהן וא\"ש הכוללי' כל הימים <span data-k=\"pg\">858</span> ּ ולבושי' דמצות יעבוד בעבודה שבלב לתקן ולהעלות",[["1748","83","<b>בעבודה שבלב זו תפלה</b>: ראה תענית ב, א. לעיל פ' בשלח קסב, א הערה 13."],["1749","84","<b>שהאהוי\"ר נק' גדפין</b>: ראה תניא פ\"מ. מאמרי אדה\"א בראשית ע' עה. וש\"נ."],["1750","85","<b>המעשה מצות</b>: אד: המצות."],["1751","86","<b>כעדר הרחלים שעלו מן הרחצה</b>: שה\"ש ו, ו."],["1752","87","<b>ב\"י</b>: ד: בן יומו."],["1753","88","<b>בנשמות</b>: אד: בנש\"י."],["1754","89","<b>בנשמות שנק' צאן</b>: ראה גם מאמרי אדה\"ז תקס\"ה כאן (ע' רנח נוסחא שני'). שע\"ת נז, א."],["1755","90","<b>אז תעבורנה הצאן</b>: ירמי' לג, יג [ושם: עוד תעבורנה — ראה גם לעיל פ' וארא סח, א. וש\"נ]."],["1756","91","<b>משה רע\"מ</b>: ראה זהר וירא קו, א. לעיל פ' וארא עז, ב. וש\"נ."],["1757","92","<b>שתפלה דרבנן</b>: ראה שו\"ע אדה\"ז הל' תפלה סק\"ו, ס\"ב. הנסמן לעיל פ' בא קכ, ג."],["1758","93","<b>שנתחב\"ס וסוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["1759","94","<b>סו\"ף דבר. . שמור</b>: קהלת יב, יג."],["1760","95","<b>עבדי</b>: אד: עברי."]]],[2300550301,"אותם מגשמיות שיעלו למעלה [מעלה] דסוף מעשה עבמ\"ת כו'. ודוקא ע\"ע זה יעבוד הו\"ש<sup data-n=\"1761\">96</sup> הללו ולא זולתו שאינו ע\"ע לפי ששרשו בעה\"נ הנ\"ל שהוא בחי' מ\"ע דבחי' משה ע\"כ ביכולתו לרחוץ ולתקן את הלבושים דמצות שנעשו בעוה\"ז השפל משום דנתב\"ס וסוב\"ת כנ\"ל וד\"ל. [(וז\"ש ביום ההוא יצאו מ\"ח<sup data-n=\"1762\">97</sup> כו' דמ\"ת שבאים בבירורי' דמצות יעלו למע' הנ\"ל)].\n<b>ובשביעית</b> יצא לחפשי חנם בלא מצות<sup data-n=\"1763\">98</sup> כו', הנה ידוע דכל העלאת מ\"ן והמשכת מ\"ד שזהו הנק' אתעדל\"ת ואתעדל\"[ע]<sup data-n=\"1764\">99</sup> לא שייך רק בבחי' האחרונה שבעצמו' אוא\"ס ב\"ה שנמשך אחר הצמצום דקו\"ח שבא לכלל שפע עכ\"פ להיות מקור לכל [ה]השתל' דאבי\"ע וכידוע בפי' משובח ומפואר עדי עד שמו הגדול שזהו בחי' מל' דא\"ס<sup data-n=\"1765\">100</sup> כנ\"ל<sup data-n=\"1766\">101</sup>, אבל במהו\"ע דא\"ס עצמו שהוא מובדל ומרומם לבדו ונק' יחיד כו' שלמעלה מעלה גם מהיות בחי' מקור למקור להיות בחי' חיי העולמים לא שייך לומר ענין העלאת מ\"ן כו', שכל העלאות הוא לעורר ע\"י מעשה התחתונים בחי' חפץ חסד הראשון ובמהו\"ע ממש שלמעלה מזה אין העלאת מ\"ן מאתעדל\"ת במעשה התחתונים מגיע לשם כלל וכמ\"ש אם צדקת מה תתן לו<sup data-n=\"1767\">102</sup> כו', שגם המצות לא יגיעו לשם אע\"פ שהן פנימי' רצונו שמפני רוממות העצמ[ו]' ממש אין לקדושת המצות ערך לו כלל וכמ\"ש קדושים תהיו כו' ע\"י המצות יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם<sup data-n=\"1768\">103</sup> שע\"י המצות שאינם תופסים מקום כלל כו', וזהו חנם בלא מצות לפי שהאור המאיר ממהו\"ע נק' מתנת חנם ולא מצד מעשה התחתונים כנ\"ל וד\"ל.\n<b>והנה</b> בכל וא\"ש דהוי עלמא בכל עולם ועולם יש עליות וירידות שנק' העלאת מ\"ן והמשכת מ\"ד מעילה לעילה בלי הפסק [ו]כמו במלאכים דתרגום וקרא זא\"ז ומקבלין דין מן דין<sup data-n=\"1769\">104</sup> כו', וכך בכללות ההשתל' כמ\"ש ילכו מחיל אל חיל<sup data-n=\"1770\">105</sup> כו' שאין מנוחה כלל לנשמות ומלאכים שבכל עולם שעולים מדי יום ומדי שבת וחדש מגעה\"ת לגעה\"ע<sup data-n=\"1771\">106</sup> למעלה מעלה בעא\"ע<sup data-n=\"1772\">107</sup> עד רום המעלות וחוזר ויורד ונמשך אור חדש מלמעלמ\"ט וחוזר ועולה כו' ואין זה נק' מנוחה כלל, וגם ההמשכה היא לפ\"ע ההעלאה דוקא [וההעלאה הוא לפ\"ע ההמשכה] דהא בהא תליא ויחדיו יהיו תמים ואין זה בלא זה שלימות כ\"א בהתאחדותם יחד, דהיינו מאחר שההמשכה אינה באה רק לפ\"ע ההעלאה הרי ההעלאת מ\"ן גורם ההמשכת מ\"ד",[["1761","96","<b>הו\"ש</b>: אד: הו' שנים."],["1762","97","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח."],["1763","98","<b>ובשביעית. . חנם בלא מצות</b>: משפטים כא, ב. ראה גם לעיל פ' שמות א, ב. וש\"נ."],["1764","99","<b>אתעדל\"ת ואתעדל\"[ע]</b>: נסמן לעיל פ' יתרו רנט, ב."],["1765","100","<b>משובח. . שמו הגדול. . מל' דא\"ס</b>: ברכת ברוך שאמר. ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["1766","101","<b>כנ\"ל</b>: ד: כו'."],["1767","102","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["1768","103","<b>קדושים תהיו. . קדושתי למעלה מקדושתכם</b>: קדושים יט, ב. ויק\"ר פכ\"ד, ט. ראה מאמרי אדה\"א בראשית ע' רכו. וש\"נ. שמות ח\"ב ע' תקצד."],["1769","104","<b>וקרא זא\"ז. . דין</b>: ישעי' ו, ג ובת\"י שם."],["1770","105","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["1771","106","<b>ומדי שבת וחדש מגעה\"ת לגעה\"ע</b>: ראה גם לעיל פ' שמות לה, ב. וש\"נ."],["1772","107","<b>בעא\"ע</b>: אד: בעילוי אחר עילוי."]]],[2300550327,"וגם להיפוך מאחר שאין ההעלא' כ\"א לפ\"ע כח המשכת מ\"ד שמעלה מ\"ן כו' והמ\"ן מקבל ממ\"ד כו' הרי זה כמו מבלי שימצא ראש וסוף<sup data-n=\"1773\">108</sup> מאחר שהסוף משפיע לראש וראש לסוף כו' כי רק בהתאחדם יחד יש להם שלימות כו'. וזהו פי' ומקבלין דין מן דין כו' לא שזה מקבל מזה לבד אלא שכ\"א משפיע לזולתו וכן זולתו משפיע לו נמצא שניהם משפיעים ושניהם מקבלים מבלי שימצא מי הוא המשפיע ומי הוא המקבל מאחר שמקבלים זמ\"ז כו'. וכמו\"כ יובן בענין המצות דמבואר לעיל דתפלה באוי\"ר מלבנין מעשה המצות שזהו לפ\"ע הזדככות הלב ומוח במס\"נ בתפלה כן יהי' ערך המשכת גילוי אור אלקי בתומ\"צ שיעשה כל היום בהזדככות יותר, הרי לפ\"ע התפלה כן ערך <span data-k=\"pg\">תכט</span> ּ התומ\"צ שנמצא תו\"מ מקבל מן התפלה וכן להיפך שלפ\"ע המשכת אור בהיר בהזדככות בתומ\"צ כמו בכוונה ורעו\"ד כן יהי' ערך הזדככות הלב ומוח במס\"נ בעבודה שבלב זו תפלה דהא בהא תליא הרי התפלה מקבל מן התומ\"צ, ונמצא שמקבל[ין] דין מן דין [כנ\"ל] בהעלאת מ\"ן והמשכת מ\"ד שאין לזה בלא זה שלימות ולכך האומר אין לי אלא תורה<sup data-n=\"1774\">109</sup> אפי' תורה אין לו ולהיפך בתפלה בלא תומ\"צ כו' וד\"ל.\n<b>והנה</b> ידוע שבכל יום ויום מתחדשים כל העולמות [ב]חידוש האור והשפע אלקי' בבחי' יחו\"ע דמ\"ד ומ\"ן חדש שלא הי' כמוהו שהוא מפני חידוש הבירורי' דרפ\"ח כו' שמתחדשים בכל יום כמ\"ש בזהר ע\"פ מצמיח חציר לבהמה<sup data-n=\"1775\">110</sup> שהן אלף טורין כו', והיינו ענין עליות חדשות בכל יום ומדי חדש ושבת כו' ובכל שנה בכלל ובפרט הכל דרך עא\"ע<sup data-n=\"1776\">111</sup> בהתחדשו' תוס' אורות עליונים בריבוי מדרגות ואופנים שונים כו' וזהו ילכו מחיל אל חיל כו' שאין זה בחי' מנוחה כלל כנ\"ל. וזהו שש שנים יעבוד וא\"ש דהוי עלמא<sup data-n=\"1777\">*112</sup> שלא נק' מנוחה כלל, אבל באלף הז' יהי' מנוחה<sup data-n=\"1778\">112</sup> לחיי העולמים כידוע, ולכך נק' אלף הז' יום שכולו שבת<sup data-n=\"1779\">113</sup>. והענין הוא כידוע שיש ב' מיני מנוחה א' מנוחה שאחר המלאכה שאין זה מנוחה עצמי' רק ששובת ממלאכ[תו] בלבד וזהו שבתות דעכשיו, ולא תאמר שכך הוא בוא\"ש שהן ו' יומין עילאין דאצי'<sup data-n=\"1780\">114</sup> כמ\"ש כי אלף שנים בעיניך<sup data-n=\"1781\">115</sup> כיום אתמול שאלף הז' נק' יום השבת כשבתות דעכשיו שנק' מנוחה ממלאכתו בכללו', אלא הענין הוא דאלף הז' נק' מנוחה לחה\"ע כמנוחה עצמי' שלא מן המלאכה כלל והיינו שלא יהי' עוד ירידות ועליות<sup data-n=\"1782\">116</sup> כלל. והוא להיות שיהי' אז גילוי אור העצמי' דא\"ס שלמעלה ממקור חיי העולמים לגמרי שאין המצות מגיעים",[["1773","108","<b>מבלי שימצא ראש וסוף</b>: ע\"פ קהלת ג, יא."],["1774","109","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב. לקמן פ' תצוה שנ, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670436\" data-slug=\"torat-chaim\" data-id=\"2300670436\">תו\"ח בראשית כו, ג</a> ובהערה 34. שע\"ת עג, ג."],["1775","110","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד. ראה זהר בראשית יח, ב. לעיל פ' בא צג, א. וש\"נ."],["1776","111","<b>עא\"ע</b>: אד: עלי' אחר עלי'."],["1777","*112","<b>שש שנים יעבוד וא\"ש דהוי עלמא</b>: נסמן לעיל רעח, ד."],["1778","112","<b>באלף הז' יהי' מנוחה</b>: ראה גם לעיל פ' בשלח רכא, ב ואילך. וש\"נ."],["1779","113","<b>מנוחה לחיי העולמים. . יום שכולו שבת</b>: סוף תמיד."],["1780","114","<b>עילאין דאצי'</b>: אד: למעלה."],["1781","115","<b>כי אלף שנים בעיניך</b>: תהלים צ, ד."],["1782","116","<b>שלא יהי' עוד ירידות ועליות</b>: ראה גם לעיל פ' שמות מג, ג. וש\"נ."]]],[2300550352,"לשם כלל ולא שייך כלל עליות וירידות, שאין ירידות ועליו' שהוא המשכות והעלאות רק בבחי' מעלה ומטה והוא בבחי' קו\"ח דאבי\"ע כו' וזה שנעשה ע\"י המצות ביחו\"ע דמ\"ד ומ\"נ כנ\"ל, אבל לע\"ל גילוי אור העצמ[ו]' דא\"ס יהי' למטה כמו למעלה ממש בשוה כו' ואיך יתכן ל' עלי' מלמטלמ\"ע או [ירידות] מלמעלמ\"ט. וע\"כ לא יהי' עוד עליות העולמות שהוא ההילוך דילכו מחיל אל חיל כו' וע\"כ יום שכולו שבת, דעכשיו ו' יומין דחול הוא ירידה והמשכה ובשבת שובת שהוא העלי' ובאלף הז' שיהי' המנוחה בבחי' מהו\"ע [ו]לא ממלאכה וירידה כלל ע\"כ נק' יום שכולו שבת. ומה שנק' מנוחה לחה\"ע דחיי העולמים הוא מל' דא\"ס שיורד ועולה לפ\"ע העלאת מ\"ן במעשה התחתונים ולע\"ל שיהי' מנוחה למל' דא\"ס כאשר יתגלה בחי' אור העצמיו' ממש ויבא לכלל מנוחה העצמי', ובכל שבת יש מעין יום הז' שכולו שבת<sup data-n=\"1783\">117</sup> כו' וד\"ל.\n<b>וזהו</b> ובשביעית יצא לחפשי חנם היינו באלף הז' שזהו יום<sup data-n=\"1784\">118</sup> מנוחה לחה\"ע אז יצא גם הע\"ע הנ\"ל חפשי חנם חפשי מעבודתו לתקן ע\"י מעשה המצות בעליות וירידות כי א\"צ שם תיקון זה לעורר למעלה בחי' חפץ חסד כי יתגלה בו אור העצמ[ו]' א\"ס למטה <span data-k=\"pg\">860</span> ּ כמו למעלה שאין אתעדל\"ת מגיע לשם כלל כנ\"ל, כך בהתגלות בחי' העצמו' למטה א\"צ לאתעדל\"ת במצות כלל וזהו עוה\"ב ונק' חיי עולמים דכתי' יחיינו מיומים<sup data-n=\"1785\">119</sup> בימוהמ\"ש ביום הג' יקימנו כו'<sup data-n=\"1786\">120</sup> בתחה\"מ ונחי' לפניו ממש בעוה\"ב והוא העדן כו', ואע\"פ שעוה\"ב בא בשכר המצות בעוה\"ז דוקא מ\"מ [ב]עוה\"ב נעשה חפשי חנם בלא מצות שהוא לאחר תשלום הבירורים כנ\"ל וד\"ל. ולפ\"ז גם משה שנק' גואל ראשון וגואל אחרון<sup data-n=\"1787\">121</sup> היינו רק לימוהמ\"ש שיהי' התיקון ברוחני' המצות עכ\"פ כמ\"ש הלכתא למשיחא<sup data-n=\"1788\">122</sup>, דמ\"ש במשה כי מן המים משיתיהו דירושתו<sup data-n=\"1789\">123</sup> מבחי' מ\"ע דעגולים לתקן הוא עד סוף אלף הששי שהוא ימוהמ\"ש, אבל בעוה\"ב הוא למעלה מימוהמ\"ש שאז א\"צ תיקון כלל מטעם הנ\"ל וד\"ל.",[["1783","117","<b>ובכל שבת יש. . שכולו שבת</b>: ראה מכילתא תשא לא, יג. לעיל פ' שמות לג, ג. וש\"נ."],["1784","118","<b>שזהו יום</b>: אד: שיהי'."],["1785","119","<b>יחיינו מיומים</b>: הושע ו, ב."],["1786","120","<b>כו'</b>: ד: ליתא."],["1787","121","<b>משה שנק' גואל ראשון וגואל אחרון</b>: ראה שמו\"ר פ\"ב, ד. הנסמן לעיל פ' בא קיח, ג."],["1788","122","<b>הלכתא למשיחא</b>: ראה סנהדרין נא, ב. לעיל פ' שמות כב, ג. וש\"נ."],["1789","123","<b>דירושתו</b>: אד: דירידתו."]]],[2300550051,"<b>בעז\"ה ליל שבת קודש פ' משפטים שנת תקפ\"ו לובאוויץ</b>\n<span data-k=\"pg\">834</span> ּ<b>ואלה</b> המשפטים<sup data-n=\"1790\">1</sup> אשר תשים לפניהם<sup data-n=\"1791\">2</sup> כו', ויש לדקדק למה א' לפניהם דוקא הל\"ל אשר תשים להם ומהו אשר תשים לפניהם שימה זו לפניהם דוקא מה הוא כו'. אך הנה כללות הענין הוא במ\"ש לפניהם דוקא מדבר בבחי' פנים דכנ\"י שהן הנק' פני אדם דוקא וכמ\"ש ופני אדם לארבעתן<sup data-n=\"1792\">3</sup>. ולהבין זה יש להקדים תחלה בענין האבות שהן המרכבה<sup data-n=\"1793\">4</sup> כו' שהן כמו המרכבה דפני ארי' ופני שור ופני נשר<sup data-n=\"1794\">5</sup> שזהו בחי' חג\"ת, כידוע פני ארי' להימין בבחי' החסד<sup data-n=\"1795\">6</sup> ופני שור מהשמאל בבחי' הגבורה<sup data-n=\"1796\">7</sup> ופני נשר הוא קו האמצעי דבחי' ת\"ת<sup data-n=\"1797\">8</sup> שהוא בחי' הרחמים דנשר רחמני<sup data-n=\"1798\">9</sup> הוא כמו כנשר יעיר קנו<sup data-n=\"1799\">10</sup> כו' ובחי' פני אדם כולל כולם<sup data-n=\"1800\">11</sup> וכמ\"ש ופני אדם כו'. וכמ\"כ האבות הן המרכבה העליונה אברהם בבחי' האהבה שהוא בחי' החסד<sup data-n=\"1801\">12</sup> כפני ארי' להימין כו' ויצחק בבחי' פחד ויראה<sup data-n=\"1802\">13</sup> שזהו בחי' פני שור מהשמאל ויעקב בבחי' ת\"ת<sup data-n=\"1803\">14</sup> שהוא הרחמים דפני נשר כו' (וגם פני נשר כלול הוא כמ\"ש ופני נשר לארבעתן<sup data-n=\"1804\">15</sup> כו' שהוא בחי' רחמים דתפארת שכולל לחו\"ג<sup data-n=\"1805\">16</sup> לב' קוין כו' כמ\"ש יעקב אלקי אבי אברהם<sup data-n=\"1806\">17</sup> ופחד יצחק הי' לי כו' כידוע). והיינו ענין ג' רגלים פסח שבועות סוכות וג' תפלות<sup data-n=\"1807\">18</sup> שבכל יום ובכל תפלה אמר<sup data-n=\"1808\">19</sup> אלקי אברהם ואלקי יצחק כו', וידוע הטעם משום דאין קורין אבות<sup data-n=\"1809\">20</sup> אלא לשלשה דוקא ע\"כ אין אומרים בתפלה רק אלקי אברהם כו' ולא אלקי ראובן ושמעון כו' דהשבטים לא נקראו אבות, אע\"פ שלגבי הנולדים הן קרבין יותר מאבות כו' לפי שעיקר השרש הן ג' האבות דוקא. וע\"כ יש בכל א' מישראל מג' מדרגות דאבות כמ\"ש מה יפה ירושתינו<sup data-n=\"1810\">21</sup> כו' ולכך יכול כאו\"א לומר מתי יגיע מעשי<sup data-n=\"1811\">22</sup> למעשה אברהם כו'",[["1790","1","<b>ואלה המשפטים</b>: מיוסד על מאמר ד\"ה זה שנדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קנג. ואיזה הערות מהצ\"צ נדפסו שם בח\"ב ע' תקצז. ראה עוד ע\"ד המאמר להלן ברשימות הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["1791","2","<b>ואלה המשפטים. . לפניהם</b>: משפטים כא, א."],["1792","3","<b>ופני אדם לארבעתן</b>: ראה יחזקאל א, י. לעיל פ' שמות כח, א. וש\"נ. ז: מחק תיבות אלו ועה\"ג נרשם: ודמות פניהם פני אדם. וראה לקמן הערה 290."],["1793","4","<b>האבות שהן המרכבה</b>: נסמן לעיל פ' יתרו רנא, ג."],["1794","5","<b>האבות. . כמו המרכבה דפני. . נשר</b>: ראה זהר (רע\"מ) פינחס רנז, ב."],["1795","6","<b>פני ארי' להימין בבחי' החסד</b>: יחזקאל א, י. ראה פרדס (שער עה\"כ) שכ\"ג, מערכת מרכבה [ושם: גדולה]. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680339\" data-slug=\"torat-chaim\" data-id=\"2300680339\">תו\"ח תולדות קנד, ד</a> ובהערה 75."],["1796","7","<b>ופני שור. . הגבורה</b>: ראה יחזקאל ופרדס שם. מאמרי אדה\"א ויקרא ח\"א ע' יג. וש\"נ. תו\"ח שם ובהערה 76."],["1797","8","<b>ופני נשר. . ת\"ת</b>: ראה ת\"ז ת\"ע (קלג, ב). ז\"ח יתרו לא, ג. פרדס שם מערכת נשר."],["1798","9","<b>דנשר רחמני</b>: ראה ירושלמי פאה פ\"א, ה\"א. לעיל פ' בשלח ריג, ב. וש\"נ."],["1799","10","<b>כנשר יעיר קנו</b>: האזינו לב, יא."],["1800","11","<b>פני אדם כולל כולם</b>: זהר יתרו פ, ב. במדבר קיח, ב."],["1801","12","<b>אברהם. . בחי' החסד</b>: נסמן לעיל פ' יתרו רנט, א."],["1802","13","<b>ויצחק בבחי' פחד ויראה</b>: נסמן לעיל רעח, ב."],["1803","14","<b>ויעקב בבחי' ת\"ת</b>: זהר (ס\"ת) ויצא קנז, ב. שם ח\"ג (תוספות) שב, א."],["1804","15","<b>ופני נשר לארבעתן</b>: יחזקאל א, י."],["1805","16","<b>דתפארת שכולל לחו\"ג</b>: ראה זהר (רע\"מ) צו כח, סע\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670120\" data-slug=\"torat-chaim\" data-id=\"2300670120\">תו\"ח בראשית ח, ג</a> הערה 52."],["1806","17","<b>אלקי אבי אברהם</b>: ויצא לא, מב [בדילוג — נסמן לעיל פ' בא קכז, ג]."],["1807","18","<b>ג' רגלים. . וג' תפלות</b>: ראה גם לעיל פ' בא צד, ב. וש\"נ."],["1808","19","<b>אמר</b>: ד: או'. בדז: ניתוסף: (ו)אלקי אבותינו."],["1809","20","<b>דאין קורין אבות</b>: ברכות טז, ב. ראה גם לעיל פ' וארא סו, א. וש\"נ."],["1810","21","<b>מה יפה ירושתינו</b>: נוסח תפלת השחר. תדא\"ר ספכ\"א."],["1811","22","<b>מתי יגיע מעשי</b>: נסמן לעיל פ' יתרו רנא, ב."]]],[2300550083,"והן ג' מדרגות דאוי\"ר ורחמים שנטוע בנפש כאו\"א כטבעיות ממש.\n<b>אך</b> יש להבין דלמה לא יש בכל א' וא' מדרגות השבטים שהן למטה מן האבות במדרגה שבנקל יותר להגיע למדרגה שלהם ממדרגות האבות שגבוה מאד נעלה מהם כו', אמנם הענין הוא דבאמת אע\"פ שהשבטים למטה מן האבות יש בהם יתרון מעלה מן האבות עצמן עד שאין כל אדם זוכה למדריגתן ומדריגת האבות יכול כל א' לומר מתי יגיע מעשי למעשה כו' וד\"ל (וראי' לזה ממ\"ש ששם עלו שבטים<sup data-n=\"1812\">23</sup> שבטי י\"ה כו' שזהו בחו\"ב<sup data-n=\"1813\">24</sup> דאצי' שלמעלה מבחי' חג\"ת דאבות כו'. ועוד ראי' ממ\"ש למה תתעינו ה' מדרכיך שהוא דרך הוי' דאברהם באהבה ותקשיח לבינו מיראתיך שהוא יראה ופחד דיצחק, אבל שוב למען עבדיך<sup data-n=\"1814\">25</sup> שבטי נחלתיך דוקא שמזה הוראה גמורה שיש כח גדול יותר בשבטים מן האבות שישוב ויתגלה לכנ\"י בעבורם דוקא וד\"ל). והענין הוא בדרך כלל לפי שהאבות הן המרכבה היינו בבחי' פני ארי' ופני שור ופני נשר כו', אבל בחי' פני אדם דכליל כולהו ומקבל מבחי' פני האדם העליון שעל הכסא כידוע זהו דוקא בי\"ב השבטים שהן ד' דגלים<sup data-n=\"1815\">26</sup> שכלולים בד' אותיות דשם הוי' בי\"ב צרופים<sup data-n=\"1816\">27</sup> שבו<sup data-n=\"1817\">28</sup> שזהו עיקר בחי' אדם כידוע, וע\"כ לא הכל זוכים למדריג' האדם העליון ולא בכל אדם הוא להיות בדומה לעליון ממש כו'. אבל בחי' פני<sup data-n=\"1818\">29</sup> המרכבה דפני ארי' ושור ונשר ישנו בכאו\"א והן <span data-k=\"pg\">תיז</span> ּ אוי\"ר ורחמים דאבות הנ\"ל ואמנם אין זה עדיין בבחי' צלם אלקים דפני אדם כו' (וזהו שנק' שבטי י\"ה וכן שוב למען עבדיך שבטי נחלתיך כו'). ויובן זה בדוגמא במה שמצינו בק\"ש בפ' ואהבת כו' שהן ג' אהבות דבכל לבבך ובכל נפשך ובכל מאדך<sup data-n=\"1819\">30</sup> והן ג' מדרגות דאבות הנ\"ל שהן המרכבה דפני ארי' כו' ועכ\"ז אין זה בחי' [פני] אדם עד אחר התפלה כו'.\n<b>וביאור</b> הענין הנה ג' אהבות הנ\"ל ידוע דכל לבבך היינו בשני יצריך<sup data-n=\"1820\">31</sup> להפוך חום אש זרה דתאוות החומריות שבוער בלב בחלל השמאלי בהתקשרות עמוקות ברצונות הזרות מאד כידוע, ולהיות מואס בהם בתכלית ולא יחפוץ בחיי הבלי תענוגי עוה\"ז ויסלק ויבטל כל הרצון שלו בעיקרו ושרשו מכל תאות חומריות ויהי' רצונו האמיתי רק לה' לבדו שנק' לב א'",[["1812","23","<b>ששם עלו שבטים</b>: תהלים קכב, ד. ראה גם לעיל קכז, ד."],["1813","24","<b>י\"ה. . בחו\"ב</b>: ראה זהר (אד\"ז) האזינו רצ, ב. אגה\"ת פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' שסו וע' תרנו."],["1814","25","<b>למה תתעינו. . ותקשיח לבינו. . שוב למען עבדיך</b>: ישעי' סג, יז [ושם: תקשיח]."],["1815","26","<b>בי\"ב השבטים שהן ד' דגלים</b>: ראה במדבר פ\"ב."],["1816","27","<b>בי\"ב השבטים שהן. . הוי' בי\"ב צרופים</b>: ראה רקאנטי תצוה כח, ב. לעיל פ' שמות כא, ד. וש\"נ."],["1817","28","<b>דשם הוי' בי\"ב צרופים שבו</b>: ראה גם לעיל פ' שמות כ, ג. וש\"נ."],["1818","29","<b>פני</b>: בד: ליתא."],["1819","30","<b>ואהבת. . ובכל מאדך</b>: ואתחנן ו, ה."],["1820","31","<b>דכל לבבך היינו בשני יצריך</b>: נסמן לעיל פ' יתרו רנד, ב."]]],[2300550115,"לאביו שבשמים<sup data-n=\"1821\">32</sup>, וזהו בכל לבבך ביראה ופחד בעול מ\"ש [שלימה] ברצון כו' שזהו בחי' פני שור שבמרכבה כו' שהוא שרש גם לנה\"ב<sup data-n=\"1822\">33</sup> ונהפוך הרצון הזר שבנה\"ב להיות רק לה' לבדו כביטול פני שור העליון כו' וד\"ל. וידוע ג\"כ שיש בזה מעלה ומדרגה גבוה במה שנהפך חשוכא לנהורא כו' מק\"נ דשרשו בבחי' גבורה דז\"מ דתהו שהי' קודם במעלה לפני מלוך מלך לבנ\"י<sup data-n=\"1823\">35</sup> שהוא בחי' התיקון<sup data-n=\"1824\">34</sup> דהיינו בחי' חשך סתרו שקדם לאור<sup data-n=\"1825\">36</sup> כו' (וע\"כ נק' עשו בנה הגדול<sup data-n=\"1826\">37</sup> ונק' בגדי עשו החמודות<sup data-n=\"1827\">38</sup> כאשר יבורר חשמ\"ל דק\"נ כמו שהי' בבחי' התהו קודם השבירה ונפילה כו' שזהו כתנות אור באל\"ף<sup data-n=\"1828\">39</sup> כו'). אך עכ\"ז אין ערך לאהבה זו דבכל לבבך לאהבה דכל נפשך דקאי בניצוץ אלקי שהוא חלק אלוה<sup data-n=\"1829\">40</sup> שנק' נר הוי'<sup data-n=\"1830\">41</sup> ושרשו למעלה מבחי' הפנימי' דשם הוי' דתיקון כמ\"ש כי חלק הוי' עמו<sup data-n=\"1831\">42</sup> כו' שקשורה ודבוקה למעלה באהבה [פנימי'] מעולם, וכאשר הנשמה האלקי' תמסור במס\"נ ליכלל ולידבק למעלה בהתקרבות<sup data-n=\"1832\">43</sup> עוז אהבה לה' ודאי גדולה הרבה יותר מאהבה דנה\"ב בהיפך הרצון הזר כנ\"ל, שזהו רק כמו הרחוק שנעשה קרוב לפי שעה כמו בע\"ת וכגר כו' ואין לו ערך לקירוב ודיבוק בעצם כבן לאב וכה\"ג (וראי' לזה דגם שבעלי' ובירור דעשו שהוא נה\"ב בשרשו כמו שהי' קודם השבירה גבוה מאד כנ\"ל מ\"מ בנפילתו למטה הוא נק' קליפה לפרי כו' וכתי' בי' ואת עשו שנאתי<sup data-n=\"1833\">44</sup> כו', משא\"כ נש\"י לא נאמר בהם ענין שנאה בעצם רק אהבה כמ\"ש אהבתי אתכם<sup data-n=\"1834\">45</sup> כו'. וע\"כ מאחר שבחי' עשו בתכלית הקטנות גם שיכול לעלות למעלה ביותר כנ\"ל כמו באהבה דבכל לבבך אין לה ערך כלל לגבי אהבה דבכל נפשך דנשמה שהיא גדולה ונפלאה בעצם הרבה יותר וד\"ל. וידוע דרישא דעשו בעטפוהי דיצחק<sup data-n=\"1835\">46</sup> שנמשך מפסולת גבו' דקדושה דיצחק וזהו ענין דכל לבבך ע\"י רשפי אש דקדושה דפחד יצחק נהפך חום האש הזר דעשו שבנה\"ב להיות גם הוא רק לה' לבדו כנ\"ל, וזהו ג\"כ בחי' פני שור שבמרכבה כנ\"ל, אבל אהבה דכל נפשך היינו בחי' אהבה דאברהם שהוא כמו אהבה האלקי' דנשמה ליכלל בשם הוי' כניצוץ באבוקה שזהו כמו פני ארי' להימין שישאג באהבה רבה<sup data-n=\"1836\">47</sup> כו' וד\"ל. והאהבה הג' היא אהבה דכל מאדך <span data-k=\"pg\">836</span> ּ שהוא אה\"ר בלתי מוגבלת במוח ולב כלל היותו למעלה מן ההשגה ודעת שלא יוכל להתיישב כלל בהשגה וטעם כידוע וזהו בחי' רחמים דיעקב שהוא בחי' פני נשר כו' כנ\"ל,",[["1821","32","<b>לב א' לאביו שבשמים</b>: ברכות נז, א."],["1822","33","<b>פני שור. . שרש גם לנה\"ב</b>: נסמן לעיל פ' יתרו רסג, ג."],["1823","35","<b>לפני מלוך מלך לבנ\"י</b>: וישלח לו, לא."],["1824","34","<b>דתהו שהי' קודם. . התיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ."],["1825","36","<b>דתהו. . חשך סתרו שקדם לאור</b>: תהלים יח, יב. ראה גם לעיל פ' בשלח קנח, ב. שער האמונה מג, א ובהערה 1."],["1826","37","<b>עשו בנה הגדול</b>: תולדות כז, טו. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' קמה. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370275\" data-slug=\"torah-or\" data-id=\"3901370275\">תו\"א בשלח סא, ב</a>. לעיל פ' בשלח קלו, ג."],["1827","38","<b>בגדי עשו החמודות</b>: תולדות שם [בדילוג]. ראה גם אוה\"ת בשלח כרך ז ע' ב'תרנט. לעיל פ' שמות ח, ב. לקמן פ' תרומה שיא, א. ויקהל תה, ד."],["1828","39","<b>כתנות אור באל\"ף</b>: בראשית ג, כא. ראה ב\"ר פ\"כ, יב. מאמרי אדה\"א ויקרא ח\"ב ע' תצג. וש\"נ. שעה\"י קמ, א ובהערה 10."],["1829","40","<b>חלק אלוה</b>: ראה גם לעיל פ' יתרו רנב, ד. וש\"נ."],["1830","41","<b>נר הוי'</b>: משלי כ, כז."],["1831","42","<b>כי חלק הוי' עמו</b>: האזינו לב, ט."],["1832","43","<b>בהתקרבות</b>: בד: בהתגברות."],["1833","44","<b>ואת עשו שנאתי</b>: מלאכי א, ג."],["1834","45","<b>אהבתי אתכם</b>: מלאכי שם, ב."],["1835","46","<b>דרישא דעשו בעטפוהי דיצחק</b>: ראה ת\"י ויחי נ, יג. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרסב. קונטרסים ע' שלג."],["1836","47","<b>ארי'. . שישאג באהבה רבה</b>: הושע יא, י. ראה גם מאמרי אדה\"א דברים ח\"א ס\"ע שא. וש\"נ. לעיל פ' וארא סב, ג."]]],[2300550147,"וכידוע דכח התפעלות הרחמים שבא מן המרירות והשפלות מגיע למעלה הרבה יותר מהתפעלות אוי\"ר דארי' ושור כו' וע\"כ נק' נחלת יעקב ונק' נחלה בלי מצרים<sup data-n=\"1837\">48</sup> כלל שזהו בחי' בריח התיכון<sup data-n=\"1838\">49</sup> כו' שמעורר ר\"ר העליונים שבפנימי' הכתר וז\"ש ואשא אתכם על כנפי נשרים<sup data-n=\"1839\">50</sup> כו', וזהו [בחי'] ג' מדרגות שבמשיח ונשא מסט' דאברהם וגבה מסט' דיצחק מאד מסט' דיעקב<sup data-n=\"1840\">51</sup> וד\"ל.\n<b>והנה</b> ע\"י ג' אהבות הנ\"ל הוא שנכלל בכאו\"א מג' מדרגות דאבות כנ\"ל, והיינו מג' מדרגות דמרכבה פני ארי' ושור ונשר כו', וזהו שיש בכאו\"א מבחי' מרכבה דאבות כנ\"ל עד שכל א' יכול לומר כו'. אך אחר שהגיע כנ\"י לג' אהבות הנ\"ל אזי נקראו בשם פני אדם דכליל כולהו וכמ\"ש ופני אדם להם<sup data-n=\"1841\">52</sup> כו' לקבל מבחי' פני אדם העליון שעל הכסא כו', והוא במ\"ש אחר ג' אהבות הנ\"ל והיו הדברים האלה כו' שזהו מצות ת\"ת<sup data-n=\"1842\">53</sup> שבחי' דבר ה' וחכמתו ורצונו שהוא פנימי' דאדם העליון דכתיב זאת תורת האדם<sup data-n=\"1843\">54</sup> כי דבריו חיים וקיימים<sup data-n=\"1844\">55</sup>, וכמו במ\"ת ממש שהאיר ה' פניו בחכמתו ורצונו ביו\"ד הדברות דכתיב חכמת אדם תאיר פניו<sup data-n=\"1845\">56</sup> ואעפ\"י שהוא בבחי' אנפי רברבי דבחי' ז\"א ובנ\"י נשמות בגופים נק' אנפי זוטרי<sup data-n=\"1846\">57</sup> מ\"מ זהו כפני האדם דמרכבה שמקבל מהארת פנים דאד\"ם שעל הכסא, וכך הוא במצות ת\"ת גם עכשיו כשמדבר דבר ה'<sup data-n=\"1847\">58</sup> שה' יושב ושונה כנגדו<sup data-n=\"1848\">59</sup> כו' או כמו תען לשוני אמרתיך<sup data-n=\"1849\">60</sup> כו' כמ\"ש במ\"א, ואמנם בלא ג' אהבות הנ\"ל בתחילה לא נק' אדם כמו האומר אין לי אלא תורה<sup data-n=\"1850\">61</sup> כו' וד\"ל. וזהו שלא נק' אדם בצלם אלקי'<sup data-n=\"1851\">62</sup> כ\"א אחר הק\"ש ותפלה שאז הוא בדומה לעליון<sup data-n=\"1852\">63</sup> שהוא בחי' אדם שעל הכסא בתומ\"צ שאחר ג' אהבות הנ\"ל, והוא בחי' מדרגות השבטים שאין כל אדם זוכה שהוא בחי' פני אדם הכולל כולם אע\"פ שיש בחי' מרכב' דאבות שהוא פני ארי' כו' בכל א' וא' כנ\"ל (וזהו שאע\"פ שתתעינו ה' מדרכיך כו' מ\"מ שוב למען עבדיך שבטי נחלתיך כנ\"ל).\n<b>והנה</b> לנגד ג' מדרגות הנ\"ל דפני ארי' ופני שור כו' אומרים המלאכים ג\"פ קדוש<sup data-n=\"1853\">64</sup> ה' צבאות דהיינו ג' צמצומים מלמעלה למטה בג\"פ קדוש כו' והוא כידוע שמבשרי אחזה<sup data-n=\"1854\">65</sup> כו',",[["1837","48","<b>נחלת יעקב. . נחלה בלי מצרים</b>: ישעי' נח, יד. שבת קיח, סע\"א. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קח ואילך."],["1838","49","<b>יעקב. . בריח התיכון</b>: ראה זהר תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט."],["1839","50","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["1840","51","<b>ונשא מסט' דאברהם. . דיעקב</b>: ישעי' נב, יג. זהר וישב קפא, ב."],["1841","52","<b>ופני אדם להם </b>[ח: ליתא]: יחזקאל א, י [ושם: ודמות פניהם פני אדם]."],["1842","53","<b>והיו הדברים. . ת\"ת</b>: ואתחנן ו, ו. ראה גם לקמן פ' פקודי תמח, ב. וש\"נ."],["1843","54","<b>דכתיב </b>[ בד: כמ\"ש ו]<b>זאת תורת האדם</b>: שמו\"ב ז, יט [ושם: וזאת]. חוקת יט, יד [ושם: התורה אדם]. ראה זהר (רע\"מ) משפטים קיז, ב. צו כט, ב. מאמרי אדה\"ז תקע\"א ע' עח וע' צג. מאמרי אדה\"א נ\"ך ע' שכה. וש\"נ. לעיל פ' בא קיג, ד. לקמן פ' תצוה שעג, א."],["1844","55","<b>דבריו חיים וקיימים</b>: ברכת אמת ויציב."],["1845","56","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["1846","57","<b>אנפי רברבי. . אנפי זוטרי</b>: ראה חגיגה יג, ב. לקמן שיא, ד ואילך [ושם בשם הזהר]. מאמרי אדה\"א דברים ח\"ג ע' תתקא בהערה. קונטרסים ע' שמג ואילך."],["1847","58","<b>ת\"ת גם עכשיו כשמדבר דבר ה'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשצה."],["1848","59","<b>שה' יושב ושונה כנגדו</b>: נסמן לעיל פ' יתרו רסא, א."],["1849","60","<b>תען לשוני אמרתיך</b>: תהלים קיט, קעב. ראה גם לעיל רנו, א."],["1850","61","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["1851","62","<b>אדם בצלם אלקי'</b>: בראשית א, כז. נח ט, ו."],["1852","63","<b>אדם. . בדומה לעליון</b>: נסמן לעיל רסב, א."],["1853","64","<b>ג\"פ קדוש</b>: ישעי' ו, ג."],["1854","65","<b>שמבשרי אחזה</b>: איוב יט, כו. ראה הנסמן לעיל פ' בא צח, ב."]]],[2300550179,"דאנו רואים שיש ג' מדרגות באדם בג' צמצומים א' בחי' פנימי' הלב שנק' רעותא דלבא<sup data-n=\"1855\">66</sup> שמתצמצם ובא ונמשך למוח המח' (שזהו הנק' קלא פנימאה דלא משתמע<sup data-n=\"1856\">67</sup> בדבור כמו קול חיצוני שנמשך מן הבל הלב החיצוני לדבור בפה כך הוא בחי' קול זה הפנימי שנמשך מן הבל הלב הפנימי למוח כו'), והיינו כאשר יתפעל האדם באהבה וחשק וחפץ בדבר מה ה\"ז בחי' כח רוחני ובלתי מוגבל כלל, אבל מיד שמתצמצם אור האהבה וחשק זה לבוא במוח לחשוב ולהרהר באותיות מחשבתו אותו הדבר שחושק ומתאוה בלבו הרי נתצמצם מהות האהבה והתשוקה <span data-k=\"pg\">תיח</span> ּ שהיתה בלב בבחי' הרוחני' להיות ב[מהות] מח' בעלמא ובהגבלת כלי האותיות בצרופי' שונים, וא\"כ הי' זה ע\"י צמצום ההמשכה מפנימי' הבל הלב לבוא אל המוח לחשוב בדבר זה כו' (וע\"כ נק' קלא פנימאה כמו הקול שנמשך מהבל הלב החיצוני לבוא בדבור שנשתנה למהות קול ודבור גשמי כך נשתנה מהות האהבה הרוחני' באותיות המח' שהן בלא אור וחיות כלל כו'). וצמצום הב' הוא באותיות המח' שקודמת להבל הלב החיצוני והוא<sup data-n=\"1857\">*68</sup> דאותיות המח' הגם שאינו רק כמו לבוש חיצוני לפנימי' הלב כנ\"ל אבל מ\"מ הן בחי' רוחני' לגבי הבל החיצוני שבלב, והוא מה שנתצמצם אותיות המח' בהבל הלב בחיצוני' שבא בדבור. וכאשר אנו רואים שבעת שיוצא הדבור מפי האדם הרי מדבר רק כפי אופן המח' שחושב דמה שחושב הוא מדבר, ובאותו עת שמדבר ירדה המח' מן המוח להבל הלב החיצוני שיוצא בקול ודיבור זה, כמו שנראה בחוש שטרם דברו בדיבור המח' הוא במוח דוקא ומה שרוצה לדבר כלול במח', אבל בעת שיוצא הדבור מהבל הלב אז תשכון המח' בלב עד שהדבור מורכב מן המח' והבל הלב<sup data-n=\"1858\">68</sup> (והוא ע\"י הקנה שמחובר במוח ולב כמ\"ש במ\"א) (אך מה שהמח' פועל התפעלות המדות במורגש בהבל הלב זהו מפנימי' המח' ביותר כידוע שזהו מבחי' מל' דתבונה שהיא לאה<sup data-n=\"1859\">69</sup> שילדה ששה בנים<sup data-n=\"1860\">70</sup> כו', משא\"כ חיצוני' מח' זו שיורדת בהבל הלב החיצוני יותר בעת הדיבור שמדבר מה שהי' במח' תחילה כו'). וצמצום הג' היינו מה שנמשך מחיצוני' הבל הלב המורכב שם מאמ\"ר<sup data-n=\"1861\">71</sup> רוחני לבא בקול ודבור המורגש בגשמיות בהרכבה דאמ\"ר<sup data-n=\"1862\">72</sup> גשמי (שנק' קלא דמשתמע בדיבור ושרשו בקלא פנימאה הנ\"ל שנמשך מפנימי' הלב למח' שבמוח ומשם לחיצוני' הלב ומשם לדיבור",[["1855","66","<b>רעותא דלבא</b>: זהר וירא ק, א."],["1856","67","<b>קלא פנימאה דלא משתמע</b>: ראה זהר בראשית נ, ב. ויגש רי, א. שעה\"י קלד, סע\"ב ואילך. מאמרי אדה\"א קונטרסים ע' שח. וש\"נ."],["1857","*68","<b>והוא</b>: דזח: ליתא."],["1858","68","<b>שהדבור. . המח' והבל הלב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370453\" data-slug=\"torah-or\" data-id=\"3901370453\">תו\"א ויחי קב, ג</a>. מאמרי אדה\"א בראשית ע' תעו. לעיל קו, ד."],["1859","69","<b>מל' דתבונה שהיא לאה</b>: ראה ע\"ח (שער לאה ורחל) של\"ח, פ\"ג. פ\"ד. לקו\"ת להאריז\"ל ס\"פ תולדות. ביאוה\"ז תרומה מט, ג."],["1860","70","<b>לאה שילדה ששה בנים</b>: ויצא ל, כ. ראה גם לעיל פ' שמות יח, א. וש\"נ."],["1861","71","<b>הבל הלב. . מאמ\"ר</b>: ראה זהר תצוה קפד, ב. לעיל יט, ג. וש\"נ."],["1862","72","<b>בקול ודבור. . דאמ\"ר</b>: ראה זהר (רע\"מ) בא מג, ב. לעיל פ' בא קו, ד. שמות יט, ג ובהנסמן בהנ\"ל."]]],[2300550211,"כו') (וע\"כ אנו רואים שהקול הגשמי מעורר את הכוונה<sup data-n=\"1863\">73</sup> שבמוח ולב בפנימי' שבו שנק' רעותא דלבא כי מפנימי' הלב הוא שמתצמצם ונמשך למח' ומן המח' להבל הלב שממנו יוצא הקול). והנה צמצום הא' בפנימי' התשוקה שבלב לבא לבחי' במהות<sup data-n=\"1864\">74</sup> מח' הרי נשארת מהות התשוקה הרוחני' שבלב בבחי' מקיף על הצמצום דאותיות המח' המקבל ממנו, וכמ\"כ בצמצום הב' במהות המח' הרוחני' שבא להיות במהות הבל הלב החיצוני כנ\"ל ג\"כ נשאר מהות המח' בבחי' מקיף על הבל הלב שמקבל ממנו כו', וכמ\"כ גם הצמצום הג' ממהות הבל הלב החיצוני שנמשך לבא במהות קול גשמי נשאר גם הבל הזה שבלב בבחי' מקיף על הקול הגשמי (וראי' מהשתנות הקול גשמי מחמת שינוי הבל הלב מקרירות לחום וכה\"ג) (ועכ\"ז הרי הקול גשמי מעורר הכוונה הפנימי' שבלב ומוח כנ\"ל וד\"ל).\n<b>והנמשל</b> מכ\"ז יובן למעלה בבחי' אדם העליון שעל הכסא כו' שיש בו ג' צמצומי' שהן ג\"פ קדוש עד שנק' הוי' צבאות בבחי' קול ודיבור העליון שמזה נתהוה כל ריבוי צבאות העליונים, והיינו ה' צבאות ע\"י ג\"פ קדוש שהן ג' צמצו[מי'] בתחלה. והענין הוא דצמצום הא' הוא מפנימי' הלב דאדם העליון שיבא במהות אותיות המח' שצ\"ל ע\"י צמצום גדול, שמצמצם לאור האהבה הרוחני' ולא נמשך ממנה רק מה שיוכל להתלבש באותיות המח' לבד וגוף עצם אור האהבה והתשוקה נשאר בבחי' מקיף עליו שהוא ענין הקדושה וה[ה]בדלה <span data-k=\"pg\">838</span> ּ בערך. וזהו בחי' קדוש הא' שהוי\"ו דקדוש זה הוא בחי' צמצום קדושה הראשונה דבחי' פנימי' המדות שבלב לגבי המח' שהולך בצמצום לבא במהות מח' כו'. וכמו\"כ בצמצום הב' שהוא ירידת אור מהות המח' הרוחני לבא למהות הבל הלב החיצוני בעת הדיבור כנ\"ל גם זה בא ע\"י וי\"ו דוקא, אבל עיקר המח' נשאר בבחי' מקיף בהעלם. וכן בצמצום הג' מן הבל הלב לקול ודיבור העליון שבהבל לב האדם העליון, אע\"פ שנק' חיצוני' לגבי פנימי' המדות והמח' הרוחני וכנ\"ל, מ\"מ נק' פנימי' ורוחני' לגבי מהות הרכבת קול גשמי כנ\"ל, וצריך גם הוא לבא ע\"י צמצום דוי\"ו, ועיקר מהות הבל הלב נשאר בבחי' מקיף (וכענין קול ה' בכח קול ה' בהדר<sup data-n=\"1865\">75</sup> כלול מג' מדריגות חג\"ת אמ\"ר שבלב כו'). וזהו ענין קדוש הג' בוי\"ו שמורה צמצום ההמשכה ממהות המדות שבהבל לב החיצוני לבוא בקול ודיבור העליון להיות מזה התהוות כל העולמות מאין ליש שנק' הוי' צבאות כנ\"ל וד\"ל.",[["1863","73","<b>שהקול. . מעורר את הכוונה</b>: ראה גם לעיל פ' בא קו, ד. וש\"נ."],["1864","74","<b>לבחי' במהות</b>: בתו\"ח כאן נכתב תיבת לבחי' ובין השיטין נכתב תיבת במהות. בד: במהות."],["1865","75","<b>קול ה' בכח. . בהדר</b>: תהלים כט, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670426\" data-slug=\"torat-chaim\" data-id=\"2300670426\">תו\"ח בראשית יד, ג</a> ובהערה 34."]]],[2300550243,"<b>והנה</b> ע\"ד הנ\"ל בג' צמצומים דג\"פ קדוש מלמעלה למטה יובן ג\"כ ענין מארז\"ל בג' שאגות שעל כל משמר ומשמר<sup data-n=\"1866\">76</sup> יושב ה' ושואג כארי כו' כמ\"ש שאוג ישאג על נוהו<sup data-n=\"1867\">77</sup> כו'. דהנה ג' משמרות הלילה הן ג' מיני צמצומים בבחי' המל' שנק' לילה<sup data-n=\"1868\">78</sup>, והוא בחי' הדין והצמצום שנק' חשך והסתר אלקי' שבבחי' המל' שיורדת ומתצמצמת בג' צמצומים בג' משמרות בהיכלות דק\"נ (שזהו כלבים צועקים חמור נוער<sup data-n=\"1869\">79</sup> כו') ומבררת משם בירורים והעלאות כמ\"ש ותקם בעוד לילה<sup data-n=\"1870\">80</sup> ותתן טרף לביתה רפ\"ח ע\"ה גימ' טרף<sup data-n=\"1871\">81</sup>, והוא מה שעולה משם ניצוצים דקדושה בבכי' שנק' מי בוכין<sup data-n=\"1872\">82</sup> מ\"ת בוכין<sup data-n=\"1873\">83</sup> אנן בעינן למהוי כו' ואז עולה המל' למעלה ומעורר אתעדל\"ע מן המשפיע אל המקבל שזהו מ\"ש שבכל משמר ומשמר הקב\"ה שואג כארי כו'. וענין השאגה זהו התגלות פנימי' המדות שבלב כמו שאגתי מנהמת לבי<sup data-n=\"1874\">84</sup> כמו שאגת הארי' אשר ישאג לטרוף כו' שזהו התגברות רב בהתפעלות הלב למעלה מן הכלי שלא יכול להכיל בכלי אותיות המח' כלל כו'. וכך הוא למעלה בהתעוררות אה\"ר דמשפיע שהוא בחי' סוכ\"ע לכנ\"י בזמן הגלות דוקא שנק' לילה<sup data-n=\"1875\">85</sup> ובכל לילה ובכל משמר ומשמר שאז בחי' החשך והסתר אלקו' בתכלית כו', שמפני שהתעוררו' האה\"ר ותשוקה זו היא באה מפנימי' הלב דאדם העליון לכנ\"י ע\"כ נק' בשם שאגה דוקא כמ\"ש שאוג ישאג על נוהו, ובפרט על העדר היחוד והקירוב כמו שכנ\"י בגלות רשפי' רשפי אש<sup data-n=\"1876\">86</sup> כו' בשלהובי דרחימותא<sup data-n=\"1877\">87</sup> יותר מבזמן בהמ\"ק כמ\"ש במ\"א ע\"פ כן בקדש חזיתיך הלואי<sup data-n=\"1878\">88</sup> כן באה\"ר ברשפי אש כזו בהיכל ק\"ק בזמן בהמ\"ק חזיתיך כי נפלאה אה\"ר זו מצד הריחוק לפי שאז דוקא תצא לאור נקוד' הפנימי' ביותר. וכך הוא ממש מן המשפיע אל המקבל בתיאובתא דדכורא לגבי נוק'<sup data-n=\"1879\">89</sup> שבעת הריחוק יותר תגדל תשוקתו כמ\"ש אני לדודי ועלי תשוקתו<sup data-n=\"1880\">90</sup> ואלי תשוקתו<sup data-n=\"1881\">91</sup> יותר מעת הקירוב כנ\"ל.\n<b>וזהו</b> שעל <span data-k=\"pg\">תיט</span> ּ כל משמר דוקא שואג כי משמר לשון משמר האסורים כי בית האסורים נק' משמר ע\"ש ששומרי' שם האסורים וגם כאן בהיות בגלות נאמר מלך אסור ברהטי'<sup data-n=\"1882\">92</sup>, אשר<sup data-n=\"1883\">93</sup> עכ\"ז אדרבה מחמת זה דוקא נתעורר פנימי' אה\"ר העליונה לכנ\"י שלא יכילנה כלי הלב וע\"כ בא לכלל שאגה, כמשל באדם התחתון כשחפץ ומשתוקק מאד לאיזה דבר הנאהב לו ביותר מימי קדם זכור יזכור את האהבה",[["1866","76","<b>שעל כל משמר ומשמר</b>: ברכות ג, א."],["1867","77","<b>שאוג ישאג על נוהו</b>: ירמי' כה, ל (בגמ' שם: ה' ממרום ישאג וממעון קדשו יתן קולו שאוג ישאג על נוהו. וראה רש\"י שם ד\"ה ישאג)."],["1868","78","<b>המל' שנק' לילה</b>: ראה זהר בא לח, ב."],["1869","79","<b>כלבים צועקים חמור נוער</b>: ברכות שם בהיפך הסדר."],["1870","80","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["1871","81","<b>רפ\"ח ע\"ה גימ' טרף</b>: נסמן לעיל פ' יתרו רעג, א."],["1872","82","<b>מי בוכין</b>: ראה דרשות התורה לר' שם טוב ן' שם טוב ר\"פ ויקרא."],["1873","83","<b>מ\"ת בוכין</b>: ראה ת\"ז ת\"ה (יט, ב). מאמרי אדה\"א בראשית ע' קג. וש\"נ. שמות ח\"א ר\"ע לו."],["1874","84","<b>שאגתי מנהמת לבי</b>: תהלים לח, ב."],["1875","85","<b>הגלות. . לילה</b>: ראה זהר אחרי סז, רע\"ב. סה\"מ מלוקט ח\"ב ע' רסו הערה 16."],["1876","86","<b>רשפי' רשפי אש</b>: שה\"ש ח, ו."],["1877","87","<b>בשלהובי דרחימותא</b>: זהר קדושים פד, א."],["1878","88","<b>כן בקדש. . הלואי</b>: תהלים סג, ג. ראה זהר תרומה קמ, סע\"א ואילך. לקמן חצר, ד. פ' תצוה שלז, ד. שעא, ד. מאמרי אדה\"א ויקרא ח\"א ע' קה. וש\"נ. ש\"א כט, ב ובהערה 26."],["1879","89","<b>בתיאובתא דדכורא לגבי נוק'</b>: ראה זהר נח סו, ב. לך פה, ב. תרומה קסה, סע\"א."],["1880","90","<b>אני לדודי ועלי תשוקתו</b>: שה\"ש ז, יא."],["1881","91","<b>ואלי תשוקתו</b>: דזח: ליתא. ראה סידור שער האלול רכז, ב. רכט, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380852\" data-slug=\"likkutei-torah\" data-id=\"4001380852\">לקו\"ת ראה לד, ב</a>."],["1882","92","<b>מלך אסור ברהטי'</b>: שה\"ש ז, ו."],["1883","93","<b>ברהטים אשר</b>: בד: כו'. אך."]]],[2300550274,"הישנה אז לא יכיל כלי לבו וישאג בשאגה כי לא יכיל כלי הלב גודל חפצו ותשוקתו, וזהו כמו שאגתי מנהמת לבי שנק' נהמת הלב הנ\"ל שזהו ענין תעלומות הלב<sup data-n=\"1884\">94</sup> מה שלא יכול לכנוס בכלי הלב כנ\"ל וזהו שנשאר בבחי' מקיף על הלב כו'. וכך הוא בבחי' שאגה העליונה במדות דאדם דאצי' שזהו בא מבחי' פנימי' מדות עליונות בחי' תעלומות הלב כמו נהמת הלב הנ\"ל שזהו הגבה למעלה מהגבלת אותיות המח' עדיין, רק הוא בחי' קול פשוט כו' עדיין בתעלומות הלב כמו צעק לבם אל הוי'<sup data-n=\"1885\">95</sup> כו' (בל\"א קלייעט אין הארצין) והוא בחי' קלא פנימאה, שזהו למעלה גם מבחי' נקודה דחכ' בבינה שלמעלה שנק' חכים ולא בחכ'<sup data-n=\"1886\">96</sup> כו', וגם למעלה מבחי' ח\"ס שנק' מח' סתימאה חש\"ב מ\"ה<sup data-n=\"1887\">98</sup> מאחר שבחי' השאגה הוא בנקודת פנימי' הלב שנק' רעותא דלבא ששרשו בנקודת מקור הרצון שנק' רצון פשוט שלמעלה גם ממקור החכ' שנק' טעם כמוס לרצון<sup data-n=\"1888\">97</sup> כו' והוא בחי' כתר שבכתר שלמעלה מח\"ס כו'. וזהו שעל כל משמר דוקא שמצד ההסתר שלמטה בא התעוררות למעלה בבחי' שאגה כארי מבחי' רב חסד דע\"י שלמעלה גם מהחכ' ומח' העליונה שנק' ח\"ס כו' וד\"ל, והיינו מבחי' מקיף דמח' סתימאה שמאיר מפנימי' הלב וכך הוא על כל משמר ומשמר שואג דהיינו כ[מו] שבירידות ההמשכה מבחי' פנימי' הלב למח' שאג מבחי' מקיף דמח' שבפנימי' הלב (שנק' קלא פנימאה כנ\"ל). כך גם בירידת [ו]המשכה וצמצום המח' להבל הלב החיצוני שהן המדות שמורכבים מאמ\"ר שבלב החיצוני שבא לדיבור כנ\"ל (שהוא קדוש השני כנ\"ל) הוא שואג מבחי' מקיף דמח' שמקפת על המדות שבהבל הלב בחיצוני' שלא יוכל ליכנס בלב כלל כנ\"ל. וכמ\"כ בהמשכה המצומצמת מהבל הלב החיצוני לקול ודבור המורגש שהוא וי\"ו דקדוש הג' שאג ישאג מבחי' מקיף דהבל הלב בקול ודבור שאז נק' קול זה המורגש בדיבור בשם שאגה ממש, וזה שמה ששואג מנהמת הלב מבחי' תעלומות נקודת הלב שלמעלה מן המח' וח\"ס הנ\"ל שנק' קלא פנימאה. ונמצא דג' מיני שאגה הללו בג' משמר[ו]' היינו בג' מקיפי' דג' מיני קדוש הנ\"ל, דהיינו מקיפים דג' ווי\"ן דג\"פ קדוש עד שבא לקול ודיבור ממש שזהו שאגה ממש ודוקא בג' משמרות הלילה, לפי שעיקר סיבת התעוררות דמשפיע למקבל שהן כנ\"י שיתעורר מבחי' המקיפים דמדות ומח' ודיבור הנ\"ל אינו בא רק מצד בחי' קטנות דמקבל בהיותה למטה בחשך דגלות בג' משמורות דלילה כנ\"ל וד\"ל.",[["1884","94","<b>תעלומות הלב</b>: תהלים מד, כב. ראה גם לעיל פ' בא קו, ב. וש\"נ."],["1885","95","<b>צעק לבם אל הוי'</b>: איכה ב, יח [ושם: אדני — ראה הנסמן במאמרי אדה\"ז תקס\"ה ח\"ב לע' תקפה. שע\"ת עא, ג ובהערה 24]."],["1886","96","<b>חכים ולא בחכ'</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה (יז, ב)."],["1887","98","<b>מח'. . חש\"ב מ\"ה</b>: זהר בראשית כד, א. ת\"ז תס\"ט (קיב, ב). שעה\"י קלז, א."],["1888","97","<b>ח\"ס. . טעם כמוס לרצון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380510\" data-slug=\"likkutei-torah\" data-id=\"4001380510\">לקו\"ת שלח מט, ג</a>. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שצב."]]],[2300550302,"<b>ויובן</b> כ\"ז בתוס' ביאור בדרך פרט בכל ניצוץ מישראל כו', שהן ג' משמרות הלילה שהגלות נק' לילה והיינו בכלל כאשר כנ\"י הן בגלות בגופים החומרים ובצרכי חיי גופם המה משועבדים בתכלית עד שנשכח מלבם לגמרי עומ\"ש לחיות כחיי הגוים, והן בחי' המשמר[ו'] דאישון לילה שהן בחשך גמור דק\"נ ונחלקי' לג' מדרגות שהן ג' מיני <span data-k=\"pg\">840</span> ּ חשך שנק' משמר כמו משמר בית האסורים שהשכינה עמהם בגלות ותפיסא כמ\"ש מלך אסור כו'. ובדרך פרט בכל ניצוץ האלקי שנתפס במאסר חומר גופו הבהמי' בג' עבירות חמורות גזל ועריות וש\"ד כו' (גזל גוזל או\"א<sup data-n=\"1889\">99</sup> שהן מוחין דחו\"ב שבפנימי' המדות שבלב, ועריות בהרהורי עבירה שמן הלב למוח, וש\"ד בכעס ורציחה שבהבל הלב לירד לחיי רעהו וגם בלה\"ר שהורג בלשון<sup data-n=\"1890\">100</sup> כו' וכה\"ג) והן ג' תפיסות, ומאסר הג' שהוא ש\"ד קשה מכולם וכמ\"ש מי יעלה כו' נקי כפיים<sup data-n=\"1891\">101</sup> כו' וכתיב ובפרישכם כפיכם כו' ידיכם דמים מלאו<sup data-n=\"1892\">102</sup> כו' ועל כל משמר ותפיסא ה' שואג כארי כו'. דהיינו כאשר יצעק האדם בצעקת הלב אל ה' בצר לו מחטאיו ואשר בחושך ילך במיני מאסר הגוף כנ\"ל וצעקה זו מצד שקצר כלי הלב להכיל צערו מאשר מאד נתרחק מאור פני מלך חיים<sup data-n=\"1893\">103</sup>, וכבעלי תשובה אמיתי' שבוכים וצועקי' מקירות הלב שזהו כמו השאגה מנהמת הלב כנ\"ל, אז בזה מעוררים אתדל\"ע כמו\"כ למעלה, בחי' שאגה העליונה דאדה\"ע מפנימי' הלב העליון שלמעלה גם ממח' סתימאה הנ\"ל ששאוג ישאג בבחי' המקיפי' שזהו בחי' המשכת הרחמים הגדולים על בניו שהם בגלות וריחוק עצום בזה וצועקים אליו כמו בחי' מ\"ת בוכין כו' וד\"ל.\n<b>וזהו</b> סומך ה' לכל הנופלים<sup data-n=\"1894\">104</sup>, כי הנה מ\"ש נפלה לא תוסיף קום<sup data-n=\"1895\">105</sup> כו' היינו שלא תקום מעצמה אבל קוב\"ה מוקים לה<sup data-n=\"1896\">106</sup> כמ\"ש סומך ה' לכל הנופלים כו', שהוא לסוכת דוד הנופלת<sup data-n=\"1897\">107</sup> לשון הוה תמיד בתחתית המדרגות בהיותם בגלות זה האחרון שנשמותיהם אסור בחומר שעבוד הגוף בג' מיני מאסר הנ\"ל (והעיקר במאסר דגוזל או\"א שהוא שרש הראשון דנש\"י בבחי' פנימי' דאו\"א שהוא בח\"ס כו'). אך כתיב כי יפול לא יוטל<sup data-n=\"1898\">108</sup> לגמרי לפי שה' סומך ידו כמשל הנופל בראשו לארץ שבהגיע סמוך לארץ יסמכנו בידו איש גבור חזק שיש בכחו להעמידו גם בסמוך לארץ<sup data-n=\"1899\">109</sup> כו' (כמ\"ש במ\"א), וגם כאן סומך ה' לכל הנופלים זהו נש\"י שנפלה ממקום גבוה מאד נעלה לבירא עמיקתא<sup data-n=\"1900\">110</sup> מעומ\"ר לעומ\"ת שהרי שרשם הראשון בפנימי' המח' העליונה, וזהו שא' ישראל עלו במח'<sup data-n=\"1901\">111</sup> ונק' לי",[["1889","99","<b>גוזל או\"א</b>: משלי כח, כד. ראה גם מאמרי אדה\"א דברים ח\"ג ע' תשנד. וש\"נ."],["1890","100","<b>בלה\"ר שהורג בלשון</b>: ערכין טו, ב."],["1891","101","<b>מי יעלה. . נקי כפיים</b>: תהלים כד, ג. ד."],["1892","102","<b>ובפרישכם כפיכם. . ידיכם דמים מלאו</b>: ישעי' א, טו."],["1893","103","<b>מאור פני מלך חיים</b>: ע\"פ משלי טז, טו."],["1894","104","<b>סומך ה' לכל הנופלים</b>: תהלים קמה, יד."],["1895","105","<b>נפלה לא תוסיף קום</b>: עמוס ה, ב."],["1896","106","<b>קוב\"ה מוקים </b>[ד: יוקים]<b> לה</b>: ראה זהר ח\"ש קלד, א. ויגש רח, ב. פקודי רמ, ב. מאמרי אדה\"א דברים ח\"א ע' פח. וש\"נ. נ\"ך ע' שנא. וש\"נ."],["1897","107","<b>לסוכת דוד הנופלת</b>: עמוס ט, יא. ראה גם ש\"א מו, א."],["1898","108","<b>כי יפול לא יוטל</b>: תהלים לז, כד."],["1899","109","<b>כמשל הנופל בראשו. . בסמוך לארץ</b>: ראה גם מאמרי אדה\"א נ\"ך ע' שנד וע' שנה וס\"ע שנא ואילך."],["1900","110","<b>לבירא עמיקתא</b>: חגיגה ה, ב. ראה גם לעיל פ' שמות ד, ג. וש\"נ."],["1901","111","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל לב, ב."]]],[2300550328,"ראש<sup data-n=\"1902\">112</sup> שזהו בחי' ח\"ס דא\"א כו', ונפלה משם לעומ\"ת בתכלית שהן הגופים החומרים שנלקחו מתאוות דאו\"א שהוא משמרים דק\"נ ובחי' הרע דגזל ועריות וש\"ד שהן כוללים<sup data-n=\"1903\">113</sup> ג\"ק הטמאות כו' (וכאשר נכרתה הנשמה משרשה באו\"א שנק' יתומים ואין אב<sup data-n=\"1904\">114</sup> כו'). וזהו כמשל המושלך בבור עמוק ביותר שצריך ליד ארוכה ביותר שיגיע לשם ויוציאנו ויעלנו משם, כך צריך לנפילת כנ\"י בעומ\"ת דק\"נ בחי' יד ארוכה ביותר שנק' יד הגדולה כו' שיוכל להגיע לעומ\"ת להעלות משם, דהיינו שבהכרח שיבוא האור האלקי ממקום גבוה יותר גם משרשם הראשון במח' העליונה שמשם נפלה לעומ\"ת כ\"כ להשיבם למקומם ושרשם הראשון כו' (וכמו שהי' במצרים שנגלה עליהם מלך כו' בכבודו ובעצמו<sup data-n=\"1905\">115</sup> ולא ע\"י מלאך<sup data-n=\"1906\">116</sup> ולא ע\"י שרף כו' כי הי' נפילתם ושעבודם בנש\"ט דמצרים<sup data-n=\"1907\">117</sup> שצריך לבוא שם מאוא\"ס בעצמו דוקא כמשל הנ\"ל, לפי שכל הגבוה<sup data-n=\"1908\">118</sup> גבוה יותר יותר יוכל להשפיל א\"ע גם במקום חושך ואפילה להאיר גם שם משום דקמי' כחשיכה כאורה<sup data-n=\"1909\">119</sup> כו'<sup data-n=\"1910\">120</sup> (וכך הוא גם עכשיו <span data-k=\"pg\">תכ</span> ּ בגלות זה האחרון שנתארך ביותר בתכלית ההסתר והצמצום כו'). וזהו ג\"כ ענין השאגה ששואג כארי על כל משמר כו' דבחי' שאגה זו היינו למעלה מעלה גם מבחי' מח' העליונה שהוא שרש נש\"י, דבשאגה זו מעלה אותם גם ממקום נפילתם למטה ביותר. וזהו כללות ענין הג' משמרות שהוא בלילה שנק' גלות דוקא (ובכל חצות לילה דוקא דאחית תרין דמעין בימא רבא<sup data-n=\"1911\">121</sup> כו') שזהו יותר גבוה מתענוג שבראי' מקרוב בג' רגלים מטעם הנ\"ל כמ\"ש כן בקדש חזיתיך וד\"ל.\n<b>ומעתה</b> י\"ל מהו שאמר ששואג כארי דוקא, להיות מבואר למעלה בענין האבות הן המרכבה דפני ארי' להימין זהו בחי' ומדרגה דאברהם אוהבי<sup data-n=\"1912\">122</sup> כו' שהוא מצד האהבה העצמי' דנשמה בשרשה בפנימי' ועצמות דאלקים חיים, והיינו אהבה דבכל נפשך שהיא הנה\"א שנמשכת אחרי הוי' ממילא מצד שנלקחה משם ועולה למקור חוצבה כו', והיינו בחי' אה\"ר שנמשך כמים<sup data-n=\"1913\">123</sup>, אך זהו בבחי' הגבו' שבחסד והוא בחי' פני ארי' להימין כו' וכמו אחרי ה' ילכו כארי' ישאג כארי' שבמרכבה<sup data-n=\"1914\">124</sup> העליונה כו'. אך הנה [ידוע] בזהר במ\"ש דאית חסד ואית חסד<sup data-n=\"1915\">125</sup> כו' והוא ב' מדרגות דנוצר חסד<sup data-n=\"1916\">126</sup> ורב חסד<sup data-n=\"1917\">127</sup>, דנוצר חסד זהו בחי' החסד שהוא אה\"ר שברצון (ונק' חסד דא\"א) ורצון אותיות",[["1902","112","<b>ישראל. . לי ראש</b>: ראה פע\"ח (שער הלולב) שכ\"ט, פ\"א. מאמרי אדה\"א ויקרא ח\"א ע' צה. וש\"נ. שע\"ת צד, ד ובהערה 26."],["1903","113","<b>כוללים</b>: ד: ליתא."],["1904","114","<b>יתומים ואין אב</b>: ע\"פ איכה ה, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680236\" data-slug=\"torat-chaim\" data-id=\"2300680236\">תו\"ח תולדות קנב, ג</a>."],["1905","115","<b>שנגלה. . בכבודו ובעצמו</b>: ראה גם לעיל פ' בא קכב, א. וש\"נ."],["1906","116","<b>ולא ע\"י מלאך</b>: ראה גם לעיל פ' בא קכב, סע\"ב ואילך ובהנסמן שם."],["1907","117","<b>נפילתם ושעבודם בנש\"ט דמצרים</b>: ראה ז\"ח יתרו לא, א. לעיל פ' שמות מא, ד. וש\"נ."],["1908","118","<b>שכל הגבוה</b>: ראה לעיל פ' שמות כא, ב הערה 863."],["1909","119","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["1910","120","<b>כו'</b>: כנצ\"ל: כו')."],["1911","121","<b>חצות. . תרין דמעין בימא רבא</b>: ראה זהר ויקהל קצו, א."],["1912","122","<b>דאברהם אוהבי</b>: ישעי' מא, ח."],["1913","123","<b>אה\"ר שנמשך כמים</b>: ראה ספר הערכים חב\"ד ח\"א ע' תקכח ואילך."],["1914","124","<b>אחרי ה' ילכו. . כארי' שבמרכבה</b>: הושע יא, י. ראה מאמרי אדה\"א דברים ח\"א ס\"ע שא. וש\"נ. שמות ח\"ב ע' תעז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680094\" data-slug=\"torat-chaim\" data-id=\"2300680094\">תו\"ח וישלח קפא, ג</a>."],["1915","125","<b>דאית חסד ואית חסד</b>: ראה זהר (אד\"ר) נשא קמ, ב. לעיל פ' בשלח קמב, ג. וש\"נ."],["1916","126","<b>דנוצר חסד</b>: תשא לד, ז."],["1917","127","<b>ורב חסד</b>: תשא שם, ו."]]],[2300550353,"צנור<sup data-n=\"1918\">128</sup> שזהו נוצר חסד לאלפים (שנמשך לחו\"ב מבחי' ח\"ס דא\"א שנק' מזל הח' דא\"א שממנו מקבל אור אבא<sup data-n=\"1919\">129</sup> דאצי' כו') והוא המשכת האה\"ר דרך צנור מאור הכתר שהוא בחי' רצה\"ע כו' (והוא הרצון שיכול לבוא בשכל וטעם ג\"כ גם כשאינו אלא בהעלם ונק' טעם כמוס לרצון, והוא הרצון הנולד בהתפעלו' שיש לו ביטול והפסק אע\"פ שההתפעלו' חזק מאד, וזהו [אהבה] דבכל נפשך נה\"א שתרוץ כניצוץ בשלהבת כמו משכני אחריך נרוצה<sup data-n=\"1920\">130</sup> כו'). אך בחי' ורב חסד הוא למעלה מנוצר חסד, דנוצר הוא רק צנור שנפתח מעצמיות אור הכתר שהוא רק התעוררו' והתפעלות הרצון כנ\"ל, אבל אה\"ר העצמיי' שבעצמיות הנפש ממש זה[ו] התפעלות עצמיות הנפש ממש שלמעלה מהתפעלו' רצון הנולד לפי שעה כו'. וזהו אה\"ר דכל מאדך שלא תכנס בכלי הלב והמוח כלל מפני שלא תגבילנו השכל וגם הרצון, להיותה אהבה עצמיות ופשוטה והוא מצד דיבוק נש\"י בעצם במקורם ושרשם בעצמו' א\"ס ממש (וכמו שא' רשב\"י בי' אחידא בי' להיטא<sup data-n=\"1921\">131</sup> כו') (וכמו שא' חבוקה ודבוקה בך<sup data-n=\"1922\">132</sup> ממש ולא כניצוץ המרוחק שיפול עליו ענין מרוצה אלא דבוק ממש בעצם המקור), וזהו בחי' ורב חסד דא\"א שזהו מה שאמר הקב\"ה יושב ושואג כארי כו' דבחי' השאגה באה מנקודת הלב שבעצמיות הנפש ממש שלמעלה מהתפעלו' רצון כנ\"ל. וכמ\"כ מלמעלה למטה נמשך בחי' אה\"ר העליונה שבעצמו' א\"ס ממש כמ\"ש אה\"ר אהבתנו<sup data-n=\"1923\">133</sup> כו' שלא יוגבל בכלי החכ' והרצה\"ע כלל<sup data-n=\"1924\">134</sup> רק אה\"ר העצמי' ופשוטה כאהבה דכל מאדך למטה בכנ\"י מלמטה למעלה, וזהו בחי' ורב חסד העליון שנתעורר אה\"ר העצמי' העליונה על כנ\"י כמו בעת צרתם ושוועתם אליו או בתוקף גלות ישראל כו' ושכינה עמהם כו', והוא בכל חצות לילה דזכור יזכור על אהבה דכנ\"י וז\"ש שאג ישאג על נוהו כו', וזהו שיושב ושואג כארי דוקא כשאגת הארי שבמרכבה בבחי' אה\"ר כנ\"ל<sup data-n=\"1925\">135</sup> דכנ\"י שנא' &lt;842&gt; ּ כארי' ישאג על נוהו מפני שהשאגת הלב באה מצד שאינה נכנסת בכלי כלל וד\"ל.\n<b>והנה</b> סיבת השאגה בלב באה רק [מ]בחי' ראי' דארי' אותיות ראי'<sup data-n=\"1926\">136</sup> כידוע וראי' היא בחכ' שלמעלה משמיעה דבינה<sup data-n=\"1927\">137</sup>, כמו שאנו רואים שכל זמן שההתפעלו' הלב אינו רק מצד ההשגה האלקי' שמתיישב[ת] בכלי מוחא ולבא יבין גם הוא הבנה והשגה זו דבינה ליבא<sup data-n=\"1928\">138</sup> הלב מבין<sup data-n=\"1929\">139</sup> כו' והוא בחי'",[["1918","128","<b>ורצון אותיות צנור</b>: ראה זהר הרקיע לזהר בראשית נא, א (כה, ב). מאמרי אדה\"א בראשית ע' לו. וש\"נ."],["1919","129","<b>מזל הח'. . אור אבא</b>: ראה זהר (אד\"ז) האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. לעיל פ' שמות לו, א. וש\"נ."],["1920","130","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["1921","131","<b>בי' אחידא בי' להיטא</b>: זהר (אד\"ז) האזינו רצב, א. ראה מאמרי אדה\"א שמות ח\"ב ע' שכט. בראשית ע' קעא. ז: בחד קטירא אתקטרנא בי' אחידא — ראה זהר שם רפח, א. רצב, א. לקמן פ' תרומה שו, א. תצוה של, סע\"ב ואילך. ויקהל תלה, ד. שע\"ת קה, ד ובהערה 34."],["1922","132","<b>חבוקה ודבוקה בך</b>: הושענא אום אני חומה [ליום ג]."],["1923","133","<b>אה\"ר אהבתנו</b>: ברכת ק\"ש שחרית [נוסח אשכנז]."],["1924","134","<b>כלל</b>: ניתוסף ע\"פ זח."],["1925","135","<b>כנ\"ל</b>: שם: ליתא."],["1926","136","<b>דארי' אותיות ראי'</b>: ראה ת\"ז ת\"ע (קכב, א). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["1927","137","<b>וראי' היא בחכ'. . משמיעה דבינה</b>: ראה גם לעיל פ' שמות כז, ג. וש\"נ."],["1928","138","<b>דבינה ליבא</b>: ת\"ז בהקדמה (יז, א)."],["1929","139","<b>הלב מבין</b>: ברכות סא, א."]]],[2300550373,"תמצית המושג שנקלט בלב דוקא, כמו<sup data-n=\"1930\">140</sup> שמזה יוצאים<sup data-n=\"1931\">141</sup> ענין התפעלות קול תנועת הניגון בכוונה שבלב ומוח דוקא כשיר המלאכים והלוים וכה\"ג. אמנם אז עדיין לא יבא האדם לבחי' שאגה בקול פשוט כלל שהוא בלא סדר והדרגה כלל רק בקול פשוט בלי שום כוונה בתחלה במוח ולב רק פתאום יצעק וישאג כמו שאגתי מנהמת לבי, ונהמת הלב הוא התפעלו' נקוד[ת] פנימי' הלב פתאום מבלי טעם וכוונה שבמוח לפי שלא יכילנו כלי הלב וכלי המוח כלל וכלל ע\"כ בא ממילא לכלל שאגה דוקא. וזהו בא רק ע\"י בחי' ראי' שבלב דוקא והוא מה שהלב רואה<sup data-n=\"1932\">142</sup> כמו בראי' חושי' לדבר מה שחפץ ומשתוקק בו שזהו בראי' עין השכל שבלב ולא מה שהלב מבין ומשיג בהשגה והבנת שכל בלבד, כמו הרואה את המלך הגדול או [אב] לבנו ובן לאביו שרואהו מרחוק ששאג ישאג עליו בקול פשוט מנהמת לבו כו' לפי שאז נוגע לו בעצם נקודת פנימי' שבו, ולא כאשר שמע מביאתו ולא ראהו עדיין שאינו אלא שמח במוחו ולבו בהתבוננות באיכותו ומהותו כו' וע\"כ א' דאינו דומה שמיעה לראי'<sup data-n=\"1933\">143</sup>, וכמו אהבת אדם א\"ע ביותר גם מאוהבו נאמנו או בנו כו' לפי שנפשו הוא מכיר כמו בראי' חושית ממש אע\"פ שלא ראה נפשו במהותה הרוחני' בעיניו הגשמי' מ\"מ בחי' הכרה והרגשה זו שמרגיש לחיי נפשו בגופו זהו כמו ראי' בעין, וזהו הסיבה להתפעלו' עצמו בחיי נפשו יותר מחיי אוהבו נאמנו כנפשו עד שכל אשר יש לו יתן בעד נפשו כו' להיותה בחי' עצמיות ממש, משא\"כ התקשרות נפשו בנפש בנו או אוה\"נ כו'). וז\"ש לאהבה את ה' אלקיך כי הוא חייך<sup data-n=\"1934\">144</sup> ממש כו' (וכך הי' במ\"ת שבבחי' ראי' מקרוב על כ\"ד פ\"נ<sup data-n=\"1935\">145</sup> כו'), ואמנם לא תוכל להיות בחי' הראי' בלב כ\"א בפנימי' ממש שנק' נקודת הלב ששם הוא בחי' יחיד[ה] דנפש ממש ונק' נהמת הלב כו' אבל לא בבינה והשגה בלב כו'. ומ\"ש וידעת היום<sup data-n=\"1936\">146</sup> והשבות אל לבבך כו' היינו בחי' הדעת והשגה שבמוח ישוב ללב ואח\"כ יבא לבחי' ראי' בלב כנ\"ל כמ\"ש בר\"מ דבעין השכל דבלבא<sup data-n=\"1937\">147</sup> אתחזי כולא כו', הרי כל פנימי' המראה דנבואה דמשה שנק' רע\"מ<sup data-n=\"1938\">148</sup> הי' בבחי' ראיי' עין השכל שבלב שהלב רואה כו' ומזה דוקא [יבא] בחי' השגה כנ\"ל דארי' אותיות ראי' וד\"ל.\n<b>וזהו</b> בחי' אהבה דבכל מאדך הנ\"ל שלמעלה מב' אהבות דכל לבבך ובכל נפשך הנ\"ל, דהנה מבואר למעלה בענין האבות הן המרכבה דפני ארי' ופני שור ופני נשר כו' שהן בחי' חג\"ת דאוי\"ר דאברהם ויצחק ורחמים דיעקב כו', והנה אהבה דבכל לבבך היינו בשני יצריך שזהו להפוך גם הלב <span data-k=\"pg\">תכא</span> ּ החומרי שיתאווה ויאהב גם הוא לה' [אחד] ולא יהי' לו שום רצון זר כלל כו', והוא ע\"י בחי' יראה ופחד יצחק שיכול למשול ברוחו",[["1930","140","<b>כמו</b>: ד: ליתא."],["1931","141","<b>יוצאים</b>: דז: יוצא."],["1932","142","<b>שהלב רואה</b>: קה\"ר פ\"א טז, א."],["1933","143","<b>דאינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג, יח. לעיל פ' שמות כב, ב. וש\"נ."],["1934","144","<b>לאהבה. . כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["1935","145","<b>על כ\"ד פ\"נ</b>: נסמן לעיל פ' יתרו רנג, ד."],["1936","146","<b>וידעת היום</b>: ואתחנן ד, לט."],["1937","147","<b>דבעין השכל דבלבא</b>: ראה זהר (רע\"מ) משפטים קטז, ב. הנסמן במאמרי אדה\"א קונטרסים ע' תקפד."],["1938","148","<b>דמשה שנק' רע\"מ</b>: ראה זהר וירא קו, א. לעיל פ' וארא עז, ב. וש\"נ."]]],[2300550392,"ולאכפיי' לסט\"א כו' להיות לבו ברשותו שלא ילך אחרי ההבל בכל תאוה רעה בלתי לה' לבדו והוא להרגיז יצ\"ט על היצה\"ר שבלבו כמ\"ש לעולם ירגיז אדם יצ\"ט<sup data-n=\"1939\">149</sup> כו'. וזהו הכח והגבורה לכבוש את יצרו לכופו שיהי' גם הוא נכנע ובטל לעבודה האלקי' לבד זהו בא מכח ועוז דבחי' פני שור שבמרכבה העליונה, שיש שם שרש לנשמת יצחק בקו השמאל בבחי' גבורה עליונה דקדושה ככח השור בקרנו שמנגח בכח גדול לכל העומדים לנגדו, ויש כח בשור למשא ולעול מ\"ש לעבוד בע\"כ כמו יוסף שנק' שור כמ\"ש בכור שורו<sup data-n=\"1940\">150</sup> כו', ומשם מסתעפי' לכל הניצוצי' לנש\"י בכל דור ודור גם בקטן שבקטנים להיות מושג<sup data-n=\"1941\">151</sup> וגובר לכבוש את היצה\"ר בדרך כפי' לקבל עליו עומ\"ש שלימה גם ביצה\"ר שבלבו וזהו בכל לבבך כו'. אך כ\"ז אינו רק לאכפיי' בע\"כ כו' ואין זה נק' היפך הרצונות זרות לגמרי רק שמונע ומתרחק מהם ודוחה אותם וכופה אותם עד שיהי' לבו הטבעי נכנע ובטל בע\"כ כמו ע\"י הרוגז שמרגיז עליו כו'. אך אהבה דכל נפשך שזהו בחי' אה\"ר דנשמה האלקי' שנמשך למקור חוצבה כניצוץ שתרוץ בכח גדול ליכלל לגמרי בשלהבת כנ\"ל והוא כמו בחי' פני ארי' להימין באה\"ר שברצון כנ\"ל בעוצם הדביקות ותשוקה ליכלל באלקי' חיים כו'. והנה עי\"ז יוכל להיות גם היפך כל הרצונות הזרות שבגוף החומרי שיהי' מואס ברע לגמרי ולהיות לו רק לב א' לאביו שבשמים ולא בדרך כפי' ודחי' בלבד כענין בטל רצונך מפני רצונו<sup data-n=\"1942\">152</sup> כו'. ואמנם גם זה עדיין לא נק' היפך הרע מעומקא<sup data-n=\"1943\">153</sup> ושרשה לגמרי מכל וכל כי הרי עדיין יש למציאות הרע כמו שהוא בחום הטבעי' מוכן לכל תאוה רק שמואס ברע זה והסיר כל הרצון ממנו לגמרי מכל וכל (ולא שהוא סו\"מ בדרך כפי' ודחי' לבד כו', כמו שמואס אדם באמת בכל חיי הבלי עוה\"ז ולא יש בלבו רק רצון א' לידבק בה' אחד בתורה ותפלה ומע\"ט כו', שעכ\"ז עדיין לא נהפכו כל עיקר פנימי' נקודת התקשרות לבבו הטבעי בכל רצונות הזרות שבגופו החומרי עד שלא יכול להטות לבו אליהם כלל לעולם, שהרי במעט פר\"ע מ\"ש והיסח דעתו ולבו מה' בקרירות ועצלות ואהבתו ודביקות נשמתו ע\"י ביטול טרדת הבלי הזמן בפרנסתו וכה\"ג אז יוכל ליפול בהתקשרות רצונות הזרות שלא לה' המה מפני שלא נזדכך גופו הטבעי עדיין בעצם הרע כו'. ואמנם ע\"י אה\"ר הג' דכל מאדך הנ\"ל שזהו בחי' פני נשר דהיינו בחי' הרחמים דיעקב כנ\"ל יכול להיות היפך הרע מעיקרו ושרשו שלא ישלוט באדם כלל כאלו מופשט מכל רע בעצם וכמו ולבי חלל בקרבי<sup data-n=\"1944\">154</sup> כו'. והטעם הוא לפי שאה\"ר זו דכל מאדך ה\"ז למעלה מהגבלת הכלי לגמרי שלא יכילנו הכלי המוח והלב כלל וכלל וע\"כ יבא מזה התפעלו' השאגה מבחי' פנימי' נקודת הלב שבעצמיות הנפש ממש, וזהו כארי' ישאג כשאגת ארי בקול",[["1939","149","<b>לעולם ירגיז אדם יצ\"ט</b>: ראה לעיל פ' בשלח רכו, ב. וש\"נ."],["1940","150","<b>בכור שורו</b>: ברכה לג, יז."],["1941","151","<b>מושג</b>: בד: מושל."],["1942","152","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב, מ\"ד."],["1943","153","<b>מעומקא</b>: בד: מעיקרא. ז: מעיקרו."],["1944","154","<b>ולבי חלל בקרבי</b>: תהלים קט, כב."]]],[2300550409,"פשוט כנ\"ל. וזה לא יוכל להיות ע\"י אתעדל\"ת דאדם מצד עצמו באהוי\"ר כ\"א ע\"י אתעדל\"ע שנמשך על נפשו אה\"ר העצמי' הנ\"ל שלא יוגבל <span data-k=\"pg\">844</span> ּ אורה בכלי החכ' והתפעלות הרצון כלל, והוא בא ע\"י שמתעורר עליו מבחי' ר\"ר העליונים ממקור כל הרחמים שהוא מעצמו' א\"ס מקורא דכולא<sup data-n=\"1945\">155</sup> כו', והיינו ע\"י מה שבכח הנשמה האלקי' אחר הכפיי' ומואס ברע כנ\"ל (כאהבה דכל לבבך ובכל נפשך הנ\"ל) לעורר ע\"ע ר\"ר למעלה, וזהו רק במה שיש בכחה להשפיל א\"ע ביותר להכיר בעצמו עוצם הריחוק כ\"כ מאלקי' חיים ע\"י חטאיו הרבים ופירוד לבבו בהתקשרות עמוקות בהבלי תאוות חומריות כו' ובא לכלל מרירות ושפלות ולב נשבר ונדכה ביותר כאביון המדוכא בעוני וחוסר כל ויותר מזה, אזי עי\"ז מתעורר אתעדל\"ע ר\"ר שבעצמו' א\"ס ממש כי רם ה' ושפל יראה<sup data-n=\"1946\">156</sup> כו' דעומ\"ר דר\"ר אינו נמשך רק בעומק שפלות ולב נשבר כו'.\n<b>וזהו</b> שרש בחי' קו האמצעי דמדה\"ר דיעקב שמבריח לקצה העליון שע\"ז א' ופני נשר לארבעתן שבחי' פני נשר הוא שעולה בר\"ר העצמי' ממש הנ\"ל כמ\"ש [במ\"א] ע\"פ כנשר יעיר קנו<sup data-n=\"1947\">157</sup> על גוזליו ירחף למטה ולפעמים אמר ישאהו על אברתו למעלה מכנפיו וכמ\"ש ואשא אתכם על כנפי נשרים<sup data-n=\"1948\">158</sup> ואביא אתכם אלי ממש כמו במ\"ת כידוע. והענין הוא כידוע דהנשר טבעו רחמני על בניו וכשירא מן טורפים ומזיקים למטה אז יעיר קנו למטה ועל גוזליו ירחף כאשר ינשאם למעלה ויסתירם תחת כנפיו שלא יגיע בהם חץ מלמטה כמו באברתו יסך לך<sup data-n=\"1949\">159</sup> כו'<sup data-n=\"1950\">160</sup> ותחת כנפיו תחסה כו', שלמעלה הן בחי' מקיפים העליונים דר\"ר דפני נשר לשמור לנשמות שנק' בנים שלא יגיע חץ הקטרוגי' הקשים כו', שמסתעפי' מחטאים ועוונות כו', אך כאשר רבו מאד החיצים מן המקטריגי' הרעים של הרע עד שלא יועיל ההסתר שתחת הכנפים דנשר שהוא בחי' ורב חסד ורחמים העליונים להצילם, אז א' ישאהו על אברתו למעלה מכנפיו שאין חץ מגיע שם כלל לפי שהנשר פריחתו הגבה למעלה ברום השמים כמ\"ש דרך הנשר בשמים<sup data-n=\"1951\">161</sup> כו'. וז\"ש ואשא אתכם על כנפי נשרים כו' שאין שם מקום<sup data-n=\"1952\">162</sup> ושרש ליניקת החיצונים והוא מה שנמשך מאה\"ר העצמי' ממש כנ\"ל שמפני זה דוקא יוכל להיות בחי' היפך הרע בעצם מכל וכל כנ\"ל שאין כח זה באוי\"ר דאברהם ויצחק [רק] בבחי' רחמים דיעקב שהוא פני נשר והוא אה\"ר דכל מאדך הנ\"ל וד\"ל.",[["1945","155","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["1946","156","<b>כי רם ה' ושפל יראה</b>: תהלים קלח, ו."],["1947","157","<b>כנשר יעיר קנו</b>: האזינו לב, יא. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670299\" data-slug=\"torat-chaim\" data-id=\"2300670299\">תו\"ח בראשית ה, ג</a> ואילך."],["1948","158","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["1949","159","<b>באברתו יסך לך</b>: תהלים צא, ד."],["1950","160","<b>כו'</b>: ד: ליתא."],["1951","161","<b>דרך הנשר בשמים</b>: משלי ל, יט."],["1952","162","<b>מקום</b>: דזח: מקור."]]],[2300550426,"<b>וזהו</b> ואלה המשפטים אשר תשים לפניהם דוקא דהיינו לבחי' פני אדם שבהם שהוא פני אדה\"ע שבמרכבה שכולל כולם וכמ\"ש ופני אדם לארבעתן כו' שנק' אדם תתאה. והענין הוא כנ\"ל בשרש האבות שהן המרכבה דפני ארי' ושור ונשר ואחר שיהי' ג' מדרגות הללו דמרכבה שהן אוי\"ר ורחמים כנ\"ל אזי יתעורר בחי' אדם שהוא בחי' המוחין דחב\"ד שבמדות, דהיינו ענין בחי' ראי' עין השכל שבלב שלבו יראה בראי' חושית כמו שרואה ומכיר חיי נפשו שזהו עיקר בחי' אדם שנק' בר דעת להכיר את בוראו בלבו ע\"י המוחין דחו\"ב שבלב דוקא, כמ\"ש וידעת היום והשבות אל לבבך בראי' ושמיעה שבלב דוקא, וזהו בחי' אדם תתאה בחי' המוחין דבחי' המל' בלב דכנ\"י והן השבטים <span data-k=\"pg\">תכב</span> ּ שמתכללים בי\"ב גבולי<sup data-n=\"1953\">163</sup> אלכסון<sup data-n=\"1954\">164</sup> ונק' צבאות הוי' כו' (ובזה יש יתרון מעלה לשבטים על האבות כנ\"ל). ולכך אמרו השבטים ליעקב כשם שאין בלבך<sup data-n=\"1955\">165</sup> אלא א' יחו\"ע, כך אין בלבינו אלא א' יחו\"ת דהיינו למהוי אחד באחד<sup data-n=\"1956\">166</sup> יחו\"ע ביחו\"ת הוי' אחד ושמו אחד<sup data-n=\"1957\">167</sup> בלי חילוק מדריגות כלל וכמ\"ש כי הוי' הוא האלקי' כולא חד<sup data-n=\"1958\">168</sup>, לפי שבאתעדל\"ת דבחי' אדם תתאה דמל' נעשה מזה אתעדל\"ע<sup data-n=\"1959\">169</sup> בבחי' אדה\"ע שעל הכסא דאצי' שהוא בחי' המוחין דמדות דז\"א דאצי' והוא מ\"ש כמים הפנים אל פנים<sup data-n=\"1960\">170</sup> כן לב האדה\"ע לאדם תתאה<sup data-n=\"1961\">171</sup> כו'. והוא ענין מ\"ש שבכל משמר יושב הקב\"ה שהוא ו\"ק דאצי' ושאג כארי כו' שזהו בחי' פנימי' הלב כשהוא בבחי' ראי' הלב דוקא (ודוגמא כזו הי' במ\"ת דכתי' פב\"פ דיבר ה' עמכם<sup data-n=\"1962\">172</sup> כו' שהיו רואים את הקולות<sup data-n=\"1963\">173</sup> כו' וכתיב חכמת אדם תאיר פניו הרי י' הדברות שפני האדם הגדול האיר לנש\"י שנק' אדם תתאה וע\"כ על כל דבור פרחה נשמתן כו' מפני שהי' בפנימי' הלב שלהם בראי' שבלב כנ\"ל) (ומעין וקצת דוגמא כזה הי' גם בעולי רגל בג' רגלים דכתיב יראה<sup data-n=\"1964\">174</sup> כו' שזהו אדם תתאה דכנ\"י שעולים ליראות וכשם שבא לראות<sup data-n=\"1965\">175</sup> כו', כך גם מאדם העליון נמשך בבחי' ראיי' כו'). והנה אע\"פ דכמים הפא\"פ יוכל להיות אתעדל\"ע [מ]בחי' אדם העליון דאצי' לאדם תתאה דמל' עכ\"ז צ\"ל בחי' ממוצע ביניהם שיחברם יחד ויהי' אחד עילאה שורה ומתייחד באחד תתאה למהוי אב\"א ממש, ואם לא מצד הממוצע דמשפיע והמקבל כשוש' דחתן וכלה הרי יוכל להיות [שיהי'] בחי' יחוד דיחו\"ע בפ\"ע ויחוד דיחו\"ת בפ\"ע ואע\"פ שיהי' ביחו\"ת כמו ביחו\"ע כמ\"ש כשם שאין בלבך כו', וכן מ\"ש כגוונא דאינון מתייחדי' לעילא<sup data-n=\"1966\">176</sup> ביחו\"ע אוף הכי ממש איהי אתייחדת לתתא בכורסיי' כו', אמנם הנה בחי' הממוצע הזה הוא התורה שניתנה",[["1953","163","<b>השבטים. . בי\"ב גבולי אלכסון</b>: ראה ס' הבהיר סמ\"ב. זהר במדבר קיח, ב ובביאוה\"ז שם פה, א ואילך. מאמרי אדה\"א דברים ח\"ב ע' תסז ואילך. וש\"נ."],["1954","164","<b>בי\"ב גבולי אלכסון</b>: ס\"י פ\"ה, מ\"א. ראה לעיל פ' בא קכז, ד הערה 708."],["1955","165","<b>כשם שאין בלבך</b>: פסחים נו, א. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'סג. וש\"נ. שע\"ת ס, ד ובהערה 9. לקמן פ' תצוה שנא, ב. ויקהל תד, ד."],["1956","166","<b>למהוי אחד באחד</b>: ראה זהר תרומה קלג, סע\"ב ואילך. קלה, סע\"א."],["1957","167","<b>הוי' אחד ושמו אחד</b>: זכרי' יד, ט."],["1958","168","<b>כי הוי' הוא האלקי' כולא חד</b>: נסמן לעיל פ' יתרו רנח, ג."],["1959","169","<b>שבאתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל רנט, ב."],["1960","170","<b>כמים הפנים אל פנים</b>: משלי כז, יט [ושם: לפנים — ראה לעיל קב, ב. וש\"נ]."],["1961","171","<b>כמים הפנים. . לאדם תתאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא</a> פמ\"ו. מאמרי אדה\"ז תקע\"א ע' מד. לקמן פ' תרומה שיב, א. שטז, ד. תצוה שלח, ד. מאמרי אדה\"א ויקרא ח\"א ע' ג בשם הזהר ובהנסמן שם. שע\"ת טו, ד ובהערה 46."],["1962","172","<b>פב\"פ דיבר ה' עמכם</b>: ואתחנן ה, ד."],["1963","173","<b>שהיו רואים את הקולות</b>: יתרו כ, טו."],["1964","174","<b>יראה</b>: משפטים כג, יז."],["1965","175","<b>וכשם שבא לראות</b>: חגיגה ב, א."],["1966","176","<b>כגוונא דאינון מתייחדי' לעילא</b>: ראה זהר תרומה קלה, א."]]],[2300550442,"ע\"י משה כמ\"ש תורה צוה לנו משה<sup data-n=\"1967\">177</sup> כו' וכמ\"ש במ\"ת משה ידבר<sup data-n=\"1968\">178</sup> כו'. והענין כידוע דג' קשרין הן<sup data-n=\"1969\">179</sup> ישראל מתקשראין באוריי' ואוריי' בקוב\"ה והיינו ס\"ר נש\"י<sup data-n=\"1970\">180</sup> שקשורים בס\"ר אותיות<sup data-n=\"1971\">182</sup> התורה<sup data-n=\"1972\">181</sup> גם במקורם הראשון למעלה בבחי' סתים דאוריי' כמו דקוב\"ה סתים וגליא<sup data-n=\"1973\">183</sup> כך אורייתא סתים וגליא וישראל סתים וגליא כו' כמ\"ש בזהר הנסתרות לה' אלקינו<sup data-n=\"1974\">184</sup> והנגלות לנו ולבנינו כו' כידוע דישראל עלו במח' כו', וע\"כ ממילא יובן דאותיות התורה הם בבחי' ממוצעים שע\"י יתחברו חתן וכלה קוב\"ה וישראל יחד כנ\"ל וד\"ל.\n<b>וז\"ש</b> ואלה המשפטים אשר תשים לפניהם, ופי' משפטים היינו ההלכות שבדיני ממונות שבין איש לרעהו וכתרגום כמשפט הראשון כהלכתא קדמייתא<sup data-n=\"1975\">185</sup> כו' וכידוע ההפרש שבין חוקים ומשפטים וכן מ\"ש לעשות צדקה ומשפט<sup data-n=\"1976\">186</sup> כו', וענין ופי' ההלכות שהוא ענין הילוך<sup data-n=\"1977\">187</sup> מורה ב' עניני הילוך, א' הילוך העליון לגבי התחתון מלמעלה למטה, והב' הילוך התחתון לגבי העליון מלמטה למעלה, ושניהם אמת דב' עניני הילוך זה ישנם בהלכות שבתורה, והוא בחי' הילוך אור המשכות וגילוי הארת פנים דחכ' דאדה\"ע להיות מאיר אורו מלמעלה למטה בפני אדם תתאה (כמו<sup data-n=\"1978\">188</sup> בכל מי שיושב ושונה שהקב\"ה יושב ושונה כנגדו ממש, וכמו שהי' במ\"ת [ביו\"ד הדברות] שהאיר פניו לישראל בדבר חכ' דתורה דחכמת אדם תאיר פניו והאירו פניהם כמ\"ש <span data-k=\"pg\">846</span> ּ באור פניך ממש נתת לנו תורת חיים<sup data-n=\"1979\">189</sup> פני אדם התחתון בחי' אנפי זוטרי<sup data-n=\"1980\">190</sup> כו', הרי נמשך מבחי' מוחי' דחכ' אדם העליון לאדם תתאה ונתחברו ונתייחדו יחד ע\"י משה שוש' דמלכא<sup data-n=\"1981\">191</sup> ואהרן שוש' דמטרוניתא<sup data-n=\"1982\">192</sup> כמ\"ש משה ידבר כו') וזהו בבחי' ההילוך מעליון לתחתון מלמעלה למטה. וז\"ש הליכות אלי מלכי בקדש<sup data-n=\"1983\">193</sup> זה הר סיני שהלך האור מעצמו' א\"ס בחכ' דתורה להאיר לנש\"י כמ\"ש וירד ה'<sup data-n=\"1984\">194</sup> כו' וזה הי' ע\"י ממוצע דח\"ע דתורה דאורייתא מתקשרא' בקוב\"ה ממש כמ\"ש בזהר דאורייתא וקוב\"ה כולא חד<sup data-n=\"1985\">195</sup> ממש, וזהו הליכות עולם לו<sup data-n=\"1986\">196</sup> שמטעם זה נק' הלכות שהן נתיבות ודרכים שבהן הולך ונתגלה עצמו' אוא\"ס למטה כו' ולכך נק' ארחות הוי'<sup data-n=\"1987\">197</sup> דרכי הוי'<sup data-n=\"1988\">198</sup>",[["1967","177","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["1968","178","<b>משה ידבר</b>: יתרו יט, יט."],["1969","179","<b>דג' קשרין הן</b>: ראה זהר אחרי עג, א. לעיל פ' שמות ב, ד. וש\"נ."],["1970","180","<b>ס\"ר נש\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא</a> פל\"ז. לעיל פ' בשלח קפג, ג. וש\"נ."],["1971","182","<b>בס\"ר אותיות התורה</b>: ראה מג\"ע אופן קפו. לעיל פ' שמות לב, ב. וש\"נ."],["1972","181","<b>ס\"ר נש\"י שקשורים בס\"ר אותיות התורה</b>: ראה גם לעיל ב, ד. וש\"נ."],["1973","183","<b>דקוב\"ה סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א. לקמן פ' תצוה שמז, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680206\" data-slug=\"torat-chaim\" data-id=\"2300680206\">תו\"ח מקץ ריח, א</a>. המשך תרס\"ו ע' שפה ואילך."],["1974","184","<b>הנסתרות לה' אלקינו</b>: נצבים כט, כח."],["1975","185","<b>כמשפט הראשון כהלכתא קדמייתא</b>: נסמן לעיל רפג, ד."],["1976","186","<b>לעשות צדקה ומשפט</b>: וירא יח, יט."],["1977","187","<b>ההלכות שהוא ענין הילוך</b>: ראה נדה בסופה. מאמרי אדה\"ז תקס\"ב כאן (ע' קנו). מאמרי אדה\"א נ\"ך ע' תב. וש\"נ."],["1978","188","<b>כמו</b>: ד: וכן."],["1979","189","<b>כמ\"ש באור פניך. . נתת לנו תורת חיים</b>: סיום תפלת שמו\"ע [בדילוג השמות]. יא: ליתא. וראה בהערה הבאה."],["1980","190","<b>פני. . זוטרי</b>: ד: ליתא. יא: פני אד\"ם תתאה בחי' אנפי זוטרי כמ\"ש כי באור פניך נתת לנו תורת חיים. וראה הערה שלפנ\"ז."],["1981","191","<b>משה שוש' דמלכא</b>: נסמן לעיל פ' יתרו רסג, ב."],["1982","192","<b>ואהרן שוש' דמטרוניתא</b>: נסמן לעיל פ' יתרו רסט, ד."],["1983","193","<b>הליכות אלי מלכי בקדש</b>: תהלים סח, כה."],["1984","194","<b>וירד ה'</b>: יתרו יט, כ."],["1985","195","<b>דאורייתא וקוב\"ה כולא חד</b>: מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא (פ\"ד</a> ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["1986","196","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["1987","197","<b>ארחות הוי'</b>: תהלים כה, י."],["1988","198","<b>דרכי הוי'</b>: שמו\"ב כב, כב. הושע יד, י. תהלים יח, כב."]]],[2300550457,"כידוע והוא המייחד ומחבר יחו\"ע ליחו\"ת למהוי חד ממש (כרב שמאיר מעצם אור חכמתו לתלמידו שחכ' זו שמשפיע לו בחי' ממוצע שיתחברו יחד והיו לאחדים ממש). והילוך הב' הוא מלמטה למעלה מכנ\"י לקוב\"ה שזהו בהילוך התחתון לגבי העליון כמו אחרי ה' ילכו כו' דהיינו [כמו] אם בחוקתי תלכו<sup data-n=\"1989\">199</sup> כו' וכה\"ג, וזהו בחי' העלי' והתקשרות דנש\"י בכלל ובפרט בתו\"מ שהתורה היא בחי' ממוצע גם להעלות לנש\"י שילכו למעלה מעלה ברום המעלות כמו ילכו מחיל אל חיל<sup data-n=\"1990\">200</sup> כו' כמ\"ש בהתהלכך תנחה אותך<sup data-n=\"1991\">201</sup> כו', וזהו מצד שישראל מתקשראין באורייתא כולא חד<sup data-n=\"1992\">202</sup> שפנימי' אותיות התורה הן מקורי' לחיות דנש\"י בס\"ר בכלל ובפרט בכאו\"א מישראל כו' כמ\"ש כי אמרתך חייתני<sup data-n=\"1993\">203</sup> ממש (ולכך נק' הלכה אותיות הכלה<sup data-n=\"1994\">204</sup> כמ\"ש במ\"א ע\"פ מזמור לתודה<sup data-n=\"1995\">205</sup> הריעו לה' כו'). ונמצא מובן מזה דהתורה בחי' ממוצע מלמעלה למטה מן המשפיע אל המקבל כנ\"ל בהילוך העליון דהליכות אלי [כו'] הליכות עולם כו' גם בחי' ממוצע מלמטה למעלה מן המקבל דכנ\"י אל המשפיע כנ\"ל וד\"ל.\n<b>ובזה</b> יובן מ\"ש או יחזק במעוזי<sup data-n=\"1996\">206</sup> שהוא עוז דתורה<sup data-n=\"1997\">207</sup> כידוע יעשה שלום לי שלום יעשה לי [כו'] ב' של[ו]מות שלום בפמשמ\"ע ושלום בפמשמ\"ט<sup data-n=\"1998\">208</sup> דענין השלום הוא בחי' [ה]התחברות וההתקשרות דמשפיע [ו]מקבל או ב' הפכים יחד כמו עושה השלום במרומיו<sup data-n=\"1999\">209</sup> כו', ויש בזה ב' מדרגות א' בחי' התחברות דמשפיע במקבל כמו הנני נותן לו את בריתי שלום<sup data-n=\"2000\">210</sup> בפמשמ\"ע שע\"ז א' יעשה שלום לי מלמעלה למטה כנ\"ל ע\"י עסק התורה וכנ\"ל בהילוך העליון לתחתון, ושלום יעשה לי בפמשמ\"ט שזהו התחברות דמקבל במשפיע כנ\"ל בהילוך שמלמטה למעלה בהתקשרות דנש\"י באותיות התורה וז\"ש ורב שלום בניך<sup data-n=\"2001\">211</sup> כו' כמשי\"ת. ובזה יובן ג\"כ מ\"ש ע\"פ כ\"א בתורת ה' חפצו<sup data-n=\"2002\">212</sup> ובתורתו יהגה דמעיקרא עביד [אינש] אדעתי' דנפשי' כו' ונק' תורת הוי' כו' ואח\"כ ובתורתו יהגה כו' שהוא לשם התורה עצמה כו' שנק' עוסק בתורה לשמה לשם התורה עצמה<sup data-n=\"2003\">213</sup> כידוע. וביאור הענין יובן ע\"פ הנ\"ל בב' מיני הילוך",[["1989","199","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."],["1990","200","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["1991","201","<b>בהתהלכך תנחה אותך</b>: משלי ו, כב."],["1992","202","<b>כולא חד</b>: בד: כנ\"ל עד."],["1993","203","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["1994","204","<b>הלכה אותיות הכלה</b>: ראה פע\"ח (שער הנהגת הלימוד) שי\"ז. לעיל פ' שמות ג, ב. וש\"נ."],["1995","205","<b>מזמור לתודה</b>: תהלים ק, א. ראה מאמרי אדה\"א נ\"ך ע' קנז. פיה\"מ צג, ב."],["1996","206","<b>או יחזק במעוזי</b>: ישעי' כז, ה."],["1997","207","<b>במעוזי שהוא עוז דתורה</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רפד. וש\"נ. לעיל פ' יתרו רנג, ג."],["1998","208","<b>שלום בפמשמ\"ע ושלום בפמשמ\"ט</b>: סנהדרין צט, ב."],["1999","209","<b>עושה השלום במרומיו</b>: איוב כה, ב [ושם: שלום — ראה לעיל יג, ד. וש\"נ. ד: שלום]."],["2000","210","<b>הנני נותן לו. . שלום</b>: פינחס כה, יב."],["2001","211","<b>ורב שלום בניך</b>: ישעי' נד, יג."],["2002","212","<b>כ\"א בתורת ה' חפצו</b>: תהלים א, ב. ראה גם לעיל פ' יתרו רנו, ג. לקמן פ' ויקהל תיז, א. וש\"נ. וראה סה\"מ מלוקט ח\"ו ע' קה."],["2003","213","<b>עוסק בתורה לשמה לשם התורה עצמה</b>: ראה פע\"ח שער הנהגת הלימוד. לעיל פ' וארא פ, ד. וש\"נ."]]],[2300550472,"דהלכות שבתורה שבחי' הילוך מלמטה למעלה בהתקשרות דנש\"י באותיות התורה ז\"ש<sup data-n=\"2004\">214</sup> אדעתי' דנפשי' כדי להמשיך אור דתורה בנשמתו להחיות[ה] באור וחיות חדש כמו אמרתך חייתני כו' וכמ\"ש ר\"ש חדאי לך נפשאי<sup data-n=\"2005\">215</sup> לך קראי לך תנאי לך דוקא בשבילה להאיר באור החיים כו' כנ\"ל, ואח\"כ <span data-k=\"pg\">תכג</span> ּ ובתורתו יהגה כו' לשם התורה עצמה ע\"כ נק' תורתו ע\"ש שהוא המשיך בה מעצמו' אוא\"ס שיאיר באור דתורה והוא בחי' הילוך העליון דעצמות א\"ס בתורה להיות התורה מתקשרא' בקוב\"ה כו', וכמ\"ש בס' הבהיר דדוד המלך הי' מחבר<sup data-n=\"2006\">216</sup> תורה שלמעלה בהקב\"ה כו' וכן א' דוד אני תורתך שעשעתי<sup data-n=\"2007\">217</sup> שהמשיך מבחי' שעשועי' העצמי' דא\"ס שנק' שעשוע המלך בעצמותו<sup data-n=\"2008\">218</sup> בשעשועי' דתורה כו' וד\"ל. וזהו לשמה לשם התורה ולא בשביל להאיר אור בנשמתו רק להמשיך אוא\"ס בח\"ע דתורה וע\"כ נק' תורתו כי בתחילה דעסיק אדעתי' דנפשי' לבד אמר תורת הוי' חפצו כמ\"ש למען תהי' תורת ה' בפיך<sup data-n=\"2009\">219</sup> כו' כי הוא חייך ממש כו', אבל עוסק בתורה לשמה לשם התורה עצמה. וזה[ו] שנק' תורתו אומנתו שפטור מן התפלה<sup data-n=\"2010\">220</sup> כידוע שהתורה נק' כלי אומנתו לבד כמו שנאמר על התורה ואהי' אצלו אמון אומנא<sup data-n=\"2011\">221</sup> כו' (כמשי\"ת) (וז\"ש בזהר בעדן [ד]עוה\"ב עין לא ראתה<sup data-n=\"2012\">222</sup> [כו'] יעשה למחכה לו למאן דדייק<sup data-n=\"2013\">223</sup> מילין דחכ[מתא] דתורה מפני שע\"י התקשרות עיונו בתורה ממשיך משעשועי' העצמי' הנ\"ל להיות משתעשע בתורה והוא העדן דעוה\"ב וד\"ל).\n<b>ובכ\"ז</b> יובן יותר מ\"ש ואלה המשפטים שהן ההלכות דוקא אשר תשים לפניהם על פניהם<sup data-n=\"2014\">224</sup> לבחי' פני אדם תתאה דהיינו כדי שישים וימשיך מבחי' פנים העליון דאדה\"ע בפנים דכנ\"י מטעם הנ\"ל ולהמשיך המוחין העליונים מזה אל זה בבחי' פא\"פ דוקא כו'. ולהבין שורש הדברים איך יכול להיות בכח המשפטים שהן ההלכות שיושם לפניהם לחבר ולייחד עי\"ז בחי' פנים העליון בפנים התחתון דכנ\"י, הנה יש להקדים ענין א' והוא מ\"ש על התורה ואהי' אצלו אמון אמון מוצנע<sup data-n=\"2015\">*225</sup> כו' וכמו אומן הבונה עפ\"י ציווי החכם שמצוה לו אופן סדר הבנין בכל פרטיו כך ולא כך כו', והנה ודאי שזה השכל שמשכיל החכם באופן מעשה הבנין שהוא עשי' גשמי' שנק' שכל שבעשי' לבד",[["2004","214","<b>ז\"ש</b>: ד: זהו שא'."],["2005","215","<b>ר\"ש חדאי לך </b>[בד: ליתא]<b> נפשאי</b>: ראה פסחים סח, סע\"ב."],["2006","216","<b>בס' הבהיר דדוד. . מחבר</b>: ראה שם סקצ\"ו. לעיל פ, א. וש\"נ."],["2007","217","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["2008","218","<b>שעשוע המלך בעצמותו</b>: נסמן לקמן פ' תרומה שיח, ב."],["2009","219","<b>למען תהי'. . בפיך</b>: בא יג, ט."],["2010","220","<b>תורתו אומנתו שפטור מן התפלה</b>: ראה גם לעיל רנו, ב. וש\"נ."],["2011","221","<b>ואהי' אצלו אמון אומנא</b>: משלי ח, ל. ב\"ר בתחלתו."],["2012","222","<b>[ד]עוה\"ב עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["2013","223","<b>יעשה למחכה לו למאן דדייק</b>: ישעי' שם. ראה זהר ח\"ש קל, ב. לעיל ח, ג. וש\"נ."],["2014","224","<b>על פניהם</b>: הזח: ליתא."],["2015","*225","<b>אמון מוצנע</b>: ב\"ר בתחלתו."]]],[2300550487,"ואין לו ערך כלל וכלל לגבי עצם כח חכמתו שמשכיל במושכלות עמוקות מאד כו', עכ\"ז הרי גם שכל מצומצם זה שמלובש בעשי' גשמי' נלקח מעצם כח החכ' שבו דוקא וע\"כ כל שהוא חכם בעצם יותר יותר יש חכ' עמוקה גם במעשה הבנין וכמ\"ש בחכ' יבנה בית<sup data-n=\"2016\">225</sup> כו'. כך יובן למעלה דבחכ' דבמע\"ב דכתי' כולם בחכ' עשית<sup data-n=\"2017\">226</sup> כו' וכמ\"ש בראשית ברא ות\"א בחוכמתא<sup data-n=\"2018\">227</sup> כידוע הגם שזהו חכ' מצומצמת מאד כמו שכל שבעשי' כנ\"ל, עכ\"ז נלקחה שרש חכ' זאת מבחי' כח חכמתו העצמי' ית' שנק' חכים ולא בחכ' ידיעא כלל כמ\"ש לתבונתו אין מספר<sup data-n=\"2019\">228</sup> כו', והוא בחי' חכ' שבתורה הקדומה שקדמה לעולם אלפים שנה<sup data-n=\"2020\">229</sup> כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"2021\">230</sup> שזהו בראשית בשביל התורה שנק' ראשית<sup data-n=\"2022\">231</sup> כידוע שלפ\"ע כח החכ' העצמי' כך הוא ערך צמצום החכ' שבעשי' שבמע\"ב כו'. וז\"ש ואהי' אצלו אמון אצלו ממש כו' אמון מוצנע שזהו כמ\"ש בזהר אסתכל באוריי' וברא עלמא<sup data-n=\"2023\">232</sup> כמו האומן שבונה ע\"פ ראייתו בלוח שמצוייר בו אופן מעשה הבנין וציור זה נעשה ע\"פ שכל וחכ' עמוקה שהוא חכ' שבתורה ולכן נק' אמון מוצנע אמון [מופלא]<sup data-n=\"2024\">233</sup> כו' ששרשה בבחי' פלאות חכ'<sup data-n=\"2025\">234</sup> <span data-k=\"pg\">848</span> ּ שנק' חכים ולא בחכ' ידיעא כו' (וז\"ש ה' בחכ' יסד ארץ<sup data-n=\"2026\">235</sup> כו') (כמשי\"ת) וד\"ל.\n<b>והנה</b> כתי' בי מלכים ימלוכו<sup data-n=\"2027\">236</sup> דזהו שהתורה אומרת בי מלכים עליונים ותחתונים ימלוכו, דהנה כתי' מלך במשפט יעמיד ארץ<sup data-n=\"2028\">237</sup> במשפט התורה דוקא להיות שמל' ית' מכ\"ע<sup data-n=\"2029\">238</sup> ומלכותו בכל משלה<sup data-n=\"2030\">239</sup> להחיות רוח שפלים<sup data-n=\"2031\">240</sup> ולזון את כל העולם מקרני ראמים<sup data-n=\"2032\">241</sup> כו', ומה שהוא מנהיג כל העולמות בפרטי [איכות] אופני השפע שלהם [הכל] הוא רק ע\"פ משפט התורה כמ\"ש י\"ב שעות הוי היום<sup data-n=\"2033\">242</sup> ג' שעות הראשונות יושב ועוסק בתורה שניות יושב ודן [את כו'] שלישית יושב וזן כו', [ו]הוא ב\"ד ש\"מ דהיינו חכ' שבמל'<sup data-n=\"2034\">243</sup> דאצי' (שם ע\"ב<sup data-n=\"2035\">244</sup> דמל') שנלקחה חכ' זאת מחכ' דתורה שהוא חכמתו ית' העצמי' כנ\"ל במקור בנין התהוות העולמות שהוא רק שכל שבעשי' שנלקחה מעצמיות החכ' שיצוייר בלוח הבנין<sup data-n=\"2036\">245</sup> כו' כמ\"ש ואהי' אצלו אמון אומנא כו' שזהו עכ\"פ לפ\"ע עצם כח גדולת חכמתו אם רב או מעט (וכשיחת ת\"ח [ש]צריכים לימוד<sup data-n=\"2037\">246</sup> כו', כך בחי' נובלות",[["2016","225","<b>בחכ' יבנה בית</b>: משלי כד, ג."],["2017","226","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["2018","227","<b>בראשית ברא ות\"א </b>[ז: ליתא. ח: כו' ותרגום ירושלמי]<b> בחוכמתא</b>: בראשית א, א. וראה בתרגום ירושלמי שם. מובא בשם הת\"א בכ\"מ ומהם: מאמרי אדה\"א דברים ח\"א ע' עדר. וש\"נ. בראשית ע' עז. וש\"נ."],["2019","228","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["2020","229","<b>שקדמה לעולם אלפים שנה</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["2021","230","<b>ה' קנני ראשית דרכו</b>: משלי יח, כב."],["2022","231","<b>בראשית בשביל התורה שנק' ראשית</b>: בראשית א, א וברש\"י שם. הנסמן בלקו\"ש נח (כרך ג) ע' 755."],["2023","232","<b>אסתכל באוריי' וברא עלמא</b>: נסמן לעיל פ' יתרו רנט, ד."],["2024","233","<b>אמון [מופלא]</b>: ראה תו\"א לב, א ובהנסמן במ\"מ לשם (מהדורת תנש\"א). לעיל פ' בשלח קעט, ב הערה 680."],["2025","234","<b>פלאות חכ'</b>: ראה גם לעיל פ' שמות כא, ב. וש\"נ."],["2026","235","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["2027","236","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["2028","237","<b>מלך במשפט יעמיד ארץ</b>: משלי כט, ד. ראה לעיל פ' בשלח קעג, א. וש\"נ."],["2029","238","<b>שמל' ית' מכ\"ע</b>: תהלים קמה, יג."],["2030","239","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["2031","240","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["2032","241","<b>ולזון. . מקרני ראמים</b>: נסמן בהערה הבאה."],["2033","242","<b>י\"ב שעות הוי היום</b>: ראה ע\"ז ג, ב."],["2034","243","<b>ב\"ד ש\"מ. . שבמל'</b>: ראה גם זהר משפטים קיז, א. לעיל פ' בא פח, א. וש\"נ."],["2035","244","<b>חכ'. . שם ע\"ב</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ב. מאמרי אדה\"א שמות ח\"ב ע' שנג. וש\"נ."],["2036","245","<b>שיצוייר. . הבנין</b>: ד: שצייר. . בד: הבונים."],["2037","246","<b>וכשיחת ת\"ח [ש]צריכים לימוד</b>: ראה סוכה כא, ב. מאמרי אדה\"א דברים ח\"א ע' ריז. וש\"נ. ח\"ד ע' א'ריט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670071\" data-slug=\"torat-chaim\" data-id=\"2300670071\">תו\"ח בראשית א, ד</a> בהערה 54."]]],[2300550501,"דחכ' שמ\"ע<sup data-n=\"2038\">247</sup> בשיחה דו\"מ<sup data-n=\"2039\">248</sup> כו'). כך היא ג\"כ בענין הנהגות העולמות בחד\"ת<sup data-n=\"2040\">249</sup> כמ\"ש לאנהגא בהון עלמין<sup data-n=\"2041\">250</sup> לגזור או[מר] כך ולא כך בעולמו' עליונים ותחתונים כמלך שגוזר אומר על יושבי ארצו שנק' חכ' המלוכה לבד שהיא קטנה בערך לגבי עצמי' גדולת החכ' שלו לעצמו כנ\"ל, אבל מ\"מ נלקח כל פרטי ציווי שלו כך ולא כך רק לפ\"ע<sup data-n=\"2042\">251</sup> עצם החכ' העמוקה שלו שלמד לעצמו והוא חכ' דתוה\"ק שנא' ואהי' אצלו כו' וד\"ל. וזהו בי מלכים ימלוכו בי דוקא דהיינו בחכ' דתוה\"ק מלכים העליונים וכמל' דאצי' בבריאה ומל' דבריאה ביצי' עד מל' דמל' דעשי' כל פרטי הנהגות דמל' בעולמות עד זמן<sup data-n=\"2043\">252</sup> את כל עוה\"ז הגשמי' כו' הכל מלך במשפט דתורה יעמיד ארץ, וכמו בי\"מ שגזר וא'<sup data-n=\"2044\">253</sup> יהי אור יהי רקיע תדשא [ה]ארץ<sup data-n=\"2045\">254</sup> וכאשר גזר אומר כן הי' לפי שדבר מלך שלטון<sup data-n=\"2046\">255</sup>, אבל הי' זה רק ע\"פ חכ' דתורה כמ\"ש בראשית בחוכמתא כו'. וזהו שאמר מתנית[י]ן מלכתא<sup data-n=\"2047\">256</sup> דהמשנה הוא מל[כתא] שגוזר ואו' כך ולא כך ואין הכוונה על הלכות ש[ב]משניות עצמן שגוזרים ואומרים בהנהגות המל' בעניני המלוכה, שהרי דברי ההלכות מדברים בעניני החכ' דתורה כמו להבדיל בין טמא לטהור וכשר ופסול וענין מ\"ע כשבת ופסח וכה\"ג. אלא הענין הוא דע\"ש זה נק' המשנה בשם מל' לפי שמחכ' דתו' זו שבהלכות נמשך שרש ההנהגות<sup data-n=\"2048\">257</sup> דמל' דאצי' בבי\"ע לגזור אומר כך ולא כך, וע\"כ נק' הלכות המשנה בשם מל' כמ\"ש מאן מלכי רבנן<sup data-n=\"2049\">258</sup> כו' ונק' בוניך שעוסקי' בבנינו של עולם<sup data-n=\"2050\">259</sup> כו' וכמ\"ש ואשים דברי בפיך<sup data-n=\"2051\">260</sup> [כו'] לנטוע שמים וליסוד ארץ שקיום [ויסוד] שמים וארץ וכל צבאם ופרטי אור השפע שלהם הכל נלקח מדבר ה' זו הלכה<sup data-n=\"2052\">261</sup> וע\"כ נק' הלכה הליכות עולם כו'. אבל עצמות ההלכה הוא בחי' הילוך אור החכ' דתורה עצמה בבחי' הפנימי' ועצמי' כנ\"ל ונק' נימין דמטרוניתא<sup data-n=\"2053\">262</sup> כו' וכידוע דהלכה אותיות הכלה כו', ור\"ת דהריעו לה' כל הארץ הלכ\"ה<sup data-n=\"2054\">263</sup> לפי שמקור שפע כל הארץ הוא בהלכה דתורה דוקא, וז\"ש ה' בחכ' יסד ארץ בחכ' דתו' דוקא יסד פרטי ההנהגה דמל' העליונה בארץ וד\"ל.\n<b>וזהו</b> ואלה המשפטים אשר תשים <span data-k=\"pg\">תכד</span> ּ לפניהם משפטים הן ההלכות (ובפרט דיני ממונות ובכל דיני האדם גם בד'<sup data-n=\"2055\">264</sup>",[["2038","247","<b>נובלות דחכ' שמ\"ע</b>: ראה ב\"ר פי\"ז, ה. פמ\"ד, יז."],["2039","248","<b>דו\"מ</b>: ד: די\"מ די' מאמרות."],["2040","249","<b>בחד\"ת</b>: בז: בחד\"ר בחסד דין רחמים."],["2041","250","<b>לאנהגא בהון עלמין</b>: ת\"ז בהקדמה (יז, א)."],["2042","251","<b>לפ\"ע</b>: בד: ע\"פ."],["2043","252","<b>זמן</b>: ד: זן."],["2044","253","<b>וכמו. . וא'</b>: ד: כמו בתו' שא' וגזר."],["2045","254","<b>יהי אור יהי רקיע תדשא [ה]ארץ</b>: בראשית א, ג. ו. יא."],["2046","255","<b>שדבר מלך שלטון</b>: קהלת ח, ד."],["2047","256","<b>מתנית[י]ן מלכתא</b>: ביצה כח, ב."],["2048","257","<b>ההנהגות</b>: ד: ההלכות."],["2049","258","<b>מאן מלכי רבנן</b>: ראה גיטין סב, א. הנסמן לעיל פ' בשלח קנט, ג."],["2050","259","<b>בוניך שעוסקי' בבנינו של עולם</b>: ראה ברכות סד, א. שבת קיד, א. מאמרי אדה\"א דברים ח\"ד ע' א'תכו. וש\"נ."],["2051","260","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["2052","261","<b>מדבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["2053","262","<b>ההלכה. . נימין דמטרוניתא</b>: ראה גם לעיל ג, ב. וש\"נ."],["2054","263","<b>ור\"ת דהריעו לה'. . הלכה</b>: תהלים ק, א. ראה לקו\"ת להאריז\"ל שם. לעיל פ' שמות כא, א. וש\"נ."],["2055","264","<b>בד'</b>: ד: בדיני."]]],[2300550515,"נזיקי' כו' שלמעלה מדיני או\"ה כשר פסול שהוא מדבר בצו\"ח שלמטה מאדם), ופי' הלכות הללו היינו בחי' הילוך האור והשפע דח\"ע דתורה שנק' הליכות עולם כו' שנעשה מקור לחכ' דמל' דאצי' שנק' אדם תתאה<sup data-n=\"2056\">265</sup> להנהגות מדת מל' בבי\"ע והוא בחי' פני אדם תתאה דכנ\"י כידוע. וע\"י בחי' משפטי' הללו דוקא הוא שנמשך והולך בחי' הארת אור פנים אדה\"ע להאיר פניו לפני אדם תתאה שהן כנ\"י דהיינו להמשיך בחי' מוחין דחב\"ד להיות בבחי' פב\"פ דוקא, והוא לפי שמשפטים הללו הן בחי' ממוצע ואמצעי בין חכ' אדה\"ע לאדה\"ת משום דאוריי' מתקשרא בקוב\"ה וישראל מתקשראן באוריי' בהילוך שמלמטה למעלה שיהי' בהם יחוד תמידי בלי הפסק לעולם כו' וד\"ל.\n<b>ומ\"ש</b> אשר תשים דוקא שמשה הוא שישים את המשפטים [לפניהם] כו' כענין שם שם לו חוק ומשפט<sup data-n=\"2057\">266</sup> כו' וכענין ותורה שם בישראל<sup data-n=\"2058\">267</sup> שימה זו היא לחק עולם שכמשפט הזה יעשה בין איש ואיש, והן בחי' המדות שבתורה שנק' משפט שכולל חו\"ג במיצוע נכון שנק' אמת והן ששה מדות בכלל והוא שא' שש שנים יעבוד כו'. וגם כאן בענין המשכה דפני אדם עילאה לאדם תתאה כמו להנהגת המל' הם ששה מדות שזהו ואלה גימ' ל\"ו<sup data-n=\"2059\">268</sup> ופי' בהפרש<sup data-n=\"2060\">269</sup> שכל מדה כלולה מו' מדות וששה מדות הכולל' יחד הוא ו' דואלה (שהוא שם<sup data-n=\"2061\">270</sup> מ\"ב<sup data-n=\"2062\">271</sup> שהוא בחי' גבורה בהעלא'<sup data-n=\"2063\">272</sup> המל' למעלה שבהן יוכל להיות העלא' בהילוך מלמטה למעלה (כענין שש מעלות לכסא<sup data-n=\"2064\">273</sup> שש כנפי' לא[חד]<sup data-n=\"2065\">274</sup> כידוע) כמו [צדיקים] ילכו בם<sup data-n=\"2066\">275</sup>. וזהו אשר תשים לפניהם לפני הדו\"ר שהן הסנהדרין שידעו לשפוט את העם וידעו דרכי המשפט שילכו בם שזהו הלכה אותיות הכלה כנ\"ל. ועכ\"ז<sup data-n=\"2067\">276</sup> יובן כפשוטו אשר תשים לפניהם לפני חכמי ישראל תשים משפטים אלה שבהן יחוברו ויתייחדו למעלה באדה\"ע כנ\"ל וד\"ל. והטעם שע\"י משה דוקא ידוע לפי ששרש נשמת משה הי' מבחי' הדעת<sup data-n=\"2068\">277</sup> דאדם עילאה שהוא נק' מפתחא דכליל שית<sup data-n=\"2069\">278</sup> כו', והוא בבחי' פנימי' דשם מ\"ה דח\"ע העצמי' שבתוה\"ק כמ\"ש בו מן המים משיתיהו<sup data-n=\"2070\">279</sup> מבחי' מים עליונים דחכ' הקדומה, וע\"כ הי' ביכולתו דוקא לעשות חיבור ויחוד להאיר ולהמשיך מעצמיות חכ' ית' בחכ' דאדם תתאה בפנימי' וחיצוני'",[["2056","265","<b>דמל'. . אדם תתאה</b>: ראה גם לעיל פ' בשלח קצח, ד. וש\"נ."],["2057","266","<b>שם שם לו חוק ומשפט</b>: בשלח טו, כה."],["2058","267","<b>ותורה שם בישראל</b>: תהלים עח, ה."],["2059","268","<b>ששה מדות. . ואלה </b>[יא: ניתוסף עה\"ג: אלה]<b> גימ' ל\"ו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת</a> להאריז\"ל ישעי' מט, כא. לקמן פ' ויקהל תטז, ג. תיח, א. פ' פקודי תמד, א. תמז, א. תמח, ג. תנה, ג. תנח, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670519\" data-slug=\"torat-chaim\" data-id=\"2300670519\">ז, א</a>. שעה\"י קלד, ב. תו\"ח נח נו, ב ובהערה 15."],["2060","269","<b>ופי' בהפרש</b>: הז: ופ\"ו [ ו' פעמים ו'] ובפרט. יא: ופי' בפרט."],["2061","270","<b>דואלה. . שם מ\"ב</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370224\" data-slug=\"torah-or\" data-id=\"3901370224\">תו\"א שמות מט, ד</a>."],["2062","271","<b>שם מ\"ב</b>: ראה זהר תרומה קלב, ב. מאמרי אדה\"א שמות ח\"א ע' קמא. וש\"נ. רשימות חוב' מא [לפ' אחו\"ק — מכתב להרב בראנדט]."],["2063","272","<b>שם מ\"ב. . בהעלא'</b>: ראה זהר שם. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשטו ובהנסמן במ\"מ לשם."],["2064","273","<b>שש מעלות לכסא</b>: מל\"א י, יט."],["2065","274","<b>שש כנפי' לא[חד]</b>: ישעי' ו, ב."],["2066","275","<b>[צדיקים] ילכו בם</b>: הושע יד, י [ושם: וצדיקים — ראה מאמרי אדה\"א שמות ח\"א ע' ק. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680180\" data-slug=\"torat-chaim\" data-id=\"2300680180\">תו\"ח ויחי רמב, א</a>]."],["2067","276","<b>ועכ\"ז</b>: הז: ועפ\"ז."],["2068","277","<b>נשמת משה. . הדעת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["2069","278","<b>הדעת. . מפתחא דכליל שית</b>: ראה זהר (ספרא דצניעותא פ\"א) תרומה קעז, רע\"א. לקמן פ' תצוה שנה, ב. ויקהל תיא, ג. אמ\"ב שער התפילין קכא, א. וש\"נ. מאמרי אדה\"א שמות ח\"ב ע' שפט. וש\"נ. במדבר ח\"ה ע' א'תתסא ואילך."],["2070","279","<b>מן המים משיתהו</b>: שמות ב, י. ראה גם לעיל פ' שמות מג, א. וש\"נ."]]],[2300550528,"שהוא ת\"ת<sup data-n=\"2071\">280</sup> דתו' לפניהם לנש\"י ולהנהגות העולמות בחכ' דמל' דאצי', וכמ\"ש בזהר ע\"פ חכמות בחוץ תרונה<sup data-n=\"2072\">281</sup> ח\"ע דאתמשיך בח\"ת כו' וכמ\"ש תנו עוז לאלקי'<sup data-n=\"2073\">282</sup> לח\"ת דמל' שנק' אלקי'<sup data-n=\"2074\">283</sup> כמו עד [ה]אלקי'<sup data-n=\"2075\">284</sup> כו', ומי הממשיך כח ועוז זה לחכ' דמל' זהו ע\"י משה דוקא שנק' איש האלקי'<sup data-n=\"2076\">285</sup> ונק' מחוקק<sup data-n=\"2077\">286</sup> שהוא בחי' יסוד אבא<sup data-n=\"2078\">287</sup> שהן בחי' המשפטים הנ\"ל שנמשך והושם לבני<sup data-n=\"2079\">288</sup> אדם תתאה ע\"י דוקא, כי משה הוא ענין א' עם המשפטים עצמן ע\"כ הוא המחבר וממשיך מח\"ע לח\"ת להיות הליכות עולם לו כו' כמו משה ידבר כו' וד\"ל.\n<b>והנה</b> מ\"ש אשר תשים לפניהם היינו לבחי' פני אדם שבכ\"א בפרט כי ד' דגלים דישראל הם כדוגמת ד' מחנות שכינה<sup data-n=\"2080\">289</sup> וכמרכבה דפני ארי' אל הימין כו' שא' ופני אדם לארבעתן<sup data-n=\"2081\">290</sup> דהיינו שם מ\"ה דחכ' שכוללם יחד והוא בחי' פני אדם <span data-k=\"pg\">850</span> ּ בכלל ובפרט וכמ\"ש ודמות פניהם פני אדם<sup data-n=\"2082\">291</sup> כו'. והענין הוא כמבו\"ל בענין פני ארי' להימין שהוא בחי' אהבה זהו התפעלות מדת האהבה שנולדה מן השכל והטעם בהשגה האלקי' שמוליד אהבה זו וה[י]א בחי' פני אדם בפרט [במדרגה] דפני ארי' להימין, וכמ\"כ בסט' דדרום בדגל ראובן<sup data-n=\"2083\">292</sup> כו' הוא<sup data-n=\"2084\">293</sup> בחי' המוחין שבמדת אהבה שלהם כמו בראי' עין השכל שבלב ועומק המושג שבלב ועי\"ז נתהפך גם הרצון הזר שלא יומשך אחר ההבל ויהי' לו רק לב א' ממש כנ\"ל. ועכ\"ז יש בזה בחי' תערובות מעט מצד בחי' הישות וגסות שמרגיש בעצמו ונחשב בעינ[י]ו לעובד ה' באמת ויש לו מזה חיות רב לעצמו כו', ולא בזה ישכון אור ה' כי אינו [שורה] רק בבחי' ביטול המציאות בהעדר הרגשת עצמו מכל וכל שנק' מ\"ה, והוא כשאינו מרגיש א\"ע כלל שיש לו אהבה וזהו ביטול היש לאין האלקי בתכלית ע\"י בחי' מ\"ה דחכ' דוקא. וכמ\"כ בבחי' פני שור מהשמאל בעומ\"ש שלימה בכפיי' הרע שבלבו כו' כנ\"ל גם בזה יוכל להיות תערובות מעט מאשר הוא עושה דבר מה ונחשב בעצמו לירא אלקי' בבחי' יש ודבר מה, וגם זה צ\"ל בבחי' הביטול בעצמו שלא ירגיש א\"ע ביראה זו ועומ\"ש זה בביטול עצמי לבטל כל בחי' הגסות וישות שלא יהי' נחשב לדבר מה בעיניו, אדרבה יהי' כחוטא בעיניו משום דכמי דבעי למעבד<sup data-n=\"2085\">294</sup> כו', ובחי' ביטול עצמו בזה בא ונמשך ג\"כ ע\"י בחי' שם מ\"ה דחכ' שהוא בחי'",[["2071","280","<b>ת\"ת</b>: דזיא: ח\"ת."],["2072","281","<b>חכמות בחוץ תרונה</b>: משלי א, כ. ראה זהר תולדות קמא, ב. מאמרי אדה\"א בראשית ע' קכג. וש\"נ."],["2073","282","<b>תנו עוז לאלקי'</b>: תהלים סח, לה. ראה פע\"ח (שער התפלה) ש\"א, פ\"ז. (שער הק\"ש) ש\"ח, פי\"ב. מאמרי אדה\"א בראשית ע' קלח. וש\"נ. דרושי חתונה ח\"א ע' קנג."],["2074","283","<b>דמל' שנק' אלקי'</b>: ראה זהר בראשית כב, א. אחרי סה, א. לעיל פ' וארא עה, ב. וש\"נ."],["2075","284","<b>עד [ה]אלקי'</b>: משפטים כב, ח."],["2076","285","<b>משה. . איש האלקי'</b>: ברכה לג, א. תהלים צ, א."],["2077","286","<b>משה. . ונק' מחוקק</b>: ברכה לג, כא. ראה גם מאמרי אדה\"א דברים ח\"א ס\"ע קצג ואילך. וש\"נ. נ\"ך ס\"ע סה. לעיל יב, ד."],["2078","287","<b>משה. . יסוד אבא</b>: נסמן בהערה 277."],["2079","288","<b>לבני</b>: דזיא: לפני."],["2080","289","<b>ד' דגלים. . ד' מחנות שכינה</b>: ראה זהר במדבר קיח, ב. ביאורי הזהר שם פה, א."],["2081","290","<b>ופני אדם לארבעתן</b>: ז: מחק תיבות אלו. וראה לעיל הערה 3."],["2082","291","<b>ודמות פניהם פני אדם</b>: יחזקאל א, י."],["2083","292","<b>דדרום בדגל ראובן</b>: במדבר ב, י. ראה גם לעיל סו, ב. וש\"נ."],["2084","293","<b>כו' הוא</b>: ד: כי היא. ז: כו' היו. יא: הי'."],["2085","294","<b>דכמי דבעי </b>[דז: דכדבעי]<b> למעבד</b>: ראה כתובות סז, א."]]],[2300550541,"אדם שבבחי' פני שור. וכמ\"כ כפני נשר בבחי' הרחמים אע\"פ שהוא בבחי' שפלות ע\"כ צ\"ל ע\"י בחי' ביטול דמ\"ה דוקא.\n<b>והנה</b> כל בחי' ביטול במדות דאוי\"ר ורחמים הנ\"ל אינו אלא בחי'<sup data-n=\"2086\">295</sup> ביטול הגסות והישות שיש בזה שנק' ביטול היש לאין לבד ואין זה ערך כלל לגבי בחי' ביטול בעצם בבחי' אין בעצם, כידוע שזהו בחי' מ\"ה בעצם דפנימי' חכ' והוא בחי' מדרגת משה שא' ונחנו מ\"ה כו' בעצם<sup data-n=\"2087\">296</sup> שהוא בחי' תכלית הביטול במציאות בלי ירגיש א\"ע כלל [וכלל] שזהו באין העצמי' דחכ'<sup data-n=\"2088\">297</sup> דוקא. ולזאת הי' מוכרח שיהי' נמשך מבחי' מ\"ה [זה] העצמי' דמשה מה שמו<sup data-n=\"2089\">298</sup> כו' במדות דאדם תתאה דכנ\"י שהוא במוחין שלהם שנק' פני אדם להיות מקור למוחין הללו שיהי' גם בהם בחי' ביטול לאין האלקי בעצם שלמעלה מן הטעם והשגה ובלתי מורגש בעצמו כלל וכלל (ולא כמו שמרגיש בעצמו גם בחי' הביטול וכמו ופילגשו ושמה ראומ\"ה<sup data-n=\"2090\">299</sup> ראו שאני בטל כו' וכמ\"ש במ\"א), ואז יכול להיות בחי' ביטול דמה בעצם הזה אף במלאכים דמרכבה דפני ארי' ושור כו' בבחי' פני אדם שבהם לבלי יתפסו לבחי' יש ודבר מה במציאות כלל (וכמ\"ש אלפי [שנא\"ן] שאינן<sup data-n=\"2091\">300</sup> במציאות) עד גם בגופים גשמי' ששרשם מפני שור יש בחי' ביטול זה העצמי' כו'). וזהו אשר תשים לפניהם שהן המשפטי' בחי' הארה והמשכה משם מ\"ה דח\"ע שתשים ותמשיך לבחי' פני אדם שבמדות שלהם להיות בהם ביטול במציאות בעצם כנ\"ל (גם בנה\"ב שמפני שור כו' וד\"ל).\n<b>כי</b> תקנה עבד עברי<sup data-n=\"2092\">301</sup> שש שנים יעבוד כו', הנה פסוק זה קאי אדסמיך לי' ואלה המשפטים שהן בחי' המדות דחכ' דאדם עילאה שנמשך לפני אדם תתאה למעלה להנהגת המל' ולמטה בפני אדם דכנ\"י הן ההלכות ש[ב]משנה במתנית[י]ן מל[כת'] כו'. <span data-k=\"pg\">תכה</span> ּ וזהו כי תקנה עבד עברי שהן כנ\"י למטה [כמ\"ש כי לי בנ\"י עבדים<sup data-n=\"2093\">302</sup> ], ולמעלה הוא בחי' נער שהוא בחי' נער מט\"ט<sup data-n=\"2094\">303</sup> דבריאה<sup data-n=\"2095\">304</sup> ונק' עבד'<sup data-n=\"2096\">305</sup> דשכינתא כמ\"ש הנה ילך מלאכי לפניך<sup data-n=\"2097\">306</sup> השמר בו [כו'] כי שמי בקרבו<sup data-n=\"2098\">307</sup> (שהוא ו\"ק דאצי' שמלובש בקטנות דכלים דו\"ק דבריאה כו'), והוא בחי' נער כרביא<sup data-n=\"2099\">308</sup> אנפי זוטרי למטה מבחי' פני אדם דמל' דבריאה כו' והוא שנק' שרו ש\"ע בכלל כמש[אר]ז\"ל נער הייתי גם זקנתי<sup data-n=\"2100\">309</sup>",[["2086","295","<b>בחי'</b>: בד: ליתא."],["2087","296","<b>ונחנו מה כו' </b>[ב: ליתא. יא: מה]<b> בעצם [ד</b>: בעצם כו']: בשלח טז, ז. ח. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["2088","297","<b>דחכ'</b>: ד: דח\"ע."],["2089","298","<b>דמשה מה שמו</b>: ראה לעיל מג, ד. וש\"נ."],["2090","299","<b>ופילגשו ושמה ראומ\"ה</b>: וירא כב, כד. ראה מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. שעה\"י קמא, א. ובהערה 16."],["2091","300","<b>אלפי [שנא\"ן] שאינן</b>: תהלים סח, יח. ע\"ז ג, ב."],["2092","301","<b>כי תקנה עבד עברי</b>: משפטים כא, ב."],["2093","302","<b>כמ\"ש כי לי בנ\"י עבדים</b>: בהר כה, נה. ניתוסף ע\"פ דיא. בז: ליתא."],["2094","303","<b>נער מט\"ט</b>: נסמן בסמוך הערה 309."],["2095","304","<b>מט\"ט דבריאה</b>: ראה גם לעיל פ' בא קכב, ג. וש\"נ."],["2096","305","<b>מט\"ט. . עבד'</b>: ראה זהר ריש פרשתינו צד, א. ב. קטו, א."],["2097","306","<b>הנה ילך מלאכי </b>[ד: מלאכי ילך]<b> לפניך</b>: משפטים כג, כ [ושם: הנה אנכי שולח מלאך לפניך]."],["2098","307","<b>השמר בו [כו'] כי שמי בקרבו</b>: משפטים שם, כא [ושם: השמר. . בו]."],["2099","308","<b>נער כרביא</b>: ראה תרגום אונקלוס וירא כא, יז-כ."],["2100","309","<b>נער הייתי גם זקנתי</b>: תהלים לז, כה. ראה יבמות טז, ב ובתוס' שם. לעיל פ' בשלח רא, ד. וש\"נ."]]],[2300550554,"שרו של עולם אמרו. ואע\"פ שנק' נער לגבי פני אדם דמל', נק' שרו ש\"ע ומקור למרכבה דשרפים וחיות הקדש וכפני ארי' כו' דהיינו כל המלאכים דבי\"ע שכולם מקבלים ממנו בחי' המוחין חדשים לבקרים ומכחו הם או' שירה בכל יום להיות כולל כולם<sup data-n=\"2101\">310</sup> (והוא בחי' כלים די\"ס דבריאה שהוא בבחי' אלקות ממש רק שהוא בבחי' הקטנות כנער ורבי' כמ\"ש כי שמי בקרבו כו') (וז\"ש שבלילה הקב\"ה רוכב על כרוב קל שלו<sup data-n=\"2102\">311</sup> שהוא בחי' נער מט\"ט<sup data-n=\"2103\">312</sup> השר הגדול הכולל כל השרים ומלאכים עליונים ונק' עבדו זקן ביתו המושל<sup data-n=\"2104\">313</sup> כו'), וכל הו' אלפי שנין<sup data-n=\"2105\">314</sup> שמסתעפים בזמן ומקום נמשך משרו של עולם זה שנק' עבד עברי<sup data-n=\"2106\">316</sup> וע\"כ א' גם זקנתי כי הי' רק בחי' ו' ימים באצי'<sup data-n=\"2107\">315</sup>, וכמו צמצום קטנות המדות שבלב שמתצמצם באותיות המח' (וכמ\"ש בזהר שעז\"א תשב אנוש עד דכא<sup data-n=\"2108\">317</sup> כו' וכתיב אנוש כחציר<sup data-n=\"2109\">318</sup> כו'). והנה להיות שישראל עלו במח' הקדומה בבחי' סתים בסדכ\"ס ובס\"ר אותיות התורה הקדומה דג' קשרים הם בבחי' סתים, ע\"כ גם בגילוי בו\"ק דמל' דבריאה שנק' נער ועבד עברי שהוא שכולל כל נש\"י המסתעפים בו' אלפי שנין ע\"י התקשרות בחכ' שבתורה, שהוא שא[מר] שש שנים יעבוד שהן ו\"א שנה<sup data-n=\"2110\">*319</sup> כי אלף שנים למטה כיום<sup data-n=\"2111\">319</sup> א' באצי' ושנה א' בעולם הבריאה. וזהו ו' שנים יעבוד לשכינה לייחד יחו\"ע דאצי' ע\"י ההלכות שבש\"ס משנה<sup data-n=\"2112\">*320</sup> שהן ו' מדות דמל'<sup data-n=\"2113\">320</sup> דאצי' [ש]מבררים כל הבירורים דק\"נ בבירור והבדלה בין טמא לטהור כשר ופסול [כו'], וכנ\"ל בענין הלכה שזהו הליכות עולם לו גם להיות מקור להנהגת העולמות הכל כפי משפט התורה שהן ההלכות שבמשנה שביצי'<sup data-n=\"2114\">321</sup> (וכענין יושב ודן [את] כו') (וע\"כ ריב\"ז שהי' שר התורה [שהיא המשנה] אמר אני כשר לפני המלך<sup data-n=\"2115\">322</sup> שנק' שרי המלוכה ויש שר שכולל כולם שע\"י יתנהג כל דבר מל' כו' כך בחי' נער מט\"ט שרו ש\"ע שמקבל משר התורה וע\"כ נק' שר הפנים<sup data-n=\"2116\">323</sup> כו'). וענין יעבוד עבודה זו לאדון העולם שהוא בחי' המל' בכלל בכל וא\"ש לברר בירורים כמו העובד את האדמה לתקן ולהצליח לעשות צמיחה רבה בכפלי כפליים, כך הוא עיקר",[["2101","310","<b>להיות כולל כולם</b>: ראה גם זהר (רע\"מ) תצא רפב, סע\"ב ואילך. פרדס (שער אבי\"ע) שט\"ז, פ\"א (בעולם היצירה). לקמן פ' תרומה שטו, ג."],["2102","311","<b>שבלילה. . כרוב קל שלו</b>: ע\"ז ג, ב."],["2103","312","<b>כרוב. . מט\"ט</b>: ראה ת\"ז ת\"נ (פו, ב). לקמן פ' תרומה שטו, א. ש\"א ס, ב ובהערה 32."],["2104","313","<b>מט\"ט. . עבדו זקן ביתו המושל</b>: ח\"ש כד, ב. ראה זהר (מדרש הנעלם) ח\"ש קכו, ב. (רע\"מ) פינחס רטו, א."],["2105","314","<b>הו' אלפי שנין</b>: נסמן לעיל רפה, ב."],["2106","316","<b>שנק' עבד עברי</b>: ראה מגלה עמוקות אופן רנ (צ, א). מאורי אור מערכת עבד ס\"ב. זהר פרשתינו צד, א."],["2107","315","<b>הו' אלפי שנין. . ו' ימים באצי'</b>: ראה מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["2108","317","<b>תשב אנוש עד דכא</b>: תהלים צ, ג."],["2109","318","<b>אנוש כחציר</b>: תהלים קג, טו. ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381209\" data-slug=\"likkutei-torah\" data-id=\"4001381209\">לקו\"ת שה\"ש כ, א</a> צויין (לזהר) פ' פינחס דרי\"ז (סע\"א ואילך). ראה גם ביאוה\"ז בלק קמח, ג."],["2110","*319","<b>שש שנים יעבוד שהן ו\"א שנה</b>: נסמן לעיל רעח, ד."],["2111","319","<b>כי אלף שנים. . כיום</b>: ראה תהלים צ, ד. לעיל הערה 315."],["2112","*320","<b>ו' שנים. . שבש\"ס משנה</b>: ראה זהר (רע\"מ) משפטים קטו, א. מאמרי אדה\"ז תקס\"ב כאן ע' קנז. לקמן פ' ויקהל תיח, ג."],["2113","320","<b>שבש\"ס משנה שהן ו' מדות </b>[ה: ניתוסף דחכ']<b> דמל'</b>: ראה פע\"ח שער הנהגת הלימוד (שנט, א), טעה\"מ להאריז\"ל ואתחנן ד\"ה בענין מקרא משנה תלמוד. לעיל פ' שמות יא, ג. טז, ד."],["2114","321","<b>שבמשנה שביצי'</b>: ראה פע\"ח שם. לעיל פ' שמות יב, א. וש\"נ."],["2115","322","<b>ריב\"ז. . אני כשר לפני המלך</b>: ראה ברכות לד, סע\"ב. לעיל פ' שמות יא, ב. וש\"נ."],["2116","323","<b>מט\"ט. . שר הפנים</b>: ראה זהר (מדהנ\"ע) ח\"ש קכו, א. (רע\"מ) פינחס ריט, א. פרדס (שער אבי\"ע) שט\"ז, ספ\"ו. מגלה עמוקות פ' שמות ג, ע\"א וע\"ג."]]],[2300550567,"המשכות דמוחין מחכ' התורה לשרו ש\"ע זהו מט\"ט שנק' עבד עברי שהן כנ\"י למטה כו' אינו אלא בשביל הצמיחה בתוס' שהוא מה שנתהפך חשך לאור מק\"נ ע\"י מצות מעשיות בתוס' ברכה והמשכה בשם הוי' דאצי' מטעם יתרון האור מן החשך דוקא, וכדרך עבודת עבד הנאמן בבית ובשדה שנמצא ברכה יתירה במעשה ידי[ו] וכמו שהי' ברכה במעשה עבד עברי דיוסף<sup data-n=\"2117\">324</sup> צ\"ע כו' (שהוא ג\"כ בהעלם בנער מט\"ט<sup data-n=\"2118\">325</sup> בזמן הגלות כמו ונתתי נערים שריהם<sup data-n=\"2119\">326</sup> ). ובזה הוא עיקר הבירור <span data-k=\"pg\">852</span> ּ הזה ז\"ש שש שנים יעבוד כו' בש\"ס משנה דוקא שהן ההלכות שנק' משפטים כנ\"ל וכידוע דבחכ' אתברירו<sup data-n=\"2120\">327</sup> בחכ' דתושבע\"פ דוקא והוא במתניתין מל[כת'] שנמשך לשרו ש\"ע שהוא עבד עברי זה מטעם הנ\"ל.\n<b>ובשביעית</b> יצא לחפשי חנם<sup data-n=\"2121\">328</sup>, פי' ובשביעית באלף השביעי שהוא העוה\"ב שהוא שנה הז' בכלל שנק' שמיטה לשנים דוא\"ו אלפי שנין דהוי עלמא שאז הוא למעלה מן העבודה דבירורים דעה\"ד טו\"ר וכמ\"ש לע\"ל בחריש ובקציר תשבות<sup data-n=\"2122\">329</sup>, שזהו בשנה הז' דכתיב ושבתה הארץ שבת לה'<sup data-n=\"2123\">330</sup> כו' להיות[ו] בבחי' אור העצמות דא\"ס ב\"ה שלמעלה מכל ההשתלשלו' דקו\"ח כו', ולא יתכן אז ענין עליות וירידות כלל ונק' מנוחה לחיי העולמים כו' וע\"כ נק' יום שכולו שבת<sup data-n=\"2124\">331</sup> שכולו ארוך<sup data-n=\"2125\">332</sup> בחיי עולם הנצחי' ולזאת ע\"ע [זה] יצא אז לחפשי חנם בלא מצות<sup data-n=\"2126\">333</sup> כמ\"ד מצות בטילות לע\"ל<sup data-n=\"2127\">334</sup> כי א\"צ עבודה ובירור כלל, ואז הוא שכר המצות ולאחר שלימות הבירורים דחכ' דתורה שבע\"פ דוקא וכמארז\"ל כל השונה הלכות דוקא בכל יום<sup data-n=\"2128\">335</sup> מובטח לו שהוא בן עוה\"ב שנק' עולם ברור<sup data-n=\"2129\">336</sup>, לפי שע\"י ההלכות הוא שלימות הבירורים מלמעלה למטה ומלמטלמ\"ע כו' והוא מ\"ש למחכה לו דוקא למאן דדייק כו' ומטעם הנ\"ל וד\"ל.",[["2117","324","<b>ברכה במעשה. . דיוסף</b>: וישב לט, ב. ואילך."],["2118","325","<b>דיוסף. . מט\"ט</b>: ראה גם ת\"ז ת\"ע (קלז, סע\"ב ואילך) ובניצוצי זהר שם."],["2119","326","<b>ונתתי נערים שריהם</b>: ישעי' ג, ד."],["2120","327","<b>דבחכ' אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה־ שמות ח\"ב ע' שכא."],["2121","328","<b>ובשביעית יצא לחפשי חנם</b>: משפטים כא, ב."],["2122","329","<b>בחריש ובקציר תשבות</b>: תשא לד, כא. ראה גם לעיל פ' בשלח קנט, ג. וש\"נ."],["2123","330","<b>ושבתה הארץ שבת לה'</b>: בהר כה, ב. ראה גם לעיל פ' בשלח רלה, א. רטו, ד."],["2124","331","<b>מנוחה לחיי העולמים. . יום שכולו שבת</b>: סוף תמיד."],["2125","332","<b>יום. . שכולו ארוך</b>: ראה קדושין לט, ב. הנסמן לעיל פ' בשלח רט, ג."],["2126","333","<b>חנם בלא מצות</b>: ראה גם לעיל פ' שמות א, ב. וש\"נ."],["2127","334","<b>כמ\"ד מצות בטילות לע\"ל</b>: ראה נדה סא, ב. אגה\"ק סכ\"ו (קמה, סע\"א). מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. נ\"ך ע' א. וש\"נ."],["2128","335","<b>כל השונה הלכות. . בכל יום</b>: נדה בסופה. ראה אגה\"ק סכ\"ט. מאמרי אדה\"א דברים ח\"ד ע' א'תסה. וש\"נ. נ\"ך ע' תא."],["2129","336","<b>עוה\"ב שנק' עולם ברור</b>: ראה גם לעיל פ' שמות ט, א. וש\"נ."]]],[2300550052,"<b>ב\"ה שבת שמברכין ר\"ח אדר ראשון שנת תקעחי\"ת לפ\"ק </b>\nפה ליובאוויטש\n<span data-k=\"pg\">144</span> ּ<b>וכי</b> ימכור<sup data-n=\"2130\">81</sup> איש את בתו<sup data-n=\"2131\">2</sup> לאמה לא תצא כצאת העבדים, הנה יש ג' מדרגות בנפש האלקי', עבד כנעני, ועבד עברי ואמה העבריה. עבד כנעני הוא כמו עבד הגשמי אשר יעבוד לאדונו כל המלאכות שלא ברצון וחשק<sup data-n=\"2132\">3</sup> אדרבה יהי'<sup data-n=\"2133\">4</sup> המלאכה והעבודה עליו יסורים גדולים מאד נגד רצונו, אבל יעשה ויעבוד בע\"כ רק מצד אימת האדון<sup data-n=\"2134\">5</sup> שלא יכהו בשבט כו' אבל עיקר רצונו ונח\"ר שלו הוא בהפקירא שיהי' בטל מכל עול וילך אחר שרירות לבו כו'. כמו\"כ חלק אלוה השורה בנפש [החיוני'] כשאין ההשראה בהתגלות כל פרטיות הכחות שבניצוץ אלקות<sup data-n=\"2135\">6</sup> בפרטיות כחות נפש הבהמיות, רק בחי' חכמה שבנפש האלקי' או בחי' יחידה שבה ישרה על נפשו הבהמי' בבחי' מקיף לבד שיפול פתאום בלבו<sup data-n=\"2136\">7</sup> הרהור תשובה והתעוררות הלב לעבודה מבלי שהכין איזה עבודה לזה, הוא הארת המקיף שהוא כמו אימת הכאת השבט של האדון כמ\"ש וכי יכה איש את עבדו בשבט<sup data-n=\"2137\">8</sup> כו' הוא ענין הכפיי' לכוף את הנפש בע\"כ בשעת התפלה כו'. אבל שרשה העצמית כל היום בהפקירא ופריקת עול מ\"ש ניחא לי' שהוא בחי' התענוג שלה ועיקר מהותה<sup data-n=\"2138\">9</sup> כו' אלא ששבט והארת המקיף יכריחנה<sup data-n=\"2139\">10</sup> לסור מרע ולעשות טוב כו'. וזהו ענין רשעים מלאים חרטות<sup data-n=\"2140\">11</sup> מהארת השבט כו', דאכל בי עשרה שכינתא שריא<sup data-n=\"2141\">12</sup> כידוע.\nועבד עברי הוא העבודה שיעבוד ברצון וחשק וזהו עיקר התענוג שלו וההפקירא והפריקת עול<sup data-n=\"2142\">13</sup> להמשך אחר עצמו כו' לא ניחא לי' אדרבה הם לו יסורים וצער, אע\"פ שכשבאי' לו עניני עוה\"ז הוא מתענג מהם אבל אין רצונו",[["2130","81","<b>וכי ימכור</b>: דרוש זה הוא הנחת כ\"ק אדמו\"ר האמצעי מדרוש שנאמר ע\"י אביו כ\"ק אדמו\"ר הזקן ונאמר על ידו עוה\"פ בשנת תקע\"ח ונדפס בארוכה בספרו דרך חיים [שנדפס בשנת תקע\"ט] עב, ד ואילך. והנחה זו בשינויים גדולים ועם הגהות וכו' מהצ\"צ נדפסה בס' אוה\"ת פ' משפטים ע' א'קכז ואילך [ובע' א'קלט ואילך נמצא ביאור על הדרוש]. וראה גם דרך מצותיך פג, ד ואילך. מאמר ד\"ה ואלה המשפטים תשי\"ד. תשל\"ח [נדפס בסה\"מ מלוקט ח\"א ע' שח ואילך]. תשמ\"א (נדפס בסה\"מ מלוקט ח\"ו ע' קט ואילך]. שיחת ש\"פ משפטים תשי\"ד. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י."],["2131","2","<b>וכי ימכור איש את בתו</b>: משפטים כא, ז."],["2132","3","<b>וחשק</b>: יא: אלא."],["2133","4","<b>יהי'</b>: ז: ליתא. יא: כבפנים."],["2134","5","<b>האדון</b>: יא: רבו."],["2135","6","<b>שבניצוץ אלקות</b>: ז: שבנפש האלקית. יא: הנה\"א."],["2136","7","<b>בלבו</b>: יא: ליתא."],["2137","8","<b>וכי יכה איש את עבדו בשבט</b>: משפטים כא, כ [בדילוג]. ראה גם דרך חיים כאן עג, סע\"א ואילך. מאמרי אדה\"א שמות ח\"א ע' יד. וש\"נ. לקמן פ' ויקהל תכג, ג."],["2138","9","<b>מהותה</b>: יא: חיותה."],["2139","10","<b>יכריחנה</b>: זיא: מכריחה."],["2140","11","<b>רשעים מלאים חרטות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310016\" data-slug=\"tanya\" data-id=\"3401310016\">תניא</a> ספי\"א. ידי משה לר' משה אלמושנינו (ויניציא שנ\"ז) איכה ג, יז (קז, ב). ג, לו (קיב, א) בשם רז\"ל. ג, מב (קיד, א). ג, סד (קיט, א). קהלת פכ\"ז (רלז, א). תפלה למשה — להנ\"ל — מאמר א' ח\"ד (סאלוניקי שכ\"ג כח, א). מאמרי אדה\"א דברים ח\"ב ס\"ע שסה. וש\"נ. ד\"ח כאן עג, ג."],["2141","12","<b>דאכל בי עשרה שכינתא שריא</b>: ראה סנהדרין לט, א. מאמרי אדה\"א שמות ח\"א ע' יד. וש\"נ. ד\"ח כאן עג, ג. מ\"מ הגהות והערות קצרות לסש\"ב ספי\"א."],["2142","13","<b>עול</b>: יא: עול מ\"ש."]]],[2300550084,"להמשך אחריהם לכתחלה, אך<sup data-n=\"2143\">14</sup> כשבאים אליו פתאום ונתפעל מהם מיד הוא במרירות על ההתפעלות כו'. נמצא שאין עניני עוה\"ז עיקר רצונו להמשיך כל עצמותו אליהם, והיינו מפני ששורה בנפשו הבהמית הארת ניצוץ אלקות בבחי' או\"פ שכל בשכל ומדות במדות דהיינו שכל כחות נפשו הבהמית הם לה' בשעת התפלה ע\"י הארת כחות<sup data-n=\"2144\">15</sup> נפשו האלקי' בהם בהתגלות גמור, דהיינו שיש לו בחי' ראי' בהעמקת שכלו הנולד מאין ליש כו', ויש לו תשוקה במדות שבלב ברשפי אש<sup data-n=\"2145\">16</sup> אוי\"ר כו'. אבל לאחר התפלה שנסתלקו הארות ניצוצו' אלקו', מיד כחות נפשו הבהמי' נמשכין אחר עניני עוה\"ז, אבל מ\"מ נתגברו הארות<sup data-n=\"2146\">17</sup> אלקו' בשעת התפלה עד שיהי' לו עיקר הרצון (דהיינו בחי' יחידה) שלו<sup data-n=\"2147\">18</sup> שיעבוד ה' במוחו ולבו [תמיד], וזהו התענוג שלו התמידי<sup data-n=\"2148\">19</sup> ועניני עוה\"ז יהיו מאוסי' בעיניו להמשך אחריהם <span data-k=\"pg\">עב</span> ּ אף שלא נהפכו מרע לטוב כלל עדיין, והוא בכל טבעיות שלו כמו שהוטבעה נפשו הבהמית אם שפלות או התנשאות או חמימות או קרירות כו'<sup data-n=\"2149\">20</sup> ולא נשתנה שום טבעיות שלו עדיין מחמת הארת נפש אלקי' בתפלה, אלא שהם כפופים לפעול פעולה אלקית מה שאין זה מהותם, ולא בע\"כ הם פועלים אלא ברצון וחשק דהיינו מדות הגשמיי' שבבשר הלב מתפעלים לאלקים חיים ברשפי אש התשוקה כמו שהם חושקים לעניני עוה\"ז, אבל לא נהפך חשוקת העוה\"ז שלא יהי' בלב שום תשוקה כלל לעניני עוה\"ז רק לה' לבדו כו'. נמצא שהם כפועלי' ועושים עבודה ברצון וחשק אבל אין זה עצמיות שלהם כו'. וה\"ז כמשל העבד המביא כל הצטרכות בני<sup data-n=\"2150\">21</sup> הבית אכילה ושתי' מן השוק דהיינו בשר ותבואה שהיו בשוק ובמקום רחוק מן בני היכל המלך ואין דרכם להתבזות בשוק ולקנות בשר כו', אלא זהו עבודת עבד שבבית לילך בשוק ולהביא מן השוק לבית כל הדברים המצטרכי' לחיות בני היכל המלך. אבל הדברים שהוא מביא עדיין הם מגושמים מאד ואינם ראוים לאכילה כלל וכלל כמו דגן התבואה וגשם הבשר<sup data-n=\"2151\">22</sup> החי שאינם ראויים להיות חיות מאכל לבני ההיכל עד שיבשלום באש ויהפכו ממהות גשמיותם למהות רוחני דק שיהי' בו טעם מאכל והוא ע\"י אפיי' ובישול כו' וד\"ל.\n<b>ועפ\"ז</b> יובן בענין הבאת קליפת נוגה הוא כחות נפשו הבהמי' להיות פועלים פעול[ת נפש ה]אלקי' בתפלה הוא כמשל הבאת העבד התבואה והבשר<sup data-n=\"2152\">23</sup> ממקום רחוק, כמו\"כ הרוח הגסו'",[["2143","14","<b>אך</b>: זיא: ואף."],["2144","15","<b>כחות</b>: ז: כח. יא: ליתא."],["2145","16","<b>במדות. . אש</b>: זיא: ברשפי אש במדות שבלב."],["2146","17","<b>הארות</b>: יא: הארת ניצוץ."],["2147","18","<b>(דהיינו. . שלו</b>: זיא: ליתא."],["2148","19","<b>התמידי</b>: זיא: ליתא."],["2149","20","<b>כו'</b>: שם: פי'."],["2150","21","<b>בני</b>: שם: ליתא."],["2151","22","<b>וגשם הבשר</b>: שם: וגם בשר."],["2152","23","<b>התבואה והבשר</b>: שם: הבשר והתבואה."]]],[2300550116,"דנוגה רחוקה מאד בהשתלשלו' מאלקי' חיים כידוע, וכשאדם מביא רוח זה שיפעול פעולה אלקות דהיינו אהבה לאלקות ועדיין לא נהפך כלל מהותו דהיינו אהבה הגשמיות דנוגה כמש\"ל, וה\"ז כמשל הבשר החי והדגן שאינו ראוי לאכילה עדיין, דהיינו שאינו כמו הבשר שנהפך<sup data-n=\"2153\">24</sup> לחיות הנפש הרוחניות מפני הטעם והמתיקות שבו שהוא רוחני דק וראוי לערבו לחיות הנפש כו' מפני שבבישול נפל כל [ה]גשמיות ממנו ונגלה בו הרוחניות הדק שבו עד שכמעט נשתנה מהותו הראשון לגמרי למהות רוחני דק שהוא הטעם<sup data-n=\"2154\">*25</sup> והמתיקות שבו מה שלא הי' בו טעם זה בעודו בגשמיותו קודם שנתבשל וכמו שנתבאר במ\"א. כמו\"כ עבודת עבד עברי הוא המשכת רוח דנוגה ג\"כ לה' ב[שעת ה]תפלה אבל הם מגושמי' ואין בהם טעם כלל<sup data-n=\"2155\">25</sup> שיהי' ראוי לבחי' מאכל, מאחר שהרוח דנוגה היא<sup data-n=\"2156\">26</sup> בתקפה ובגשמיותה בעניני עוה\"ז ולא נשתנה מן טבעיות שהוטבע בהתנשאות או בחמימות כלל, רק הניצוץ אהבה אלקי' מלובש באהבה דרוח הגסה דנוגה כמו שהטבע אופן האהבה דנוגה, לכן נק' מדות דנפש אלקי' המלובשים במדות דנוגה בשם עבדים אלא שהם עבדים להיותם פועלי[ם] אלקי' אבל הוא רק לפי מזג טבעיות הנוגה<sup data-n=\"2157\">27</sup> שהיא בתקפה וגסותה כו'. וכמו\"כ עבודת עבד העברי להביא מן השדה ומן החוץ כל היום בעסקו בתורה ובמצות שהרי דבר הלכה מלובש בעניני נוגה זה טוען כך כו' והוא מדבר בכח הדיבור שבנפש דנוגה, ובהבל דבורו בההלכה זכאי [או] חייב פטור<sup data-n=\"2158\">28</sup> הוא קורא וממשיך הארת מדותיו ית' שהוא ו\"ק דיצי' כידוע בענין יושב ודן<sup data-n=\"2159\">29</sup> כל העולם כולו<sup data-n=\"2160\">30</sup> שהמשנה ביצי'<sup data-n=\"2161\">31</sup>, פי' הקב\"ה יושב וקורא ושונה כנגדו<sup data-n=\"2162\">32</sup> סיבת התהוות אור החסד דיצי' [כו'] והוא ענין הקורא בתורה. אך איך ביכולת <span data-k=\"pg\">146</span> ּ דבריו להמשיך אא\"ס ב\"ה שבמדותיו כו' הוא ע\"י העלאת נוגה שיהי' לו בתפלה רעותא דלבא<sup data-n=\"2163\">34</sup> בתשוקה שבלב הגשמי בגסות דנוגה, ואף שלא נהפכו ממהותם רק הי'<sup data-n=\"2164\">35</sup> בדרך עבודה כנ\"ל, עכ\"ז העלאת מ\"ן הוא וכמ\"ש אם ישים אליו לבו<sup data-n=\"2165\">36</sup> בתפלה אז רוחו ונשמתו אליו יאסוף<sup data-n=\"2166\">37</sup>, פי' בחי' הרוח והנשמה של הנפש הוא ו\"ק דיצי' כידוע אליו יאסוף פי' נמשך ומתגלה<sup data-n=\"2167\">38</sup> בנפש בעסקה במשנה זכאי חייב<sup data-n=\"2168\">39</sup> שאז הקב\"ה יושב ושונה כנגדו. וענין האסיפה וההמשכה הוא ג\"כ ע\"י תשוקת הנפש בהתגלות אלקות שיהי' לו דירה בתחתונים יש לנפש דנוגה ג\"כ תשוקה זו שיהי' המשכת אלקות למטה, אבל [היא] בדרך עבודה ולא שיהי' כל תשוקתו רק זאת ולא שום תשוקה אחרת שהוא הפיכת",[["2153","24","<b>שאינו כמו הבשר שנהפך</b>: שם: כמו הבשר שאינו נהפך."],["2154","*25","<b>שבבישול. . ונגלה. . הטעם</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקסז (נו\"ש). כתובים ח\"א ע' צד."],["2155","25","<b>כלל</b>: שם: ליתא."],["2156","26","<b>היא</b>: שם: ליתא."],["2157","27","<b>הנוגה</b>: יא: המדה דנוגה."],["2158","28","<b>פטור</b>: זיא: ליתא."],["2159","29","<b>יושב ודן</b>: ראה ע\"ז ג, ב."],["2160","30","<b>כל העולם כולו</b>: שם: את העולם."],["2161","31","<b>שהמשנה ביצי'</b>: ראה פע\"ח שער הנהגת הלימוד. לעיל פ' שמות יב, א. וש\"נ."],["2162","32","<b>הקב\"ה יושב. . כנגדו</b>: נסמן לעיל פ' יתרו רסא, א. 33) יושב וקורא: ז: יושב. יא: קורא."],["2163","34","<b>רעותא דלבא</b>: זהר וירא ק, א."],["2164","35","<b>הי'</b>: זיא: המה עובדים."],["2165","36","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["2166","37","<b>אליו יאסוף</b>: זיא: ליתא."],["2167","38","<b>ומתגלה</b>: שם: ונתגלה."],["2168","39","<b>זכאי חייב</b>: שם: חייב (או) זכאי."]]],[2300550148,"המהות גסות דנוגה כנ\"ל כו'. ולפי שאין בקריאת הבל דבורי נוגה הפיכת המהות רק שעדיין בתקפה וגסותה, לכן גם הדבר<sup data-n=\"2169\">40</sup> הלכה שמדבר אינו עולה לה' בבחי' ההפשט מגשמיות נוגה להכלל במדותיו ית' שבעולם היצי' כחיות המאכל שנתבשל ויש בו טעם כו', אלא כמשל הבשר החי שהובא מן השוק שאין [לו] יתרון אלא במה שהי' רחוק והובא בתוך הבית אבל אינו ראוי לכלום<sup data-n=\"2170\">41</sup> עדיין כו'. ונמצא כל עבודת עסקו בתורה כל היום הוא רק הכנה למאכל דהיינו כשיבושל ויהי' בו טעם והיינו כעבודת<sup data-n=\"2171\">42</sup> אמה העברי' שיהפך<sup data-n=\"2172\">43</sup> מהותו לגמרי ע\"י בישול<sup data-n=\"2173\">44</sup> כמשי\"ת. ובדרך פרט הרי בכל נפש יש בחי'<sup data-n=\"2174\">45</sup> נרנח\"י<sup data-n=\"2175\">46</sup>, וב' מיני עבדים הם בחי' נפש ורוח ובחי' אמה הוא<sup data-n=\"2176\">47</sup> בחי' נשמה ומוחין כמשי\"ת, והוא בכל ניצוץ אלקות בתפלה להפך המהות<sup data-n=\"2177\">48</sup> כמשי\"ת והוא בחי' גדלות המוחין ועסק התורה ביום<sup data-n=\"2178\">49</sup> הוא מחמת רשימו דקטנות לא בתשוקה נפלאה ברשפי אש כ\"א בדרך עקשות שום תשים עליך מלך<sup data-n=\"2179\">50</sup> כו' לכן הוא כמשל הבאת העבד לבד כו', והי' כל מעשה המצות בעשי' גשמיי' ובדבור כל המצות המפורשי' בו' סדרי משנה כשמדברים [כל] היום שעבר הוא כמו משל הדברי' שהעבד עברי מביא מן השוק והם מגושמי' עדיין כו', וע\"י הגדלות שלמחר<sup data-n=\"2180\">51</sup> בתפלה ע\"י בחי' האמה העברי' יהפכו לטעם מאכל ישראל מפרנסין<sup data-n=\"2181\">52</sup> כו' וד\"ל.\n<b>והנה</b> אף מי שיש לו בחי' נשמה הוא בחי' בינה לבא<sup data-n=\"2182\">53</sup> הלב מבין<sup data-n=\"2183\">54</sup>, הוא עבודת<sup data-n=\"2184\">55</sup> האמה שאינה בבחי' שפלות כ\"כ לצאת החוצה ולהביא הביתה אלא עבודתה בבחי' פנימי' דהיינו מה שכבר הובא לבית ה[י]א מתקנם ע\"י בישול וטחינה ואפיי' כו' להפכם למהות אחר רוחני דק שיהי' בהם טעם המשיב את הנפש האוכל [את ה]מאכלים כו', והוא ענין רבקה שעשתה מטעמי' ליצחק<sup data-n=\"2185\">56</sup>, דהיינו בחי' ראיי' השגה באלקות המהווה כו' כשהוא נתפס בעמק[ות] הלב שנקודת הלב מבין ומשיג בענין אחדות ה' אז התפעלות התשוקה להמשיך ולהדבק אחרי ה' הוא עדיין בראשית המשכתה מפנימי' בינה שבלב כו'. ולכן יוכל להיות בה שינוי הטבע מכמו שהוטבעה התשוקה בגסות הנוגה דהיינו שיהי' התשוקה אלקי' זו בהיפך ממזיגת הטבע דנוגה, מפני שהיא עדיין בבחי' חירות מההשראה בנוגה כו' להיותה עדיין בבחי' ראשית המשכתה מבינה שהלב מבין בבחי' ראי' באלקות וד\"ל. וזהו ענין עבודת האמה העברי' להפך המהות של מזיגת הטבע דנוגה מהיפך להיפך אם הוא בעצם בעל התנשאות לא",[["2169","40","<b>הדבר</b>: ז: דברי ה'."],["2170","41","<b>לכלום</b>: זיא: לאכילה."],["2171","42","<b>כעבודת</b>: שם: בעבודת."],["2172","43","<b>שיהפך</b>: שם שמהפך."],["2173","44","<b>ע\"י בישול</b>: שם: ליתא."],["2174","45","<b>בכל נפש יש בחי' נרנח\"י</b>: ראה גם לעיל פ' בשלח קפ, ד. וש\"נ."],["2175","46","<b>נרנח\"י</b>: ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["2176","47","<b>הוא</b>: יא: העברי' היא."],["2177","48","<b>המהות</b>: ז: המדות."],["2178","49","<b>ביום</b>: ז: ניתוסף: ההוא."],["2179","50","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["2180","51","<b>שלמחר</b>: זיא: של (ה)מוחין."],["2181","52","<b>ישראל מפרנסין</b>: זהר ויקרא ז, ב. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' קמז. דברים ח\"ד ע' א'רכד. וש\"נ. קונטרסים ע' תקפג [ושם: בגמרא]."],["2182","53","<b>בינה לבא</b>: ת\"ז בהקדמה (יז, א)."],["2183","54","<b>הלב מבין</b>: ברכות סא, א."],["2184","55","<b>עבודת</b>: זיא: מדריגת."],["2185","56","<b>רבקה שעשתה מטעמי' ליצחק</b>: תולדות כז, יד."]]],[2300550180,"יהי' בתפל[תו] שום התנשאו' <span data-k=\"pg\">עג</span> ּ והגבהה, הלא דבר הוא כו' וכידוע, אדרבה יהי' שפל מאד כאלו לא עשה כלום ולא מחזיק טיבותא לנפשי' שהוא עושה דבר מה כו', וכיוצא בזה בחסדי' וגבורות והתפארות ישנה האופן שהוטבעה בהן כו' וד\"ל. משא\"כ בחי' עבד העברי שתשוקתו מובדלת מהבינה שממנה נתפעל להיות שהי' ההתבוננו' רק במוחו ששם הקרירות ולא נתפס בהשגה ברשפי אש נקודת הלב שיהי' הלב מבין כו', לזה נשארת התשוקה אלקי' באופן הטבעתה בגסות דנוגה ולא נהפך הנוגה כלל כנ\"ל וד\"ל. וזהו שרבקה הוא בינה<sup data-n=\"2186\">57</sup> השורה בעולם הבריאה<sup data-n=\"2187\">58</sup> עושה מטעמי' [מ]גסות דנוגה דיצי' שמהפכת המהות ונעשה הרצון בלב התשוקה רק תשוקה ורצון א' לה' ועמך לא חפצתי<sup data-n=\"2188\">59</sup> כלל כו', אך זהו בהפיכת תשוקת המדות שבבהמית ע\"י בינה ליבא. אבל גסות דבינה עצמה שהיא דקה ביותר לא נהפכת עי\"ז וצריכה פדיי', דהיינו הבחי' ראי' שבנוגה התופסת ליש ודבר כו' עדיין יהי' אף במי שיש לו בחי' נשמה בינה ליבא כו'. וזהו אם רעה קליפה דבריאה<sup data-n=\"2189\">61</sup> שמועטה<sup data-n=\"2190\">62</sup> רע בעיני אדוני'<sup data-n=\"2191\">60</sup> ז\"א דאצי' אשר לא יוכל לייעדה, שהיעוד קודם למצות פדי'<sup data-n=\"2192\">63</sup>, והיעוד הוא שהאמה העושה המטעמי' שהוא בחי' בינה ליבא תצא מגשמיות נוגה שמסתירה ולא תעסוק להביא אש של<sup data-n=\"2193\">64</sup> הדיוט גסות נוגה דיצי' להפכם כו', אלא יומשך עלי' אש של מעלה שלהבת יה<sup data-n=\"2194\">65</sup> שהשגת ה'<sup data-n=\"2195\">66</sup> הנתפס בעמקי הלב הוא יש ודבר, וכשיתגבר הרצון והתענוג שלמעלה מבינה שבנפש אז יהי' סתירה גמורה בההשגה שתהי' כלא הי' ונסתר אז גם כל פרצופה<sup data-n=\"2196\">67</sup> שעשתה מטעמי' בהמדות שהפכתם כו' ולא תקרא אז אמה כ\"א כלה שהוא בחי' כתר שבה. ושם אין אחיזה לנוגה דבינה ובטילה לגמרי שאין שום הטבעה לתפוס ולהכניס את היש כו', שזה הסימן לתגבורת הרצון בחי' יחידה כאשר יהי' ההתחדשות מאין ליש בהפלאה עצומה בכל רגע וכמ\"ש במ\"א והי' ביום ההוא<sup data-n=\"2197\">68</sup> תקראי לי אישי ואל אישך תשוקתך<sup data-n=\"2198\">69</sup> באש שלמעלה כהנא רבא<sup data-n=\"2199\">70</sup> חסד דאצי' הממשיך תשוקה לאשה וכלה זו כמ\"ש במ\"א, וזהו היעוד לאמה<sup data-n=\"2200\">71</sup> שייעדנה כ\"ג דלעילא שהוא אדוני'<sup data-n=\"2201\">72</sup> שלא תעשה לו עוד מטעמי' כאשר אהב יצחק שהוא גבורות<sup data-n=\"2202\">73</sup> דז\"א דאצי' וכו' אלא תהי' מיוחדת עמו ככלה וד\"ל.\n<b>ואם</b> רעה בעיני אדוני' שלא יוכל לייעדה ככלה מפני גסות נוגה שלה שמחמתה א\"א להתגלות בה בחי' הרצון הנק'",[["2186","57","<b>שרבקה הוא בינה</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות (מהדורת תשמ\"ט) ע' 13."],["2187","58","<b>בינה. . הבריאה</b>: נסמן לעיל פ' יתרו רעא, ד."],["2188","59","<b>ועמך לא חפצתי</b>: תהלים עג, כה."],["2189","61","<b>קליפה דבריאה שמיעוטה רע</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ו. מאמרי אדה\"א בראשית ע' צז. וש\"נ."],["2190","62","<b>שמועטה</b>: יא: שמיעוטה."],["2191","60","<b>אם רעה. . בעיני אדוני'</b>: משפטים כא, ח."],["2192","63","<b>שהיעוד קודם למצות פדי'</b>: בכורות יג, א. רמב\"ם הל' עבדים פ\"ד, ה\"ז."],["2193","64","<b>של</b>: זיא: ליתא."],["2194","65","<b>שלהבת יה</b>: שה\"ש ח, ו."],["2195","66","<b>שהשגת ה'</b>: זיא: שהשגתה."],["2196","67","<b>פרצופה</b>: שם: פרצופים."],["2197","68","<b>והי' ביום ההוא</b>: הושע ב, יח [בדילוג — ובהוספת תיבת ”לי\" — ראה מאמרי אדה\"ז הקצרים ע' ד. הנסמן במאמרי אדה\"א בראשית ע' תקב. דברים ח\"ב ע' תקכב. הנחות תקע\"ז ע' קנג. שע\"ת קלט, ב]. ראה גם סידור שער הק\"ש פ, סע\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370206\" data-slug=\"torah-or\" data-id=\"3901370206\">תו\"א ויחי מה, ב</a>."],["2198","69","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["2199","70","<b>כהנא רבא</b>: בז: שייעדנה כה\"ג דלעילא שהוא כה\"ר (וראה הערה 72). יא: שייעדנה באש של מעלה שהוא נר( )."],["2200","71","<b>לאמה</b>: יא: ניתוסף: העברי'."],["2201","72","<b>כ\"ג דלעילא שהוא אדוני'</b>: זיא: האדון (וראה הערה 70)."],["2202","73","<b>יצחק שהוא גבורות</b>: נסמן לעיל רעח, ב."]]],[2300550212,"כלה<sup data-n=\"2203\">74</sup> כידוע אז והפדה לפדות בשק\"ל כופר נפשה להוי', פי' שלהיות גסות נוגה דבריאה דקה מאד יועיל להנפש אלקי' הפדיון שתתן דבר אחר תחתי' אפי' דבר הנמוך שבה ואז נחשב כאילו היא עצמה עלתה מגשמיותה כו'. והוא ענין כל מה שהסוס רץ ומיצל<sup data-n=\"2204\">75</sup> יהי' קדש לה' והוא תא הרצים<sup data-n=\"2205\">76</sup> כמ\"ש במ\"א, והיינו אותיות הנפש אלקי' והתגלותה כל היום במחדו\"מ בתו' שיתעסק בקרירות והוא בחי' הקטנות שבה כידוע, כאשר יהיו האותיות שבה שמורי' מרע ועושי' טוב אז ביכולתם להוסיף תוס' קדושה למחר בתפלה בבחי' ראי' שבה עד שלא יחשיך לה נוגה שלה הרגשת היש וכו'. והיינו פדיית אמה מנוגה שלה ע\"י הפדיון שלה<sup data-n=\"2206\">77</sup> שנתנה אותיות שלה להוי', וזהו<sup data-n=\"2207\">78</sup> ע\"י שהסוס רץ בקרירות ביום שעבר יהי' קדש להוי' דהיינו <span data-k=\"pg\">148</span> ּ בחי' [ראי'] שבלב יהי' מופשט מנוגה שבה וכנ\"ל וד\"ל, וזהו ענין שהקטנות מועילי' לגדלות וד\"ל.\n<b>והנותן</b> פדיון האותיות שבה הוא אדוני' כמ\"ש והפדה<sup data-n=\"2208\">79</sup> אם לא יעדה, וענינו מובן למשכיל שהוא הארת בחי' המקיף שבנפש בעת הקטנות כל היום שלא יטנפו ברע ויעשו טוב, שההמשכה אשר מאליו וממילא כל היום הוא שמור במדו\"מ מרע<sup data-n=\"2209\">80</sup> ועושה טוב הוא רק מצד הארת המקיף שבפנימי' כח מ\"ה שבנפש שהיא אדון אל בינה ליבא, וזהו והפדה הוא גורם סיבת הנתינה שלה בפדיון דאותיות וד\"ל. וזהו לא תצא האמה מגשמיות נוגה שלה כצאת העבדים המה מדות דאלק[ות] מנוגה שלהם שאין יציאתם אלא ע\"י התעוררות בחי' ר\"ר עליהם ע\"י בכיי' ומואס בחייו, שבינה ליבא עושה מהם מטעמי' עי\"ז, כי המה בבכי יבואו ע\"י הארה<sup data-n=\"2210\">81</sup> כנ\"ל להפיכת המדות<sup data-n=\"2211\">82</sup> להיות כי הנוגה שלהם גסה מאד בתשוקת וחמדת עוה\"ז כו'<sup data-n=\"2212\">83</sup>. לכן אין פדיון האותיות מועיל לעבד העברי האסור וקשור בהם להוציאו מנרתקם כו' כ\"א ע\"י הבע\"ת<sup data-n=\"2213\">84</sup> האמיתי<sup data-n=\"2214\">85</sup>, אנן בעינן למהוי קדם מלכא<sup data-n=\"2215\">86</sup>, והוא בחי' אל דמי לך<sup data-n=\"2216\">87</sup> שהוא ביטול היש כידוע ע\"י בינה ליבא דוקא אז מעוררי' רחמים<sup data-n=\"2217\">88</sup> המרובי', הוא התפשטות הארה לבד מן הרצון שבנפש המדיח ומעביר גסות הנוגה דמדות מים הרעים דתשוקת עוה\"ז נמתקים במים היפים דנהרי אפרסמונא דכיא<sup data-n=\"2218\">89</sup> הוא המשכת הארת הרצון שהוא נמשך ברוחב בנהר כמ\"ש במ\"א כו' וד\"ל. אבל בינה ליבא ביציאתה מנרתק נוגה שלה לא תצא ע\"י בכיי' כ\"א ע\"י פדיי' או יעוד כנ\"ל<sup data-n=\"2219\">90</sup>.",[["2203","74","<b>הרצון הנק' כלה</b>: ראה גם מאמרי אדה\"ז אתהלך ע' קיא. וראה גם לעיל פ' בשלח רח, א ובהערה 19."],["2204","75","<b>כל מה שהסוס רץ ומיצל </b>[יא: ומציל]: ראה פסחים נ, א."],["2205","76","<b>תא הרצים</b>: מל\"א יד, כח. ראה גם לעיל קפב, ג. וש\"נ."],["2206","77","<b>שלה</b>: זיא: ליתא."],["2207","78","<b>וזהו</b>: שם: והיינו."],["2208","79","<b>והפדה</b>: משפטים כא, ח."],["2209","80","<b>מרע</b>: יא: בסו\"מ בסור מרע."],["2210","81","<b>הארה</b>: זיא: האמה."],["2211","82","<b>המדות</b>: שם: המהות."],["2212","83","<b>כו'</b>: שם: וד\"ל."],["2213","84","<b>הבע\"ת</b>: שם: הכנעתם."],["2214","85","<b>האמיתי</b>: ז: האמ[ית]ית. יא: בעצם."],["2215","86","<b>אנן בעינן למהוי קדם מלכא</b>: נסמן לעיל רפח, ב הערה 83."],["2216","87","<b>אל דמי לך</b>: נסמן לעיל רעג, ב."],["2217","88","<b>רחמים</b>: יא: רח\"ר."],["2218","89","<b>דנהרי אפרסמונא דכיא</b>: ראה תענית כה, א. לעיל פ' שמות לד, ב. וש\"נ."],["2219","90","<b>כנ\"ל</b>: ז ניתוסף: וד\"ל. יא: וד\"ל."]]],[2300550244,"<b>ועיקר</b> ענין היציאה הוא ענין המס\"נ לאחר התפלה בנ\"א<sup data-n=\"2220\">91</sup> שהוא היציאה ממהותה לגמרי ולהכלל במקור חוצבה, ובעת יציאת המדות יצאו בבכי מפני גסות נוגה שלהם, אבל יציאת ההשגה ממהותה אינה בבכי מן הרגשת היש כו' כי עוז וחדוה בפנימי' בינה שבלב ע\"י פדיי' או יעוד וד\"ל.\n<b>והנה</b> עי\"ז<sup data-n=\"2221\">92</sup> יובן למשכיל למעלה בנער מט\"ט עבדא דשכינתא [דמטרוניתא] ואמה הוא חב\"ד דבריא' ושש שנים שהוא ו\"ק הנמשכים ממנה שהוא מדות שבשכל הוא יעבוד להמשיכם לעולם הבריאה וכן ו\"ק דיצי' ועשיי' הי' חנוך תופר מנעלים<sup data-n=\"2222\">93</sup> דיצי' ועשי' לחברם ולייחדם באמה וכו' והוא [כ]משל הבאת העבד העברי מבחוץ וד\"ל, אבל בחב\"ד דבריאה אין עלייתה ומ\"ן שלה במי בוכי' אף אם רעה בעיני אדוני' אלא יפדנה בבחי' אותיות שבה שהוא הארת הראשית בסוף כו', או לבנו שהוא ו' זעירא ייעדנה<sup data-n=\"2223\">94</sup> כו' וד\"ל. והנה בכל ניצוץ אלק[ו]' יש נרנח\"י ובתחילת קומו משינתו יהי' בחי' עבד כנעני אפי' בצדיק גמור עד ב\"ש, דהיינו עבודת[ו] לאכפיי' לסט\"א דעשיי' כו', וכמבואר ברמב\"ם<sup data-n=\"2224\">95</sup> דאף צדיק גמור שלבו חלל בקרבו<sup data-n=\"2225\">96</sup> ומואס ברע שבטבע נפש רוח הבהמה<sup data-n=\"2226\">97</sup> בחמדת עוה\"ז גזל ועריות<sup data-n=\"2227\">98</sup> וכדומה, עכ\"ז באותו רע שאין הטבעיות מחמדתו כמו אכילת חלב וחזיר לא יאמר אי אפשי<sup data-n=\"2228\">99</sup> כו' שהוא מואס ברע אלא יסור מהם בעקשות לבד מצד שצוה ה' [לסור מהם] ולא מצד רצון נפשו. וטעם ההפרש בין ב' מיני רע, דידוע ענין עשה ול\"ת דל\"ת גבוהים בשרשם מבחי' עשה<sup data-n=\"2229\">100</sup> בבחי' אצי' שהם נק' חוקות שחקקתי לא תלבש כלאים<sup data-n=\"2230\">101</sup> מניעותא<sup data-n=\"2231\">102</sup> כו', פי' עד\"מ מהמשכת אהבה בלב שמניעת ההמשכה שלא תהי' האהבה יותר או באופן אחר כו' הוא גבוה ונעלה מההמשכה עצמה, והוא חק המשכת האהבה עד כאן ולא יותר וד\"ל, כמו\"כ יובן בהמשכת <span data-k=\"pg\">עד</span> ּ אורות מדותיו ית' בבחי' אצי' להיות אותיות וכלים<sup data-n=\"2232\">103</sup> דאצי' כידוע שהם אברי' דמלכא והם רמ\"ח פקודין<sup data-n=\"2233\">104</sup> דעשה, והמשכת האורות בתוך הכלים הי' בכל המשכה חק וגבול הנעלם וגבוה ממנה כנ\"ל<sup data-n=\"2234\">105</sup> והוא ענין שס\"ה ל\"ת בגידי' שהן חוקו' אופן ההמשכה בכל אבר וד\"ל. ולכן אין במיאוסו לסור מחלב ודם שום העלאת מ\"ן<sup data-n=\"2235\">106</sup> לחוקות אכילת חלב [ודם] שבבחי' אצי' שהוא מניעותא כו' בחי' סובב ומקיף כו', אלא באכפיי' בעקשות אבי שבשמים גזר ותיקן כו'<sup data-n=\"2236\">107</sup>, בכפיי' זו יכול יותר להיות",[["2220","91","<b>בנ\"א</b>: בנפילת אפים."],["2221","92","<b>עי\"ז</b>: זיא: עד\"ז."],["2222","93","<b>חנוך תופר מנעלים</b>: ראה גם לעיל פ' בשלח קנח, ב. וש\"נ."],["2223","94","<b>או לבנו. . ייעדנה</b>: משפטים כא, ט."],["2224","95","<b>וכמבואר ברמב\"ם</b>: ראה שמונה פרקים פ\"ו."],["2225","96","<b>דאף צדיק גמור שלבו חלל בקרבו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>."],["2226","97","<b>נפש רוח הבהמה</b>: זיא: הבהמי[ו]ת."],["2227","98","<b>ועריות</b>: להעיר מרמב\"ם שם."],["2228","99","<b>אכילת. . וחזיר לא יאמר אי אפשי</b>: ראה תו\"כ ס\"פ קדושים."],["2229","100","<b>דל\"ת גבוהים. . עשה</b>: ראה אגה\"ת פ\"א. מאמרי אדה\"א דברים ח\"ב ס\"ע תריח ואילך. וש\"נ."],["2230","101","<b>לא תלבש כלאים </b>[יא: שעטנז]: תצא כב, יא."],["2231","102","<b>כלאים מניעותא</b>: זהר קדושים פו, ב."],["2232","103","<b>אותיות וכלים</b>: יא: או\"כ אורות וכלים."],["2233","104","<b>אברי'. . רמ\"ח פקודין</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["2234","105","<b>כנ\"ל</b>: זיא: כו'."],["2235","106","<b>אין במיאוסו. . העלאת מ\"ן</b>: ראה גם שע\"ת עא, סע\"ד ואילך."],["2236","107","<b>ותיקן כו'</b>: זיא: וחקק כנ\"ל."]]],[2300550275,"העלאת מ\"ן כו', מפני שהכפיי' בלא רצון הנפש הרי הוא בריחוק גדול מאלקות, וכל שהוא רחוק יותר הרע<sup data-n=\"2237\">108</sup> מדת ההתפארות [כו'] והכבוד מתעורר עליו כמ\"ש במ\"א שהכנעת אוהבו ומקורבו אינו כבוד כלל<sup data-n=\"2238\">110</sup>, דוקא הכנעת הרחוק<sup data-n=\"2239\">109</sup> מאד ממנו אז יתעורר מדת התפארו' כו'. ולכן בכפיית הסט\"א בבחי' עקשות ובקרירות בלא פנימית הרצון אז אסתלקותא יקרא דקודב\"ה<sup data-n=\"2240\">111</sup> בחי' ת\"ת דאצי', כמו ביתרו שהי' רחוק מאד ואמר עתה ידעתי<sup data-n=\"2241\">112</sup> כו' נתעורר [עיקר] שלימות הארת אלקות במשה וישראל מה שלא הי' התגלות זה בלעדי יתרו, מפני שמשה וישראל עם קרובו כו'. וכן בעבד כנעני לסור בעקשות לבד מחלב יעורר בחי' ת\"ת יקרא דקודב\"ה שהוא בעל החוקות בישראל דלעילא חו\"ג דאצי' וד\"ל, ולכן אל יאמר אדם אי אפשי כו'. אבל במה שהומשך רע בנפש האדם כמו גזל ועריות צ\"ל מואס ברע כדי שיהי' אהבתו לה' ברה וזכה מגסות הנוגה שלא יחשיך כשיהי' לו ג\"כ האהבה לגזל כו' וד\"ל.\n<b>והנה</b> מב\"ש עד יוצר אור הוא בחי' ע\"ע ברעותא דלבא קצת אלא שהוא נפרד מן השכל, והרי ההשגה באלקות שמחמתה מתפעל הוא בבחי' ריחוק אצלו עדיין אלא כאדם ששומע דבר חדש או כמו הלומד שלא בעיון לעמוד על הדבר אלא לומד ליגמר<sup data-n=\"2242\">113</sup> שידע הדברים לבד במוחו, ועדיין אינו מדקדק בהדבר איך הוא ומה הוא שזה נק' עיון ובינה פי' שמתבונן הוא שעומד על הדבר הרבה ומעיין הרבה במהות הדבר מ[ה] הו[א כו']. נמצא קודם שעמד על הדבר הרבה לא הכיר הדבר הכרה גמורה והי' רחוק מאותו הדבר וכשהתבונן בו נכנס לעומקו של דבר ונתקרב אליו כו', וזהו ליגמר אינש והדר ליסבר<sup data-n=\"2243\">114</sup> וד\"ל. כמו\"כ יובן למשכיל ענין ס[י]דר שבח[י]ו של מקום בפסוד\"ז היינו רק כמו אדם השומע דבר חדש שמתפעל לבו ממנו מחמת ההתחדשות, אך עדיין לא עמד על הדבר חדש להתבונן<sup data-n=\"2244\">115</sup> בו להיות הדבר בקירוב גדול בלבו כנ\"ל<sup data-n=\"2245\">116</sup> אלא עסוק בשמיעה לבד לשמוע במהירות המוח לבד כו' (ונק' בגמ' רהיטא<sup data-n=\"2246\">118</sup> שמרהיט במוח הגירסא כו')<sup data-n=\"2247\">117</sup>. וכן בפסוקי דזמרה השבחים הלא הם עיקר ההתבוננו' בגדולת ה' שגם בש\"ע יתפעל מהם בבחי' ביטול כמשי\"ת. אלא ע\"פ סדר ד' תיקוני דשכינתא<sup data-n=\"2248\">119</sup> המבוארי' בזהר, בפסוד\"ז אינה בנפש אלקי' אלא חיצוני' בינה שבה ולא בינה ליבא, שהתפעלו' הלב עדיין בריחוק",[["2237","108","<b>הרע</b>: שם: יהי'."],["2238","110","<b>כלל</b>: יא: כ\"כ כל כך."],["2239","109","<b>שהכנעת. . הרחוק</b>: ראה גם מאמרי אדה\"ז הקצרים ע' קכא. פרשיות התורה ח\"א ע' קצב. ח\"ב ע' תקנה. שער היחוד והאמונה פ\"ז."],["2240","111","<b>בכפיית הסט\"א. . אסתלקותא יקרא דקודב\"ה</b>: ראה זהר תרומה קכח, ב. יתרו סז, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' ה. וראה גם מאמרי אדה\"א נ\"ך ע' רעו. וש\"נ. לקמן פ' פקודי תמו, ג. לקו\"ת שם ז, א."],["2241","112","<b>עתה ידעתי</b>: יתרו יח, יא. ראה גם לקמן פ' ויקהל תו, א ובהערה 557."],["2242","113","<b>ליגמר</b>: יא: ליתא."],["2243","114","<b>ליגמר אינש והדר ליסבר</b>: ראה ע\"ז יט, א."],["2244","115","<b>חדש להתבונן</b>: ז: חידוש להתבונן. יא: הרבה בחידושי' ועדיין לא התבונן."],["2245","116","<b>כנ\"ל</b>: שם: כ\"כ."],["2246","118","<b>ונק' בגמ' רהיטא</b>: שבת קל, ב."],["2247","117","<b>(ונק'. . כו')</b>: שם: ונק'. . כו'."],["2248","119","<b>ד' תיקוני דשכינתא</b>: ראה זהר תרומה קלג, א. מאמרי אדה\"א דברים ח\"ב ע' תח. וש\"נ. נ\"ך ע' טז."]]],[2300550303,"מן השבח במוח [כו'] ואינו אלא כמו מסדר אותו<sup data-n=\"2249\">120</sup> כדוגמת רהיטת הגירס' ולכן הוא בקרירות שבמוח לבד כו'. אבל כשמתפשט' בלב<sup data-n=\"2250\">121</sup> התבוננו' השבח בקירוב גדול [בלב] לעמוד עליהם בהכרה שבלב כו' הוא בברכת יוצר אור, שמשם מתחיל כניסת ז' היכלות<sup data-n=\"2251\">122</sup> דמדות להפכם לה', מפני שאין הפיכת המהות אלא <span data-k=\"pg\">150</span> ּ בבינה ליבא כנ\"ל ובק\"ש שאז התקשרות אמיתי' הנפש בה' אחד מהות מדותיו ית' וכידוע. לכן תחילה צריך לה[ת]תקן בנפש היכל האהבה שהוא נתקן בברכת אה\"ר, והיינו ע\"י בינה ליבא יהי' תשוקת הלב באחדות גמור עם ההתבוננו' ויהי' בחי' היכל לה' כידוע, ואז ע\"י ההיכל יכול ההתבוננו' שבנפש באחדו' הבורא לקבל השרא' אלקות בהיכל שבה<sup data-n=\"2252\">123</sup> כשאומר פסוק שמע ישראל כו', דהיינו כמו שהוא באמת ענין אחדות הוי' כו' ולא רק כמו הגבלת ההתבוננו' שבנפש וד\"ל. וקודם ש\"ע הוא היכל ק\"ק והוא היכל החכ' שבנפש להפוך חשך ההשגה אלקי' דהיינו כשיאיר היטב [בנפש] ענין ההתחדשות מאין ליש ולא יסתירנה נוגה דבריאה כנ\"ל, והוא עבודת אמה העברי' בינה ליבא לתקן נוגה שלה וכנ\"ל והוא עיקר תיקון בחי' כסא כו', ואח\"כ יוכל להיות בחי' מנורה בברכות ש\"ע שהוא ההשתחוואה והביטול הרגשת עצמותו מכל וכל כידוע שהוא כ\"ח מ\"ה שבנפש שהארתו מן כתר שבה הנק' כלה וכנ\"ל, ואז מקבלת שלהבת י\"ה והוא היחוד האמיתי שמקבלת אש שלמעלה מכהנא רבא חסד דאצי' המדליק המנורה וד\"ל. ואחר ש\"ע הוא נפילת אפים שהוא למעלה ממדרגת מס\"נ, שפי' מס\"נ הוא כשעדיין עסוק במסירה אליך ה' נפשי אשא<sup data-n=\"2253\">124</sup> עד הפשט' הרגשת עצמות[ו] שבכ\"ח מ\"ה שבה בש\"ע. אבל לאחר מסירה והפשטת עצמות[ו] שנעשית רק נקודה חדא בחי' הרצון שבה לבד וכשתחזור ותבנה בחו\"ב ומדות באותו אופן שהיא במקור חוצבה הוא בחי' נ\"א, כמו משל המתבטל מעצמותו כשרואה דבר נפלא ונעשה רק נקודה א' ואח\"כ כשהוא רגיל בו יש לו התפשטו' חו\"ב אורך ורוחב כמו קודם<sup data-n=\"2254\">125</sup> רק שהוא באופן יותר נפלא שאין ערוך לאורך ורוחב הראשון לו כו' וכמ\"ש במ\"א בענין ה' כמלקדמין<sup data-n=\"2255\">126</sup> וד\"ל<sup data-n=\"2256\">127</sup>. ונמצא מאחר דמה לי קטלא כולא<sup data-n=\"2257\">128</sup> או פלגא כמו שיש כל אלו המדרגו' במס\"נ הכלל[י] כמו\"כ בכל פרט שבה וד\"ל, וגם לאחר ש\"ע יהי' הפרש בין נ\"א דחכ' לנ\"א דמדות כנ\"ל וד\"ל.",[["2249","120","<b>אותו</b>: זיא: אותיות שהוא."],["2250","121","<b>בלב</b>: שם: ליתא."],["2251","122","<b>יוצר אור. . מתחיל. . ז' היכלות</b>: ראה סידור האריז\"ל במקומו."],["2252","123","<b>שבה</b>: ז: ליתא."],["2253","124","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["2254","125","<b>כמו קודם</b>: זיא: במקורם."],["2255","126","<b>ה' כמלקדמין</b>: זהר בלק קצא, א. ראה גם ביאוה\"ז שם קב, ג."],["2256","127","<b>כמלקדמין וד\"ל</b>: ז: כו'. יא: ליתא."],["2257","128","<b>דמה לי קטלא כולא</b>: ב\"ק סה, א."]]],[2300550053,"<b>בעז\"ה דרוש אדמו\"ר ר' דובער פ' משפטים</b>\n<span data-k=\"pg\">860</span> ּ[א] לא תהי' משכלה<sup data-n=\"2258\">1</sup> ועקרה בארצך<sup data-n=\"2259\">2</sup> את מספר ימיך אמלא, וי\"ל מהו ענין משכלה ועקרה [ש]לא תהי' בארצך דוקא וכי הארץ יולדת כו'. וגם מה זה שייך לענין את מספר ימיך אמלא כו'. אך הנה ידוע [ד]כנ\"י נק' ארץ כמ\"ש כי תהי[ו אתם] ארץ חפץ<sup data-n=\"2260\">3</sup>, ולמעלה נק' אה\"ח<sup data-n=\"2261\">4</sup> כמ\"ש אתהלך לפני ה' בארצות החיים<sup data-n=\"2262\">5</sup> ב' ארצות ארץ עילאה וארץ תתאה כמ\"ש בזהר, ופי' ארץ החיים שמקבל[ת] כל אורות וחיים<sup data-n=\"2263\">6</sup> [ה]עליונים דאצי' הנזרעים בתוכה כמ\"ש אור זרוע לצדיק<sup data-n=\"2264\">7</sup> כו' ואובדת<sup data-n=\"2265\">8</sup> ואולידת ועבדת פרי<sup data-n=\"2266\">9</sup> ונותנת חיים ומזון לכל העולמות, ולזאת נק' בשם ארץ החיים ע\"ש קבלת השפע [וע\"ש ההשפעה] לכל העולמות כו' וכמו בי\"מ שא[מר] תדשא הארץ<sup data-n=\"2267\">10</sup> תוצא הארץ<sup data-n=\"2268\">11</sup> כו'. וכמו עד\"מ הארץ הגשמי' שממנה יוצאת חיים ומזון לכל עליון<sup data-n=\"2269\">12</sup> ונק' ארץ דמפק[א] מזון<sup data-n=\"2270\">13</sup>, כי כח הצומח שבארץ יצמיח בה כל פרי תבוא[ו'] השדה ופירות באילן וכמו<sup data-n=\"2271\">14</sup> מיני מגדים להחיות בהן כל חי אדם ובהמה [וחי' ב]חיים הגשמי' להיות למזון וטרף שלהם לכאו\"א למיניהם, ובלעדי זה לא הי' לכל הברואים שום קיום וחיות כלל אפי' רגע. ואף כי ירבה הכסף וזהב וכל הון ועושר לא יועילו להחיות נפש כל חי כ\"א הארץ שתוציא צמחה להחיות כ\"ח, וא\"ל<sup data-n=\"2272\">15</sup> הי' צמח האדמה לא הי[' קיום] לעולם. ואמנם זאת הצמיחה בארץ [היא] באה רק מב' סיבות א' מן הזרע שנזרע בה שאם לא היו זורעי' בארץ לא הי' צמיחה [ב]תבואות השדה כלל. והב' מכח הצומח ש[ניתן] בארץ מכח האלקי שיצמיח כל צמח הארץ כצמח השדה וכה\"ג, [וגם] בצמח התבואה והפירות הכל בא מכח אלקי ששורה להמשיך כח זה מכח הצומח שב[א] במא[מר] תדשא הארץ דשא עשב מזריע זרע ועץ עושה פרי<sup data-n=\"2273\">16</sup> כו' וכמ\"ש וכל שיח השדה כו' וכל עשב השדה טרם יצמח כי לא המטיר ה'<sup data-n=\"2274\">17</sup> כו', ואחר שהארץ מקבלת הכח העליון הזה אז תוציא הארץ צמחה להחיות כל חי כו'. וכך<sup data-n=\"2275\">18</sup> יובן בארץ העליונה בבחי' אור ושפע החיות [ה]אלקי הרוחני שנק' אה\"ח למעלה שמקבלת כל שפע אור הזרוע בה",[["2258","1","<b>לא תהי' משכלה</b>: מיוסד על מאמר ד\"ה זה שנדפס ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370349\" data-slug=\"torah-or\" data-id=\"3901370349\">תו\"א עח, ד</a> [וראה הנסמן במ\"מ לשם]. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["2259","2","<b>לא תהי' משכלה ועקרה בארצך</b>: משפטים כג, כו."],["2260","3","<b>כי תהי[ו אתם] ארץ חפץ</b>: מלאכי ג, יב."],["2261","4","<b>אה\"ח</b>: הט: ארץ החיים."],["2262","5","<b>אתהלך לפני ה' בארצות החיים</b>: תהלים קטז, ט. מובא גם בשם הזהר במאמרי אדה\"א במדבר ח\"ב ע' תקעא."],["2263","6","<b>וחיים</b>: הט: החיים."],["2264","7","<b>אור זרוע לצדיק </b>[הט: לצ\"ע]: תהלים צז, יא."],["2265","8","<b>ואובדת</b>: שם: ליתא."],["2266","9","<b>ואולידת ועבדת פרי</b>: ראה זהר בהקדמה יב, א. בראשית מו, א."],["2267","10","<b>תדשא הארץ</b>: בראשית א, יא."],["2268","11","<b>תוצא הארץ</b>: שם א, כד."],["2269","12","<b>עליון</b>: הט: הדרים עלי'."],["2270","13","<b>ארץ דמפק[א] מזון</b>: ברכות מט, א."],["2271","14","<b>וכמו</b>: ט: וכל."],["2272","15","<b>כ\"ח וא\"ל</b>: הט: כל חי ואם לא."],["2273","16","<b>ועץ עושה פרי</b>: בראשית א, יב. הט: עץ — לפי\"ז הוא המשך הכתוב שלפנ\"ז בדילוג תיבת פרי."],["2274","17","<b>וכל שיח השדה. . ה'</b>: בראשית ב, ה."],["2275","18","<b>וכך</b>: הט: וכמו\"כ."]]],[2300550085,"מבחי' צ\"ע<sup data-n=\"2276\">19</sup> דאצי', וממנה נמשך ונשפע כל אור וחיות [ו]מזון רוחני לכל העולמות בכל מיני שפע חיצוני' ופנימי' למלאכים ונשמות כמ\"ש בזהר ע\"פ מצמיח <span data-k=\"pg\">תל</span> ּ חציר לבהמה<sup data-n=\"2277\">20</sup> כו', דמלאכים שמקבלים מצמיחת עשב הארץ העליונה<sup data-n=\"2278\">21</sup> נק' חציר כו' שנק' מאכל בהמה. ויש שפע פנימי' שנמשך מאה\"ח העליונה לנשמות ומלאכים<sup data-n=\"2279\">22</sup> כמ\"ש קדש [ישראל] לה' ראשית<sup data-n=\"2280\">23</sup> תבואתו<sup data-n=\"2281\">24</sup> כו' שנק' מאכל אדם, שהוא ענין הכח והעוז להחיותם במזון העליון דתבואות הארץ להיות בהם חיות [ה]אלק[י] למזון ממש להוסיף אור חדש במוחין ומדות אהוי\"ר שלהם כמו אהוי\"ר מהתבוננו', שנמשך לאדם בפרט ולכנ\"י בכלל [בק\"ש] באמרו ואהבת את ה' אלקיך כו' בכל לבבך בב' יצריך<sup data-n=\"2282\">25</sup> [ב]נשמה [ו]גוף הטבעי ג\"כ. וגם להיות בו כח המעשה בפו\"מ להיות סו\"מ וע\"ט ולדבק במצות ה' לעשות אותם וחי בהם<sup data-n=\"2283\">26</sup> חיי[ם] אמיתי' ממש מחיי החיים<sup data-n=\"2284\">27</sup> כו', כדוגמת חיים ומזון שיחי' האדם מזרע פרי תבואת הארץ כו' שי[ו]צא ויצמיח ממנה להחיות כ\"ח<sup data-n=\"2285\">28</sup> כו' שבלעדי זה אין לו<sup data-n=\"2286\">29</sup> קיום כלל. וכך הוא ממש כל בחי' אור וחיות האלקי הרוחני הנמשך לאדם [מ]ארץ העליונה לכל פרטי אור וחיות נפשו, או להחיות המוחין בתו\"מ ועבודה שבלב בתפלה באהוי\"ר שכלי' וטבעי', הכל נמשך מבחי' אה\"ח דלעילא [דמפקא מזון העליון לכל העולמות. וז\"ש אתהלך לפני ה' בארצות החיים ארץ עילאה וארץ תתאה דהיינו כנ\"י דלעילא] וכנ\"י דלתתא, וכנ\"י דלעילא נק' ארץ עילאה כנ\"ל ובירידתה והמשכתה למטה בנש\"י בגופי' נק' ארץ תתאה דהיינו כנ\"י דלתתא [שמהם מקבלים כל] [ה]עולמות כו' וד\"ל (ובמ\"א בפ' וישב<sup data-n=\"2287\">30</sup> מבואר בפי' בארצות החיים ארץ עילאה בחי' בינה וארץ תתאה בחי' המל' ושניהם למעלה והוא מ\"ש ישראל עלו במח'<sup data-n=\"2288\">31</sup> דבינה כו').\n(ב) <b>והנה</b> מבואר לעיל<sup data-n=\"2289\">32</sup> במשל ארץ הגשמי' שיש בה ב' סיבות לצמיחה כל צמח שבהארץ<sup data-n=\"2290\">33</sup>, א' מן הזרע שזורעים [בה]. והב' מכח העליון הניתן בכח הצומח שבה להצמיח כל צומח כו'. וכך יובן בנמשל בכנ\"י שלמטה<sup data-n=\"2291\">34</sup> שהוא כמו כנ\"י שלמעלה [ש]מקבלת אור הזרוע [לצדיק עליון] כו', כך כנ\"י שלמטה [ש]נק' ג\"כ בשם צדיק כמ\"ש ועמך כולם צדיקים<sup data-n=\"2292\">35</sup> ממש<sup data-n=\"2293\">36</sup>, ולא שיכוין בזה בשם התואר בבחי' מדרגת צ\"ע<sup data-n=\"2294\">37</sup> בדביקות והתקשרות אמיתי' [שה]איך אפשר שיהיו כולם צדיקים גמורים. אלא הכוונה על שרש הנשמות שבגופי' שכלול[ים] מב'",[["2276","19","<b>צ\"ע</b>: הט: צדיק עליון."],["2277","20","<b>מצמיח חציר לבהמה</b>: נסמן לעיל רעז, ד."],["2278","21","<b>העליונה</b>: הט: עילאה."],["2279","22","<b>ומלאכים</b>: ט: ליתא."],["2280","23","<b>קדש [ישראל] לה' ראשית תבואתו</b>: ירמי' ב, ג."],["2281","24","<b>תבואתו</b>: ט: תבואתה. ראה מאמרי אדה\"א שמות ח\"א ע' א ובהערה שם."],["2282","25","<b>ואהבת. . בב' יצריך</b>: נסמן לעיל פ' יתרו רנד, ב."],["2283","26","<b>וחי בהם</b>: אחרי יח, ה."],["2284","27","<b>מחיי החיים</b>: ראה יומא עא, א."],["2285","28","<b>כ\"ח</b>: הט: כל חי."],["2286","29","<b>אין לו</b>: ה: אין להם. ט: לא יהי' להם."],["2287","30","<b>בפ' וישב</b>: ראה תו\"ח שם רג, ד. אוה\"ת כאן ע' ב'תשל."],["2288","31","<b>ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. הנסמן לעיל פ' שמות לב, ב."],["2289","32","<b>לעיל</b>: הט: למעלה."],["2290","33","<b>שבהארץ</b>: שם: שבה."],["2291","34","<b>שלמטה</b>: תוקן ע\"פ הט. ובתו\"ח: שלמעלה."],["2292","35","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["2293","36","<b>ממש</b>: הט: ליתא."],["2294","37","<b>צ\"ע</b>: שם: צדיק גמור."]]],[2300550117,"מדרגות צ\"ע וצ\"ת שז\"ש צדיקי' תרין<sup data-n=\"2295\">38</sup> כמ\"ש בזהר, והן ב' מיני נהורין שבנשמ[תא] נה\"ח<sup data-n=\"2296\">39</sup> [והוא אור המאיר ונהורא אוכמא<sup data-n=\"2297\">40</sup> הוא] אור השורף ומכלה לגוף כמ\"ש במ\"א בענין נר ה' נשמת אדם<sup data-n=\"2298\">41</sup> וכמ\"ש כי אתה [תאיר] נרי<sup data-n=\"2299\">42</sup> כו'. והנה בחי' אור העליון שבנשמות הוא בחי' אור ושפע<sup data-n=\"2300\">43</sup> גילוי אלקו' בנשמה כמו בהלו נרי על[י] ראשי<sup data-n=\"2301\">44</sup> כו' והוא ממש כמו בחי' צ\"ע למעלה שנא' בו אור זרוע לצ\"ע<sup data-n=\"2302\">45</sup> כו', והוא המשכת גילוי אלקות ע\"י תומ\"צ שנק' זריעה כמ\"ש זרעו לכם לצדקה<sup data-n=\"2303\">46</sup> וכן א[מר] זורע צדקות<sup data-n=\"2304\">47</sup> כו'. ולכך נק' כולם צדיקים לפי שכללות נש\"י הם נק' צדיקים בתו\"מ בפו\"מ עכ\"פ דאפי' ריקנים [שבהם] מלאים מצות כרמון<sup data-n=\"2305\">48</sup> ולכך כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"2306\">49</sup> שנא' ועמך כולם צדיקים לעולם ירשו ארץ שהוא אה\"ח העליונה, לפי שע\"י [ה]זריעה שלהם בתו\"מ בעוה\"ז שמוסיפים ריבוי הצמיחה עד אין שיעור למעלה באורות יחו\"ע<sup data-n=\"2307\">50</sup> דאצי', וע\"כ לעולם ירשו ארץ לעולם הבא שנא'<sup data-n=\"2308\">51</sup> כמ\"ש זרעו לכם כו' וקצרו<sup data-n=\"2309\">52</sup> לפי חסד שהוא [בעוה\"ב שהוא] שכר מעשה המצות בעוה\"ז דוקא (וכמו <span data-k=\"pg\">862</span> ּ אדה\"ר בג\"ע שנא' ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"2310\">53</sup> שע\"י עבודתו בג\"ע בנטיעה וזריעה ניתוסף צמ[י]ח[ת] אורות העליונים בג\"ע בכפלי כפליים לאין שיעור כו'). וכך כנ\"י<sup data-n=\"2311\">54</sup> שנקראו צדיקים שמשפיעים אור הזרוע לצ\"ע ממש בארץ וכמ\"ש לעשות חסד ומשפט וצדקה בארץ<sup data-n=\"2312\">55</sup> דוקא, והן [עצמן] מצד חלק הנשמות שבגופים הם בחי' מקבלים אור הזרוע דתו\"מ להוציא [צמח] הארץ בכפלי כפליים והוא ע\"י מה שנולד בהם התפעלות ודביקות באלקו' באוי\"ר שכליים. דהגם שאנו רואים שכ\"א לפי שכלו והשגתו יתפעל בלבו באוי\"ר, ודאי אין זה מכח עצמו ממש אלא הוא בא מאור הזרוע לצ\"ע בארץ עילאה הנ\"ל ומשם נצמח בכח הצומח דארץ העליונה להיות [מזון לנשמות ומלאכים הנ\"ל, עד גם לנשמות שבגופים שנק' ארץ תתאה. שזהו מה שהצמיח אור התפעלות אהבת ה' ויראתו] באדם למטה ולנטוע בלב[ו ועל פניו] אהוי\"ר זו כל הימים [בל ימוט לעולם] כי כ\"ז<sup data-n=\"2313\">56</sup> שיומשך כח האדם [מצד] עצמו אין לו קיום כלל וחולף ועובר, כידוע שגם ברוב יגיעת האדם להתבונן ולהשיג בגדולת ה' עד שיתפעל בלבו ברשפי אש אוי\"ר במעט רגע יתבטל והי' כלא הי' ממש ונעשה בלא אור וחיות כלל וכמת יחשב כו'. אך ורק מה שנמשך באדם מכח אור הזרוע לצ\"ע באה\"ח העליונה עד [ל]נשמות שבגופי' שיתעורר ברוח העליו[ן] וזהו שנטוע ומושרש בו בעולם בלי יבוטל לעולם,",[["2295","38","<b>צדיקי' תרין</b>: ראה זהר ויצא קנג, ב. מאמרי אדה\"א בראשית ע' צג. וש\"נ. שמות ח\"ב ע' תרכט. ש\"א ג, א ובהערה 21. לקמן פ' תצוה שנה, ד."],["2296","39","<b>נה\"ח</b>: הט: נהורא חיוורא."],["2297","40","<b>נה\"ח. . ונהורא אוכמא</b>: ראה זהר בראשית נא, רע\"א."],["2298","41","<b>נר ה' נשמת אדם</b>: משלי כ, כז. ראה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרמג ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370182\" data-slug=\"torah-or\" data-id=\"3901370182\">תו\"א מקץ מ, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370158\" data-slug=\"torah-or\" data-id=\"3901370158\">ש\"א לד, ב</a> ואילך. לעיל פ' בשלח רלח, ב."],["2299","42","<b>כי אתה [תאיר] נרי</b>: תהלים יח, כט."],["2300","43","<b>ושפע</b>: הט: משפיע."],["2301","44","<b>בהלו נרי על[י] ראשי</b>: איוב כט, ג."],["2302","45","<b>לצ\"ע</b>: הט: לצדיק."],["2303","46","<b>זרעו לכם לצדקה</b>: נסמן להלן הערה 52."],["2304","47","<b>זורע צדקות</b>: ברכת יוצר."],["2305","48","<b>ריקנים [שבהם] מלאים מצות כרמון</b>: ראה ערובין יט, א."],["2306","49","<b>כל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין צ, א (במשנה)."],["2307","50","<b>יחו\"ע</b>: הט: עליונים."],["2308","51","<b>לעולם הבא שנ'</b>: הט: שלהם הוא."],["2309","52","<b>זרעו לכם כו' וקצרו</b>: הושע י, ב [ושם: קצרו — ראה הנסמן לעיל פ' וארא פב, א הערה 665]."],["2310","53","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["2311","54","<b>כנ\"י</b>: הט: בנש\"י."],["2312","55","<b>לעשות חסד ומשפט וצדקה בארץ</b>: ירמי' ט, כג [ושם: עושה — ראה הנסמן לעיל פ' בשלח קלח, ד הערה 330]."],["2313","56","<b>כ\"ז</b>: הט: כל מה."]]],[2300550149,"והוא כמשל הזריעה שצומח[ת] בלי שיעור והיינו ע\"י זריעה דתו\"מ דוקא. וגם זריעה זאת צ\"ל ע\"י בחי' החסדים העליוני' שיש במצות העליוני' למעלה [ו]כמ\"ש אשריכם זורעי על כל מים<sup data-n=\"2314\">57</sup> העליוני' וז\"ש זרעו לכם לצדקה שהן המצות שנק' צדקה<sup data-n=\"2315\">58</sup> ואז וקצרו כו' וד\"ל. וא\"כ הרי [מ]ובן מכ\"ז עכ\"פ שאין עיקר החיוב על האדם רק לעבוד עבודת הארץ העליונה, שהוא [ל]זרוע צדקות דתו\"מ ולתקן הזריעה שתקלוט בארץ הוא החרישה דמרפי ארעא<sup data-n=\"2316\">59</sup> והסרת הקוצים ואבנים שהוא ענין סו\"מ [בתשובה ו]לב נשבר להכניע חומרי[ות] עפר הגוף כו' (כמו לעבדה ולשמרה בג\"ע כו'). ואז יתן ה' כח עילאה בכח הצמיחה העליונה שבארץ להצמיח כל<sup data-n=\"2317\">60</sup> צמיחה שהוא המזון וחיות לנשמות בתולדות אוי\"ר אמיתי' הנ\"ל לבלתי יפול הנופל לעולם (וכמבו\"ל<sup data-n=\"2318\">61</sup> דהמשכת הכח בכח הצומח להצמיח כו' בא מעצמו' אור האלקי כו'. ונמצא יש כאן ב' סיבות א' מן הזרוע לצ\"ע למעלה ולמטה כו' והמשכת כח העליו[ן ב]כח הצומח שבארץ עילאה וארץ תתאה.\n<b>וזהו</b><sup data-n=\"2319\">62</sup> בחי'<sup data-n=\"2320\">63</sup> אור זרוע [לצדיק] לצ\"ע והוא בשביל צדקות<sup data-n=\"2321\">64</sup>, כאלו א[מר] אור זרוע לצדיקים לעוה\"ב בשביל צדיקים, וזהו כנ\"י שלמטה שנק' צדיקים במעשה המצות שיאכלו פרי מעשיהם לעוה\"ב [ו]בשביל זה נזרע אור העליון מבחי' צ\"ע וקצירתו<sup data-n=\"2322\">65</sup> הוא לעוה\"ב וכמ\"ש וקצרו לפי חסד וכן הוא או' זורע צדקות מצמיח ישועות כו'. והוא מ\"ש [ו]לישרי לב<sup data-n=\"2323\">66</sup> בעבודה דתו\"מ באוי\"ר אמיתי' שמחה העליונה שבחי'<sup data-n=\"2324\">67</sup> עוה\"ב בקבול שכרם [ששם] נשמחה בו ממש (וא\"כ נתפרש [לצדיקים] לצ\"ע, ואמנם גם פי' הב' אמיתי דכוונת זריעה זו בשביל צ\"ת<sup data-n=\"2325\">68</sup> דהיינו כנז'<sup data-n=\"2326\">69</sup> למטה שנק' צ\"ת שהוא ענין ובחי' התקשרות דמקבל אל המשפיע בדביקות אמיתי <span data-k=\"pg\">תלא</span> ּ כידוע). וכתי' הלוך ילך ובכה<sup data-n=\"2327\">70</sup> נושא משך הזרע שהוא אור הזרוע לצ\"ע ואחר שלימות הבירורים שזהו הצמיחה והקצירה בא יבא ברנה נושא אלומותיו כי כלום אדם זורע קב<sup data-n=\"2328\">71</sup> אלא להוציא כמה כורין, וז\"ש [ו]לישרי לב שמחה [ו]כמ\"ש במ\"א עמ\"ש אז יאמרו בגוים<sup data-n=\"2329\">72</sup> הגדיל ה' לעשות עם אלה כו' (וזהו לצדיק בשביל צ\"ת שיהיו כנ\"י בבחי' צ\"ע בשלימות ההתקשרות והדביקות אהוי\"ר כו' וד\"ל. וזהו<sup data-n=\"2330\">73</sup> וצדיק יסוד עולם<sup data-n=\"2331\">74</sup> כמו [ה]יסוד שעליו נבנה הבנין שהוא עיקר קיומו שלא יפול לעולם כך התו\"מ [ו]אוי\"ר בצדיקי' בעוה\"ז הוא בחי'",[["2314","57","<b>אשריכם זורעי על כל מים</b>: ישעי' לב, כ."],["2315","58","<b>המצות שנק' צדקה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. לעיל פ' שמות יד, א. וש\"נ."],["2316","59","<b>החרישה דמרפי ארעא</b>: ראה מו\"ק ב, ב."],["2317","60","<b>כל</b>: הט: ליתא."],["2318","61","<b>(וכמבו\"ל</b>: ה: וד\"ל וכמבואר למעלה. ט: כו' וכמבואר למעלה."],["2319","62","<b>וזהו</b>: ט: נרשם כאן פ\"ג. פ\"ד נרשם להלן על יד הערה 73."],["2320","63","<b>בחי'</b>: הט: פי'."],["2321","64","<b>צדקות</b>: שם: צדיק."],["2322","65","<b>צ\"ע וקצירתו</b>: תוקן ע\"פ הט. ובתו\"ח כאן: הע'."],["2323","66","<b>[ו]לישרי לב</b>: המשך הכתוב אור זרוע לצדיק — תהלים צז, יא."],["2324","67","<b>שבחי'</b>: ט: שבחיי."],["2325","68","<b>צ\"ת</b>: הט: צדיק תחתון."],["2326","69","<b>כנז'</b>: שם: בשביל כ(ב)נ\"י."],["2327","70","<b>הלוך ילך ובכה</b>: תהלים קכו, ו."],["2328","71","<b>כלום אדם זורע קב</b>: ראה פסחים פז, ב. הנסמן לעיל פ' שמות מ, ג."],["2329","72","<b>אז יאמרו בגוים</b>: תהלים קכו, ב. ראה לעיל פ' שמות לז, א ואילך. מא, ב."],["2330","73","<b>וזהו</b>: ט: נרשם כאן פ\"ד. פ\"ג נרשם לעיל על יד הערה 62."],["2331","74","<b>וצדיק יסוד עולם</b>: משלי י, כה."]]],[2300550181,"היסוד [לעוה\"ב] שעליהם יהי' יסוד בנין העולם [הבא] וכמ\"ש לעולם ירשו ארץ שהוא אה\"ח דלעילא שהוא חלק ירושתו לעולם בבחי' נצחי' דעולם הא\"ס וד\"ל.\n(ג) <sup data-n=\"2332\">75</sup> <b>והנה</b> כתי' וצדיק באמונתו יחי'<sup data-n=\"2333\">76</sup> (שמזה א[מר] דתרי\"ג מצות<sup data-n=\"2334\">78</sup> בא חבקוק והעמידן על א[חת]<sup data-n=\"2335\">79</sup> וה[י]א האמונה שהיא כנ\"י שנק' אמונה [ד]איהו אמת ואיהי אמונה<sup data-n=\"2336\">77</sup> )<sup data-n=\"2337\">80</sup>, פי' כנ\"י שלמטה שנק' צדיקי' בתו\"מ [בפו\"מ] (והוא בחי' צ\"ת דבחי' מקבל כו') באמונתו יחי' דהיינו רק בתוקף עוז האמונה דכנ\"י בכלל ובפרט בכאו\"א מישראל, זאת האמונה ישים אל לבו ויאמין באמונה חזקה בעצמו' אוא\"ס ב\"ה שנק' חיי כל החיים<sup data-n=\"2338\">81</sup> העליו[ני'] כמ\"ש כי עמך מקו\"ח<sup data-n=\"2339\">82</sup> כו'<sup data-n=\"2340\">83</sup> העליוני', שהוא הנותן כח ועוז לבחי' כח הצומח שבארץ עילאה וארץ תתאה להוציא צמחה ותוליד תולדות רבים [כו' ו]היינו גם כל בחי' מזון וחיות האלקי לנשמות בגופים [ו]משם יצמיח ה' בתוס' ברכה וכל התפעלו' אוי\"ר שכליי' וגם טבעי' הנמשכת באדם למטה הכל הוא מכח ה' הניתן בכח הצומח שבאה\"ח שיבא בגילוי אור למטה בכנ\"י שנק' ארץ תתאה, והוא אשר הצמיח ה' אור האלקי' בלבו בל ימוט לעולם. ואז<sup data-n=\"2341\">84</sup> בא מכח עצמו שידמה בדמיונו שהוא העובד ביגיעת המוח והלב [עד שנתפעל] וממנו נמצאת<sup data-n=\"2342\">85</sup> תולדה זו שהרי חולפת ועוברת מיד כו', אלא תולדה זו היא באה מארץ עילאה מאור הזרוע לצ\"ע ונקלט במקבלים שנק' צ\"ת, וז\"ש וצדיק באמונתו יחי' שבאמונה זו דוקא שמאמין ב[שם] ה[וי]' שממנו יומשך לו אוי\"ר זו יחי' בה חיי עולם [בבחי' חיים] נצחי[ים] דא\"ס כו'. אבל אם אין אמונה זו חזקה בנפשו וד[ו]מה בנפשו שהוא [או]ה[ב ו]עובד את ה' מכחו דוקא [ו]כל עבודתו ומגמתו רק ש[י]הי' לו האהבה [בלבד] עד שיהי' בעונג<sup data-n=\"2343\">86</sup> כעובד ה' וימלא לבו רק מזה עצמו שנתפעל ולא יותר, זהו האות והסימן שלא נקלט בנפשו אור הזרוע [ל]צ\"ע [ב]ארץ עילאה וארץ תתאה בתוך תוכו כו' וע\"כ יצא האור הזה הנולד לחוץ ויפול הנופל שלא יחי' וימות וד\"ל.\n(ד) <sup data-n=\"2344\">87</sup> <b>וביאור</b> הענין הנה ידוע דבינה נק' אם הבנים<sup data-n=\"2345\">88</sup> שהם המולידי'<sup data-n=\"2346\">89</sup> אוי\"ר שנולד[ים] מן ההשגה ושכל באלקו' כמ\"ש כי אם לבינה תקרא<sup data-n=\"2347\">90</sup>, ויש בזה ב' מדריגות חיצוני' ופנימי', דהיינו כאשר ההשגה וההבנה בההתבוננו' הוא בחיצוני'",[["2332","75","<b>(ג)</b>: ראה לעיל הערה 62."],["2333","76","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["2334","78","<b>דתרי\"ג מצות</b>: ראה מכות כג, סע\"ב. הנסמן לעיל פ' בשלח קפט, ג."],["2335","79","<b>בא חבקוק והעמידן על א[חת]</b>: מכות כד, א."],["2336","77","<b>(שמזה. . אמונה)</b>: ה: שע\"ז. . אמונה."],["2337","80","<b>[ד]איהו אמת ואיהי אמונה</b>: ראה זהר בלק קצח, ב. מאמרי אדה\"א ויקרא ח\"א ס\"ע צג ואילך."],["2338","81","<b>חיי כל </b>[ט: ליתא]<b> החיים</b>: ראה יומא עא, א."],["2339","82","<b>כי עמך מקו\"ח</b>: תהלים לו, י."],["2340","83","<b>כו'</b>: הט: ליתא."],["2341","84","<b>וא\"ז</b>: ה: ואין זה. ט: ועי\"ז."],["2342","85","<b>נמצאת</b>: ה: יצא. ט: לא יצא. ראה הערה שלפנ\"ז."],["2343","86","<b>בעונג</b>: שם: בעיניו."],["2344","87","<b>(ד)</b>: ט: ה. ראה הערה 73."],["2345","88","<b>דבינה נק' אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. מאמרי אדה\"א נ\"ך ע' שיב. וש\"נ. שעה\"י קי, ב ובהערה 19."],["2346","89","<b>המולידי'</b>: הט: המדות."],["2347","90","<b>כי אם לבינה תקרא</b>: משלי ב, ג. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600547\" data-slug=\"or-hatorah-hb\" data-id=\"8316600547\">אוה\"ת משלי כרך א' ע' תקמז</a>."]]],[2300550213,"לבד דרך מעבר שלא נשרש<sup data-n=\"2348\">91</sup> ונקלט בעומק כלל רק במח' [ו]עומק שכלי כענין בחי' שמיעה מרחוק ה' נראה לי<sup data-n=\"2349\">92</sup> בהבנה [והשגה] לבד, אז מה שנולד התפעלו' המדות אוי\"ר <span data-k=\"pg\">864</span> ּ בלב מזה אין בהם חיות וקיום כלל ומיד חלפו ועברו כו'. והוא מה שכוונתו באהוי\"ר זו שממלא לבו במורגש לפי שעה לבד שאין בזה בחי' הביטול לאין האלקי כלל, כי עיקר האהבה הוא בחי' הביטול שבה לדבר האהוב שהוא [הדבקות בה' דוקא, ולא שיחפוץ באהבה ודביקות מצד עצמה ומצד כח עצמו שהוא יהי' מדובק ומקושר כנ\"ל. ומדריגה הנ\"ל<sup data-n=\"2350\">93</sup> הוא בחי' עומק בינה שבלב והוא] בחי' הקליטה שקולט האור [האלקי] בתוך תוכו כמו בהשגה בסוכ\"ע, שהוא שם ה' נתפס ונקלט האור כמ\"ש<sup data-n=\"2351\">94</sup> באמת שהוא הי' הוה ויהי' ולמעלה מההשתל'<sup data-n=\"2352\">95</sup> ואין בו שינוי כלל כמ\"ש אני ה' לא שניתי<sup data-n=\"2353\">96</sup>, וכה\"ג בהתבוננות בעצמות אוא\"ס [ב\"ה] ממש שלמעלה מסו\"מ [כידוע], הרי נקבע במוח הדעת כמו שהוא בבחי' ראי' עין השכל כאלו עיניו רואות בראי' חושית, [ו]כמו לע\"ל שא' כולם ידעו אותי<sup data-n=\"2354\">97</sup> ממש שיכירו במהו\"ע [ממש] כי נגלה כבוד ה'<sup data-n=\"2355\">98</sup> וראו כל בשר כו'. ואז ממילא גם האהבה הנולד בלב שנק' בשם ולד יש לו קיום נצחי שיהי' גם הוא בבחי' ביטול לאין האלקי בתמידות נק' בני אל חי<sup data-n=\"2356\">99</sup> ממש כמו בנים אתם לה'<sup data-n=\"2357\">100</sup> ממש כו', כבן שאהבתו לאביו בתמידות בלי פירוד [ל]עצמו כלל לומר שהוא האוהב כו' מאחר שבחי' עצמו הוא ממש. כמו שהנשמות הן בשרשם בתולדתם מאור העצמו' כמ\"ש<sup data-n=\"2358\">101</sup> כי אתה אבינו<sup data-n=\"2359\">102</sup> שהוא או\"א דאצי' שמהם נמשך שרש התולדה [דנשמות ממקור הראשון] שהוא פנימי' ועצמו' א\"ס ב\"ה ממש [כידוע] וד\"ל.\n(ה) <sup data-n=\"2360\">103</sup> <b>וזה</b>[ו] כל עיקר ענין העבודה עכשיו שיהי' גילוי אור דשם הוי' ממש כמו שהוא נקלט בתוך לבם ודעתם דכנ\"י בקביעות נצחי', אע\"פ שבק\"ש א[מר] ואהבת את ה' אלקיך<sup data-n=\"2361\">104</sup> אין זה עבודה כלל כי יכול להיות שמאיר אור האלקי [בנש\"י] שמתפעל באהוי\"ר לפי שעה כנ\"ל. אך שיהי' נקלט אור ותולדות<sup data-n=\"2362\">105</sup> אהוי\"ר נצחי' כל היום זהו בא ע\"י עבודה דוקא כמו ועבדתם את ה' אלקיכם<sup data-n=\"2363\">106</sup>, פי' עבודה זו הוא ע\"י הזריעה דתו\"מ בארץ שעי\"ז יהי' נקלט האור הזרוע לצ\"ע",[["2348","91","<b>נשרש</b>: ט: נתפס. ה: חסר."],["2349","92","<b>מרחוק ה' נראה לי</b>: ירמי' לא, ב."],["2350","93","<b>הנ\"ל</b>: ה: הב'."],["2351","94","<b>כמ\"ש</b>: ה: כמו שהוא."],["2352","95","<b>מההשתל'</b>: ט: מן ההשגה."],["2353","96","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["2354","97","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["2355","98","<b>כי נגלה כבוד ה'</b>: ישעי' מ, ה."],["2356","99","<b>בני אל חי</b>: הושע ב, א."],["2357","100","<b>בנים אתם לה'</b>: פ' ראה יד, א."],["2358","101","<b>מאור העצמו' כמ\"ש</b>: הט: מאו\"א העליונים כמו."],["2359","102","<b>כי אתה אבינו</b>: ישעי' סג, טז. ראה גם לקמן פ' תצוה שמו, ב. וש\"נ."],["2360","103","<b>(ה)</b>: ט: ו."],["2361","104","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה."],["2362","105","<b>אור ותולדות</b>: הט: האור ויוליד."],["2363","106","<b>ועבדתם את ה' אלקיכם</b>: משפטים כג, כה."]]],[2300550245,"באה\"ח כנ\"ל, ואז יהי' שם ה' ממש כמו שהוא למעלה מסו\"מ בבחי' אלקיכם [ממש] שיהי' שורה בתוך תוכם לאמיתי' שנק' אלקיכם דוקא. וזהו עיקר העבודה שבאמת לא שייך [לשון] עבודה כלפי מעלה שיתקן לדבר כי א\"צ לתיקון ושירות מאחר שנק' שלימותא דכולא<sup data-n=\"2364\">107</sup> כו', אלא העבודה הוא ש[יו]קלט אור אמיתי' עצמותו בכנ\"י<sup data-n=\"2365\">108</sup> עד שה'<sup data-n=\"2366\">109</sup> נק' בשם בנים בבחי' קיום נצחי (והרי מבחי' עבד נעשה [בחי'] בן וז\"ש במשיח ישכיל עבדי<sup data-n=\"2367\">110</sup> כו' ונק' בן כמ\"ש בני בכורי<sup data-n=\"2368\">111</sup> ישראל<sup data-n=\"2369\">112</sup> אתה אני היום ילדתיך<sup data-n=\"2370\">113</sup> כמשי\"ת).\n<b>וזהו</b> לא תהי' משכלה ועקרה בארצך פי' בארצך דוקא שהוא א\"י [שנק'] אה\"ח העליונה בב' מדרגות בארצות החיים כנ\"ל. והענין הוא דבחי' אור הזרוע לצ\"ע בארץ עילאה וארץ תתאה [הנ\"ל] שנק' ארציך שהן כנ\"י בחי'<sup data-n=\"2371\">114</sup> זריעה ד[אור] תו\"מ בארץ, הנה יהי' נקלט האור היטב בכנ\"י<sup data-n=\"2372\">115</sup> מלמעלמ\"ט בבחי' גילוי אלקות באמת לאמיתו בתוך תוכם<sup data-n=\"2373\">116</sup> פנימי' מוחם ולבם עד שבחי' התולד[ות] שלהם שהן אוי\"ר ומע\"ט יהי' בבחי' קיום נצחי שיחיו מחיי החיים כנ\"ל, וע\"ז א' לא תהי' משכלה ועקרה בארציך כו'. [כי] הנה ידוע שהמדות נק' בנים כו' ויש בזה ב' מדרגות בן ובת שזהו האהוי\"ר<sup data-n=\"2374\">117</sup>, האהבה היא <span data-k=\"pg\">תלב</span> ּ בחי' בן דכר כמו כי זכר<sup data-n=\"2375\">118</sup> חסדו<sup data-n=\"2376\">119</sup> כו' ונק' בן י\"ה וא[מר] בזהר דבן מסט' דאבא קאתי<sup data-n=\"2377\">120</sup> שהוא מ\"ש בנים אתם [להוי'] כו' וכמ\"ש כי אתה אבינו בדומה לאב[ינו] ממש, והיראה נק' בת שהוא בחי' מקבל, כמו הנקבה שהוא בחי' מקבל מבחי'<sup data-n=\"2378\">121</sup> הביטול בקעומ\"ש ביראה ופחד אלקי' שיש בכאו\"א שצריך לעורר ולהמשיך עליו תחלה להתפעלות האהבה ודביקות כמ\"ש זה השער לה'<sup data-n=\"2379\">122</sup> שהיראה נק' פתח ושער<sup data-n=\"2380\">123</sup> שבו יכנס תחלה, ואם אין יראה אין חכ'<sup data-n=\"2381\">124</sup>. וכל שהיראה יותר בעומק תחלה יהי' קיום יותר לתולדות אהבה ודביקות וכמ\"ש בת תחלה סימן יפה לבנים<sup data-n=\"2382\">125</sup> שנולדים אחרי[ה] (ומה שביעקב נאמר<sup data-n=\"2383\">126</sup> ואחר ילדה בת ושמה<sup data-n=\"2384\">127</sup> דינה<sup data-n=\"2385\">128</sup> זהו מלמעלמ\"ט דוקא דנוק' ובנות<sup data-n=\"2386\">130</sup> מן הדכר<sup data-n=\"2387\">129</sup> כו'). אך כ\"ז כאשר האוי\"ר באים בכח בחי' הקליטה דאור הזרוע הנ\"ל שנק' ולד של קיימא, אבל משכלה היא היולדת וקוברת<sup data-n=\"2388\">131</sup> שאין לולד קיום וחיות כלל וכלל שמיד שיולד ימות כו', זהו כמו אוי\"ר",[["2364","107","<b>שלימותא דכולא</b>: נסמן לקמן הערה 514."],["2365","108","<b>בכנ\"י</b>: הט: בנש\"י."],["2366","109","<b>עד שה'</b>: ה: עד שיהי'. ט: ע\"י שיהי'."],["2367","110","<b>במשיח ישכיל עבדי</b>: ישעי' נב, יג. ראה מאמרי אדה\"א ויקרא ח\"א ע' קיב. וש\"נ."],["2368","111","<b>בני בכורי ישראל</b>: שמות ד, כב."],["2369","112","<b>בכורי ישראל</b>: הט: ליתא."],["2370","113","<b>בני. . אתה אני היום ילדתיך</b>: תהלים ב, ז. ראה סוכה נב, א. לעיל פ' שמות א, ג. וש\"נ."],["2371","114","<b>בחי'</b>: הט: באי' ע\"י."],["2372","115","<b>היטב בכנ\"י</b>: הט: היינו בבחי' ישראל."],["2373","116","<b>תוכם</b>: שם: ליתא."],["2374","117","<b>בן ובת שזהו האהוי\"ר</b>: ראה תניא פט\"ז. מאמרי אדה\"ז שמות ח\"א ע' נג. וש\"נ."],["2375","118","<b>בן דכר </b>[ט: זכר]<b> כמו כי זכר חסדו</b>: ראה גם לעיל פ' שמות כו, א. וש\"נ."],["2376","119","<b>כי זכר חסדו</b>: תהלים צח, ג. א. ראה הנסמן לעיל פ' שמות לד, ג."],["2377","120","<b>דבן מסט' דאבא קאתי</b>: ראה זהר במדבר קכ, א. הנסמן לעיל פ' שמות לד, ב."],["2378","121","<b>מבחי'</b>: ה: והוא בחי'. ט: והוא."],["2379","122","<b>זה השער לה'</b>: תהלים קיח, כ."],["2380","123","<b>שהיראה נק' פתח ושער</b>: ראה זהר בהקדמה יא, ב. מאמרי אדה\"א בראשית ע' כט. וש\"נ."],["2381","124","<b>ואם אין יראה אין חכ'</b>: אבות פ\"ג, מי\"ז."],["2382","125","<b>בת תחלה סימן יפה לבנים</b>: ב\"ב קמא, א. ראה לקו\"ת ש\"ש סז, א."],["2383","126","<b>ומה שביעקב נאמר</b>: ראה גם לקלו\"י לזהר שמות מג, א."],["2384","127","<b>ואחר ילדה בת ושמה דינה</b>: ויצא ל, כא [ושם: ותקרא את שמה — ראה לקמן פ' פקודי תמד, א [ושם נדפס מגוכתי\"ק]. תנה, ג. מאמרי אדה\"א דברים ח\"ג ע' א'ט. וש\"נ. ש\"א לב, ב ובהערה 49]."],["2385","128","<b>ושמה דינה</b>: ה: ליתא."],["2386","130","<b>ובנות</b>: ה: נבנית ט: נובעת."],["2387","129","<b>דנוק'. . מן הדכר</b>: ראה ברכות ס, א. נדה לא, סע\"א."],["2388","131","<b>משכלה היא היולדת וקוברת</b>: ראה רש\"י כאן (כג, כו). תולדות כז, מה. מקץ מב, לו."]]],[2300550276,"שנולדים לפי שעה<sup data-n=\"2389\">132</sup> בחיצוני' השפע<sup data-n=\"2390\">133</sup> וההשגה כנ\"ל דאין בהם בחי' הביטול והתקשרות לאין האלקי בעומק כלל רק להיות אוהב ועובד ביראה<sup data-n=\"2391\">134</sup> ופחד<sup data-n=\"2392\">135</sup> ובזה ימלא חפצו כו' (כמ\"ש במ\"א ע\"פ לא יחפוץ כסיל בתבונה<sup data-n=\"2393\">136</sup> שהן בן ובת בפנימי' המוחין כ\"א בהתגלות לבו לבד כו'), שלא תוציא<sup data-n=\"2394\">137</sup> בידו למקום<sup data-n=\"2395\">138</sup> כלל, כי א\"ז<sup data-n=\"2396\">139</sup> רק דרך מעבר בעלמא<sup data-n=\"2397\">140</sup> בלתי קיום רק לפי שעה ע\"כ נק' משכלה שיולדת וקוברת. ועקרה היינו שאינה יולדת כלל כי לא יול[י]ד שום התפעלות אוי\"ר שיהי' למעשה אפי' לפי שעה, וכמו בזמן הגלות שכנ\"י נק' עקרה כו'. ואמנם בארציך שהיא אה\"ח דלעילא שאור הזרוע באה<sup data-n=\"2398\">141</sup> מבחי' פנימי' דעצמו' אוא\"ס בחו\"ב ומדות דאצי' לא תהי' משכלה ועקרה כלל וכמ\"ש שכול[ם] מתאימות ושכולה אין בהם<sup data-n=\"2399\">142</sup> וד\"ל.\n(וא\"ו) <sup data-n=\"2400\">143</sup> <b>והנה</b> י\"ל בבחי' [ה]עקרה שאינה יולדת כלל איך יתכן להיות מניעת התולדה אחר שאור זרוע לצ\"ע כנ\"ל, שא\"א לזרוע בארץ שלא תצמיח כלל כו'. אך הנה יש בעקרה ב' אופנים א' שקולטת הזרע ואינה פולטת ועכ\"ז אין לה הריון, דהגם [מ]אחר שקולטת [הרי] יש לה בית קיבול להריון אבל לא יצלח כלי בית קיבול שלה להזריע ולהוליד דכתי' אשה כי תזריע וילדה<sup data-n=\"2401\">144</sup> מפני שיש [בה] כח המוליד בזריעה כו', וזה העקרה שאין לה כח המוליד בזריעה אבל הזריעה<sup data-n=\"2402\">145</sup> עצמה לבד מקבלת כו'. והב' עקרה שאין לה בית קיבול להריון כלל כמש\"א עמ\"ש<sup data-n=\"2403\">146</sup> אין לה ולד אפי' בית ולד אין לה<sup data-n=\"2404\">147</sup> לפי שמקום ההריון מטומטם ונסת[ם] עד שאין בית קיבול לקבל ההריון. ויובן [ב'] מדרגות אלו בכנ\"י שנק' העקרה, הא' כאשר [האור] הזרוע לצ\"ע [שנמשך ל]הא[י]ר בנשמות יקלט היטב בכלי מוחם [ולבם] באמת [כמו] בהתפעלות אלקות בעומק לאמיתתו, ואז נק' כלי בית קיבול [עכ\"פ] לקבל אור האלקי העליון בתוך תוכ[ו] כנ\"ל, והוא מה<sup data-n=\"2405\">148</sup> שנק' כנ\"י בשם כוס ישועות<sup data-n=\"2406\">149</sup>, ככוס שמחזיק בתוכו היין, ונק' כוס של ברכה<sup data-n=\"2407\">150</sup> כאשר מתברך ונוסף בכפלי כפליים כו'. ואע\"פ<sup data-n=\"2408\">151</sup> גם שלא נוסף כלל רק<sup data-n=\"2409\">152</sup> מקבל היין המשמח שהוא אור האלקי שבהשגה עד שנקלט בלבו היטב נק' כוס, שיכול לקבל ישועות מבחי' <span data-k=\"pg\">866</span> ּ החסדי' העליונים, שאין בו רק<sup data-n=\"2410\">153</sup> ברכה בתוס' מרובה על העיקר (כדוגמא יו\"ד הדברות<sup data-n=\"2411\">154</sup> בקבלת התו' פב\"פ",[["2389","132","<b>אוי\"ר שנולדים לפי שעה</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010216\" data-slug=\"or-hatorah-hb\" data-id=\"8159010216\">אוה\"ת כאן ע' א'רסה</a>."],["2390","133","<b>השפע</b>: שם: השכל."],["2391","134","<b>אוהב. . ביראה</b>: ט: עובד באהבה ויראה."],["2392","135","<b>ופחד</b>: הט: ליתא."],["2393","136","<b>לא יחפוץ כסיל בתבונה</b>: משלי יח, ב. ראה מאמרי אדה\"א קונטרסים ע' סב ואילך. דברים ח\"א ע' ח. וש\"נ."],["2394","137","<b>תוציא</b>: הט: תצליח."],["2395","138","<b>למקום</b>: שם: לקיום."],["2396","139","<b>א\"ז</b>: שם: אין זה."],["2397","140","<b>בעלמא</b>: שם: ליתא."],["2398","141","<b>באה</b>: ט: בה בא."],["2399","142","<b>שכול[ם] מתאימות ושכולה אין בהם</b>: שה\"ש ד, ב. ו, ו."],["2400","143","<b>(וא\"ו)</b>: ט: (זיין). פ\"ח נרשם לקמן על יד הערה 164."],["2401","144","<b>אשה כי תזריע וילדה</b>: תזריע יב, ב."],["2402","145","<b>הזריעה</b>: הט: ליתא."],["2403","146","<b>כמש\"א עמ\"ש</b>: ט: וכמארז\"ל."],["2404","147","<b>אין לה ולד אפי' בית ולד אין לה</b>: נח יא, ל. יבמות סד, ב."],["2405","148","<b>מה</b>: הט: כמו."],["2406","149","<b>שנק' כנ\"י בשם כוס ישועות</b>: תהלים קטז, יג. ראה גם תו\"א כאן (עט, א). מאמרי אדה\"א בראשית ע' רפ."],["2407","150","<b>כנ\"י. . כוס של ברכה</b>: ראה גם תו\"א כאן."],["2408","151","<b>ואע\"פ</b>: ט: ועכ\"פ."],["2409","152","<b>רק</b>: ט: נק'."],["2410","153","<b>שאין בו רק</b>: הט: רק שאין (בו)."],["2411","154","<b>כדוגמא יו\"ד הדברות</b>: שם ודוגמא לדבר."]]],[2300550304,"שקבלו כנ\"י היטב רק שלא נולד מזה פירות שהן המצות באוי\"ר עד שבאו לא\"י דוקא). וכמו בגלות דכנ\"י נק' עקרה<sup data-n=\"2412\">155</sup> עד\"ז שהן בחי' כלי בית<sup data-n=\"2413\">156</sup> קיבול לקבל כל גילוי אוא\"ס [ב\"ה] שבחכ' דתו\"מ רק שלא יולד מזה תולדות דאוי\"ר במצות מעשיות שמוסיף אור למעלה בכפלי כפליים רק כמו שהן בלי תוס' ומגרעת כו' (ולע\"ל נק' בבחי' כוס של ברכה (וכמ\"ש כוסי רוי\"ה גימט' רכ\"א<sup data-n=\"2414\">157</sup> והוא כוס [של ברכה] דמשיח שמחזיק רכ\"א לוגין והוא בבחי' א\"א) וכמ\"ש במ\"א דכוס ישועות<sup data-n=\"2415\">158</sup> שיצמיח בתוס' מרובה לעשות פרי למעלה ולמטה<sup data-n=\"2416\">159</sup> כמ\"ש כי כארץ תוציא צמחה כן יצמיח ה' צדקה ותהלה בארץ<sup data-n=\"2417\">160</sup> כו' ולזה א' רני עקרה לא ילדה<sup data-n=\"2418\">161</sup> וכן א' [עד] עקרה ילדה שבעה<sup data-n=\"2419\">162</sup> (כמו שהאמהות עקרות היו נפקדות<sup data-n=\"2420\">163</sup> כמ\"ש במ\"א).\n<b>אבל</b><sup data-n=\"2421\">164</sup> מדרגה הב' הוא [ה]עקרה שאין בה בית קיבול להריון כלל כו', והיינו מה שאנו רואים בכ\"א בפרט שאף כלי<sup data-n=\"2422\">165</sup> בית קיבול בכלי מוחו ולבו להבין ולהשכיל ולהתפעל [כלל] מאור האלקי שבהשגה והבנה [ב]התבוננו' בממלא וסובב כו' עד שלא ירגיש כלל וכלל, הגם שמשיג בשכלו ונתפס במח' ונתאמת אצלו [מאד], מ\"מ לא נקלט הדבר אצלו כלל וכלל מפני שמוחו ולבו מטומטם ונסתם ביותר ואין לו חלל בית קיבול שנכנס בו ויוקלט האור (וזהו שנק' פולטת שאינה קולטת כלל ואינה נק' [כוס] כלל להכיל בחי' יין המשמח הנ\"ל<sup data-n=\"2423\">166</sup> ). וזהו מצד שנ[ת]טמטם המוח והלב מהרגשת עצמו ביותר [ומחזיק מקום לעצמו ביותר] ואינו בחי' כלי ריקן כלל, כי חוץ מעצמו לא ירגיש, להיות שאין בו בחי' הביטול והזזה ממקומו כלל כידוע, וידוע דכלי ריקן מחזיק הרבה וכלי מלא אינו מחזיק כלום. והוא מה שאנו רואים בטבע בנ\"א [כאלה] שכל עסקו ומגמתו בכל ימיו הוא רק שיתמלא רצונו במלואו דוקא באמרו בתמידות שכך הוא חפץ ורוצה וכך טוב לו ולא יוכל להזיז עצמו אפי' זיז כ\"ש<sup data-n=\"2424\">167</sup> להניח ולבטל רצונו רק שיהי' כרצונו דוקא, וכך נמשך לו בצרכי גופו וזה יוכל לעשות וזה אינו יכול לעשות [ב]שום אופן שכל אלה וכה\"ג הוראה על עצם מהותו שלא יוכל לזוז מעצמו. [ו]כך הוא בעבודת ה' אינו ניזוז ונתבטל ממקומו כלל וכלל גם אחר<sup data-n=\"2425\">168</sup> ההתבוננו' כלל<sup data-n=\"2426\">169</sup> כו' ואי[ן ל]ו בית קיבול כלל לקלוט רק [ב]דרך",[["2412","155","<b>בגלות דכנ\"י נק' עקרה</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תקו ואילך. דרושי חתונה ח\"א ע' שמה. הנחות תקע\"ז ע' שסה ואילך."],["2413","156","<b>בית</b>: שם: ליתא."],["2414","157","<b>כוסי רוי\"ה גימט' רכ\"א</b>: תהלים כג, ה. יומא עו, א. ראה גם לעיל פ' בשלח קנד, ד. וש\"נ."],["2415","158","<b>דכוס ישועות</b>: תהלים קטז, יג. ראה גם בענין כוס ישועות מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 18 ואילך. מאמרי אדה\"א בראשית ע' רפ ואילך."],["2416","159","<b>ולמטה</b>: הט: ליתא."],["2417","160","<b>כי כארץ. . יצמיח ה'. . בארץ </b>[הט: ליתא]: ישעי' סא, יא [ושם: כן אדני ה' יצמיח — ראה מאמרי אדה\"א דברים ח\"ג ע' תתצח. וש\"נ. הנחות תקע\"ז ע' שמ. ותיבת בארץ ליתא שם]."],["2418","161","<b>רני עקרה לא ילדה</b>: ישעי' נד, א."],["2419","162","<b>[עד] עקרה ילדה שבעה</b>: שמו\"א ב, ה."],["2420","163","<b>שהאמהות עקרות היו נפקדות </b>[הט: ונפקדו]: ראה ב\"ר פמ\"ה, ד. מאמרי אדה\"א דברים ח\"ד ע' א'תקי. וש\"נ. דרושי חתונה ח\"א ס\"ע רעז ואילך. ע' שדמ ואילך. לקמן ש, א."],["2421","164","<b>אבל</b>: ט: נרשם כאן פ\"ח. פ\"ט נרשם לקמן על יד הערה 186."],["2422","165","<b>שאף כלי</b>: הט: שאין לו."],["2423","166","<b>כלל. . הנ\"ל)</b>: שם: כלל). . הנ\"ל."],["2424","167","<b>זיז כ\"ש</b>: שם: הזזה כל שהוא."],["2425","168","<b>אחר</b>: שם: מכל."],["2426","169","<b>כלל</b>: שם: ליתא."]]],[2300550329,"מעבר בעלמא, דהיינו כמ\"ש [רז\"ל ש]אפי' בית ולד אין לה ועקרה כזו לא תוליד לעולם (ונגעי חולי רעה זאת נמצא' בכללות בקטן וגדול הערך בכל ציור קומה דכנ\"י מראש לרגל, והן ת\"ח יושבי אהלי תו[רה] והן העוסקי' במו\"מ שכאו\"א [לפי ערכו] יש בו מבחי' זו שהוא הישות והגסות [ו]ענין לגרמי', שגם בתו\"מ<sup data-n=\"2427\">170</sup> ותפלה אין כוונתו ורצונו לה' לבדו רק לעצמו ולגרמי' ולומר אני אני הוא [ו]למען שמי יכבד ה'<sup data-n=\"2428\">171</sup> כו'. וכ\"ש [בעסקו] במו\"מ שאו[מר] כחי ועוצם ידי<sup data-n=\"2429\">172</sup> כו' (בל\"א איך איך כו') [ו]בכל הפרטי העניני' מרגלא בפומי' [ל]שבח [ל]עצמו ולומר אני עושה וכך אני רוצה [וזה איני רוצה כו'], להיות שאין בו בחי' ביטול והזזה ממקומו כלל וכנ\"ל וע\"כ לא יוכל לקלוט אור האלקי' במוחו כמו שנתטמטם לגמרי כנ\"ל<sup data-n=\"2430\">173</sup>.\n<span data-k=\"pg\">תלג</span> ּ<b>(ז)</b><sup data-n=\"2431\">174</sup> והנה העצה היעוצה לזה הוא רק לעשות [בנפשו] בחי' כלי ריקן להיות בחי' כלי<sup data-n=\"2432\">175</sup> בית קיבול לקבל גילוי אור ה' בהתפעלו' והזזה ממקומו באמת. והנה יש בזה ב' אופנים, הא' מלמעלמ\"ט שע\"י תוקף גילוי אור חסד [ה]עליון באהבה [העליונה] נמשך בו בחי' הביטול והזזה [ממקומו] לעשות [בחי'] בית קיבול בחלל ריקן, או בבחי' יראה ופחד אלקי' שנופל על האדם כמו במ\"ת שנא' וירא העם<sup data-n=\"2433\">176</sup> וינועו<sup data-n=\"2434\">177</sup> ו[ב]אה\"ר שכפה עליהם ההר כגיגית<sup data-n=\"2435\">178</sup> (וכמו שהאשה כורתת ברית<sup data-n=\"2436\">179</sup> למי שעשאה כלי בית קיבול כו') כמ\"ש קול ה' יחולל אילות<sup data-n=\"2437\">181</sup> שנפתח כל[י] מוחם ולבם כו'<sup data-n=\"2438\">180</sup>. והאופן הב' בביטושי' גדולים שמבטשי' לגוף בבני חיי ומזוני [שעי\"ז] נעשה כלי ריקן בחלל שקוע במוחו ולבו שזהו בחי' לב נשבר ונדכה באמת, כעני ואביון שלבו נשבר בקרבו, שע\"ז א[מר] זבחי אלקי' רוח נשברה<sup data-n=\"2439\">182</sup> וא[מר] את מי אשכון<sup data-n=\"2440\">183</sup> את דכא ושפל רוח, והוא נמשך על האדם לטובתו כמ\"ש תשב אנוש עד דכא<sup data-n=\"2441\">184</sup> ותאמר שובו כו' והוא מ\"ש בזהר דכד מבטשין לגוף<sup data-n=\"2442\">185</sup> סליק נהורא דנשמתא להיות בחי' כלי קיבול לקלוט כו' וד\"ל. ואע\"פ<sup data-n=\"2443\">186</sup> שהביטוש הוא בחיצוני' הגוף נעשה עי\"ז בחי' כלי [קיבול] לקבל גילוי אור אלקי, לפי שזהו כמו משל העושה כלי מן העץ להיות ב[ו] חלל [ו]בית קיבול שצריך תחלה להכות בפטיש [סביב] העץ הגולמ[י] עד שיכול להיות חלל בתוכו. וכך הוא הביטוש לגוף להיות בבחי' לב נשבר ונדכה ונבזה בעיניו נמאס ושפל רוח באמת לפני כ\"א<sup data-n=\"2444\">187</sup> עד שנפשו כעפר לכל ואינו תופס מקום כלל כאלו אינו במציאות דבר מה, ואז יהי' כלי מוחו ולבו בית [קיבל] חלל לקבל כל בחי' גילוי אור",[["2427","170","<b>בתו\"מ</b>: שם: בעסקו בתורה."],["2428","171","<b>[ו]למען שמי יכבד ה'</b>: ישעי' סו, ה."],["2429","172","<b>כחי ועוצם ידי</b>: עקב ח, יז."],["2430","173","<b>כנ\"ל</b>: כנצ\"ל: כנ\"ל)."],["2431","174","<b>(ז)</b>: ט: ליתא. ראה לעיל הערה 143."],["2432","175","<b>בחי' כלי</b>: הט: ליתא."],["2433","176","<b>וירא העם וינועו</b>: יתרו כ, טו."],["2434","177","<b>וינועו</b>: ה: ניתוסף: ויעמדו מרחוק. ט: נתוסף: כו'."],["2435","178","<b>שכפה עליהם ההר כגיגית </b>[הט: כו']: שבת פח, א. ראה גם לקמן פ' ויקהל תכה, ב. מאמרי אדה\"א בראשית ע' חצר. וש\"נ. ש\"א ב, ב ובהערה 33."],["2436","179","<b>שהאשה כורתת ברית</b>: סנהדרין כב, ב."],["2437","181","<b>קול ה' יחולל אילות</b>: תהלים כט, ט."],["2438","180","<b>כו'). . כו'</b>: ט: כו'. . כו')."],["2439","182","<b>זבחי אלקי' רוח נשברה</b>: תהלים נא, יט."],["2440","183","<b>את מי אשכון</b>: ישעי' נז, טו [ושם: אשכון ואת דכא — ראה לעיל פ' וארא פג, ב. וש\"נ]."],["2441","184","<b>תשב אנוש עד דכא</b>: תהלים צ, ג."],["2442","185","<b>דכד מבטשין לגוף</b>: ראה זהר שלח קסח, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט</a>."],["2443","186","<b>ואע\"פ</b>: ט: נרשם כאן פ\"ט. פ\"ח נרשם על יד הערה 164."],["2444","187","<b>כ\"א</b>: הט: כל (ה)אדם."]]],[2300550354,"האלקי'<sup data-n=\"2445\">188</sup> להיות ב[ו] בחי' הזזה מעצמותו כנ\"ל, עד שנק' כוס בחלל גדול לקבל הרבה וכמו ולבי חלל בקרבי<sup data-n=\"2446\">189</sup> עד שיכול להיות בבחי' כוס של ברכה [שזה בחי' פקידת העקרה כו')].\n(ח) <sup data-n=\"2447\">190</sup> <b>והנה</b> הגם אחר<sup data-n=\"2448\">191</sup> שכבר נעשה בחי' כלי בית קיבול כנ\"ל עד שנק' כוס, הנה ארז\"ל כוס של ברכה<sup data-n=\"2449\">192</sup> צריך הדחה מבפנים ושטיפה מבחוץ כו'. והענין הוא כי הגם ש[כבר] נעשה [בחי'] כלי בית קיבול בחלל ריקן ע\"י שנשבר לבו באמת כעני מדוכא בנפשו כעפר ממש לבלתי יוכל להרים ראש כלל ועי\"ז גם מבפנים נעשה<sup data-n=\"2450\">193</sup> נפשו ולבו ורוחו רוח נמוכה לבא לבחי' הזזה וביטול [מ]עצמ[ו] לקבל גילוי<sup data-n=\"2451\">194</sup> אור האלקי בתוך תוכ[ו] עד שנק' כוס, הנה עוד צריך שיהי' הכוס [הזה] נקי מכל לכלוך טומאה וזוהמא לגמרי כמו עד\"מ הכוס הגשמי שא\"א להטיל בו יין אם אינו נקי ומורחץ היטב<sup data-n=\"2452\">195</sup> מבפנים בכ\"א<sup data-n=\"2453\">196</sup> שז\"ש כוס של ברכה צריך הדחה ושפשוף מבפנים שלא יקלקל היין [ש]בתוכו ואינו ראוי להיות כוס של ברכה. וכך הוא בנשמת האדם בפרט ובכלל בכנ\"י שנק' כוס צריך שיורחץ הכוס ויודחה היטב מבפנים, והיינו שלא יהי' אדם מקשר נפשו בהבלי תענוגי עוה\"ז ואפי' בצרכי גופו [ה]הכרחי' שהן דברים המותרים כאכילה ושתי' ומשגל כו' ולבושי' ופרנסתו שלא יהי' להוט אחריהם בלב ונפש ביותר מכפי המדה, אע\"פ שא\"א לאדם להיות<sup data-n=\"2454\">197</sup> בלעדם אבל יהיו מעשיהם בקרירות ובכפיי' בע\"כ ע\"פ הכרח גדול ולא לנחת ולמלא רצונו ותאוותו אחר שלבו נשבר ונדכה באמת מבחוץ ומבפנים לא יתערב דבר [זר] בלבו בהתקשרות בכל לבו ממש גם בגשמיות עוה\"ז. וזהו כמו הלכלוך והמיאוס בתוך הכוס שיקלקל היין כך ילכלך<sup data-n=\"2455\">198</sup> הלכלוך וטומא[ת] התאוות הזרות ליין המשמח שהוא גילוי <span data-k=\"pg\">868</span> ּ אור דהשגה אלקי' שנקלט במוחו ולבו וכמ\"ש כי קצר המצע<sup data-n=\"2456\">199</sup> כו', וכתיב מי יעלה בהר ה'<sup data-n=\"2457\">200</sup> נקי כפים ובר לבב<sup data-n=\"2458\">201</sup> ממש שלא נשא לשוא נפשו ורצונו כלל הוא ישא ויקבל ברכה מאת ה'<sup data-n=\"2459\">202</sup> שיתגלה בנפשו וצדקה מאלקי ישעו שהם הפירות הנוספים בכפלי כפליים להיות נק' כוס של ברכה לע\"ל (ואע\"פ שנק' עקרה בזמן הגלות). וכמ\"כ במשל הנ\"ל שכנ\"י נק' אשה עקרה גם אם יש לה בית ולד כו', אך אם לא נטהרה מטומאתה שהרי<sup data-n=\"2460\">203</sup> ה' דמים טמאים<sup data-n=\"2461\">204</sup> שנובעים ממקורה עד שתטהרה בספי' ז' נקיים שתנקה לגמרי לא תהא ראוי' ליחו\"ע שיוקלט בה אור הזרוע לצ\"ע וכ\"ש שלא תוליד לע\"ל כו' וד\"ל.",[["2445","188","<b>אור האלקי'</b>: שם: אלקות."],["2446","189","<b>ולבי חלל בקרבי</b>: תהלים קט, כב."],["2447","190","<b>(ח)</b>: ט: ליתא. ראה לעיל הערה 164."],["2448","191","<b>אחר</b>: הט: ליתא."],["2449","192","<b>כוס של ברכה</b>: ראה ברכות נא, א."],["2450","193","<b>נעשה</b>: הט: ליתא."],["2451","194","<b>גילוי</b>: שם: ליתא."],["2452","195","<b>היטב</b>: ה: יפה."],["2453","196","<b>בכ\"א</b>: ה: בכל חללו. ט: ליתא."],["2454","197","<b>להיות</b>: שם: לחיות."],["2455","198","<b>ילכלך</b>: שם: יקלקלו."],["2456","199","<b>כי קצר המצע</b>: ישעי' כח, כ."],["2457","200","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["2458","201","<b>נקי כפים ובר לבב</b>: שם כד, ד."],["2459","202","<b>ישא. . ברכה מאת ה'</b>: תהלים שם, ה."],["2460","203","<b>שהרי</b>: הט: שהן."],["2461","204","<b>ה' דמים טמאים</b>: נדה יט, א."]]],[2300550374,"(ט) <sup data-n=\"2462\">205</sup> <b>והנה</b> עדיין י\"ל למה נק' כנ\"י בשם כוס של ברכה או בשם עקרה [שתוליד] לע\"ל כמ\"ש רני עקרה לא [י]לדה כו' וכמשארז\"ל עתידה אשה שתלד בכל יום<sup data-n=\"2463\">206</sup> כו') איך אפשר שעקרה תוליד, אחר שאין בה כח התולדה כלל כנ\"ל. וגם אם תטהר מטומאתה לגמרי כנ\"ל ונעשה בחי' כלי קיבול בנקיות וטהרה ובבחי' קולטת ממש כנ\"ל, מ\"מ הרי אין בטבעה להוליד ולד מזרעה כנ\"ל. אך [הנה] צריך להקדים תחלה ב[ענין] תפילת חנה (שהוא בחי' ס\"ג דבינה<sup data-n=\"2464\">207</sup> עילאה) שא' והיא מרת נפש ותתפלל חנה<sup data-n=\"2465\">208</sup> על ה' ובכה תבכה כו' מהו על ה' ובכה תבכה דוקא מה יועיל הבכי' כנ\"ל<sup data-n=\"2466\">209</sup>, להיות ידוע שיש ב' מדרגות בסט'<sup data-n=\"2467\">210</sup>, הא' כשהיא נק' אם הבנים והוא בזמן בהמ\"ק שהוא בחי' לאה שילדה ששה בנים<sup data-n=\"2468\">211</sup> שהן ו' מדות דאצי' והן מקורים לס\"ר נש\"י<sup data-n=\"2469\">212</sup> וענפים שלהם הנוספי' כו'. ו[הב'] כמו בזמן הגלות [שכנ\"י נק' עקרה שאינה יולדת כלל, והיא בחי' חנה שאמר ויהי לפנינה ילדים<sup data-n=\"2470\">213</sup> ולחנה אין ילדים כו'<sup data-n=\"2471\">214</sup>. והענין הוא כידוע דכנ\"י שהיא בחי' המל'<sup data-n=\"2472\">215</sup> יש לה כמה שמות וכינויים לפי אופן מדרגתה לפי אותו הזמן, שאם היא בבחי' התולדה נק' לאה שנק' אם הבנים שנולדו המדות דאהוי\"ר כו', וכשהיא בבחי' עקרה נק' חנה שאין לה ילדים וכמו בזמן הגלות] כו'. אך גם בהיותה בבחי' עקרה שאינה יולדת כלום עכ\"ז ע\"י התפלה שהוא תפלת חנה נענית ונפקדת, והיינו ג\"כ בזמן הגלות שנק' עקרה בתפלה זאת דחנה יופקדה להיות בבחי' התולדה להקריב<sup data-n=\"2473\">216</sup> אם הבנים וכמ\"ש עד עקרה ילדה שבעה כו'. וי\"ל תחלה בגוף הענין בתפלת חנה במ\"ש והיא מרת נפש ותתפלל על ה' דוקא (ועלי חשבה לשכורה<sup data-n=\"2474\">217</sup> שהוא כשכנ\"י בגלות<sup data-n=\"2475\">218</sup> ). דהנה ידוע בפי' שם ה[וי]' ע\"ש שהוא ית' מהוה<sup data-n=\"2476\">219</sup> את הכל מאין ליש, ולא שהשפע בא מעצם אור דשם הוי' אלא רק מזיו ואור שלו אשר מ[ת]צמצם בבחי' שם אלקי' כמ\"ש כי שמש ומגן ה[וי]' אלקי'<sup data-n=\"2477\">220</sup> כידוע, ואמנם גם כללות מקור של ד' עולמות דאבי\"ע הם ד' אותיות דשם הוי' יו\"ד באצי' שהוא החכ' בכלל וה\"א בבריאה<sup data-n=\"2478\">221</sup> שהוא בבינה וי\"ו ביצי' וה\"א בעשי' כידוע, וע\"כ אע\"פ שאין קדוש כה'<sup data-n=\"2479\">222</sup> מ\"מ מתפשט אור דשם ה' גם בעולמות דבי\"ע גם בסוף",[["2462","205","<b>(ט)</b>: ט: יו\"ד. ראה לעיל הערה 186."],["2463","206","<b>עתידה אשה שתלד בכל יום</b>: שבת ל, ב."],["2464","207","<b>חנה. . ס\"ג דבינה</b>: ראה ע\"ח (שער מוחין דקטנות) שכ\"ב, פ\"ב. מאמרי אדה\"א דברים ח\"ד ע' א'תצד. וש\"נ."],["2465","208","<b>והיא מרת נפש ותתפלל חנה</b>: שמו\"א א, י [ותיבת חנה ליתא שם וכן ליתא בהט — ראה לקמן רצט, ד. פ' ויקהל תז, ד. מאמרי אדה\"א ויקרא ח\"א ע' צב. וש\"נ. דברים ח\"ג ע' א'צה. וש\"נ]."],["2466","209","<b>כנ\"ל</b>: הט: כו'."],["2467","210","<b>בסט'</b>: שם: בכנ\"י."],["2468","211","<b>לאה שילדה ששה בנים</b>: ויצא ל, כ. ראה גם לעיל פ' שמות יח, א. וש\"נ."],["2469","212","<b>לס\"ר נש\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא</a> פל\"ז. לעיל פ' בשלח קפג, ג. וש\"נ."],["2470","213","<b>ויהי לפנינה ילדים</b>: שמו\"א א, ב."],["2471","214","<b>כו'</b>: כ\"ה בהכת\"י."],["2472","215","<b>דכנ\"י. . המל'</b>: ראה זהר בלק קצז, א."],["2473","216","<b>להקריב</b>: הט: להקר(א)ות."],["2474","217","<b>ועלי חשבה לשכורה</b>: שמו\"א א, יג."],["2475","218","<b>לשכורה. . כשכנ\"י בגלות</b>: ראה גם ישעי' נא, כא. מאמרי אדה\"א דברים ח\"ב ע' תקכ. וש\"נ. נ\"ך ע' רג. וש\"נ. קונטרסים ע' לט."],["2476","219","<b>ה[וי]'. . מהוה</b>: ראה זהר (רע\"מ) פינחס רנז, סע\"ב. לעיל קנ, א. וש\"נ."],["2477","220","<b>כי שמש ומגן ה[וי]' אלקי'</b>: תהלים פד, יב. ראה שער היחוה\"א רפ\"ו. לעיל פ' שמות לד, ד. וש\"נ."],["2478","221","<b>יו\"ד באצי'. . וה\"א בבריאה</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"א. לעיל פ' שמות כד, ד הערה 62."],["2479","222","<b>שאין קדוש כה'</b>: שמו\"א ב, ב."]]],[2300550393,"עולם העשי' כמו בפנימי' הכתר וחכ'<sup data-n=\"2480\">223</sup> דאצי' שהרי א' קדוש ה' צבאות מכה\"כ<sup data-n=\"2481\">224</sup> וכתי' והארץ האירה מכבודו<sup data-n=\"2482\">225</sup> ולע\"ל כתי' ונגלה כבוד ה'<sup data-n=\"2483\">226</sup> [כו' וד\"ל].\n<b>והנה</b><sup data-n=\"2484\">227</sup> גם מציאת התפשטו' אור וזיו דשם ה' אינו נמשך למטה רק בבחי' קריאת שם בלבד שהוא לגבי העול[מות] שמקבלים מאור וזיו שלו לבד, עד שהכל יכולים להקרות<sup data-n=\"2485\">228</sup> בשם זה דה' כמו הללו את ה' מן הארץ<sup data-n=\"2486\">229</sup> כו' עד יהללו את שם ה'<sup data-n=\"2487\">230</sup> כי נשגב שמו לבדו וכן הריעו לה' כל הארץ<sup data-n=\"2488\">231</sup> וגם ע' אוה\"ע<sup data-n=\"2489\">232</sup> דכתי' הללו את ה' כל גוים<sup data-n=\"2490\">233</sup> כו'. אבל בחי' עצמו' דשם ה' זה כמו שהוא מורה על בחי' עצמיות א\"ס ממש שנק' שם העצם<sup data-n=\"2491\">234</sup> <span data-k=\"pg\">תלד</span> ּ שאין זה ע\"ש שמהוה את הכל ע\"י צמצום דשם אלקי' רק כמו שהוא בעצמו כך שמו, והוא ענין הי' הוה ויהי'<sup data-n=\"2492\">235</sup> שלמעלה מכל ההשתל' דד' עולמות דאבי\"ע כידוע. ולא שייך לומר ע\"ש [ענין] התהוות דבר מה דודאי כל העולמות דאבי\"ע<sup data-n=\"2493\">236</sup> קמי' ממש כל\"ח ואינם תופסים מקום כלל וכלל, גם עולם הנאצלי' בשם ה' יו\"ד חכ' [כו'] אינו רק בחי' התפשטו' גילוי אור בעלמא מבחי' העלם העצמי ממש וכמ\"ש בס\"י ע\"ס בלי מה בלי מהות<sup data-n=\"2494\">237</sup> כו', וז\"ש אני ה' לא שניתי דקאי על שם העצם שלמעלה מהיות גם בחי' מקור להתהוות העולמות שאין בו שום שינוי כלל מקודם שהאציל וברא ויצר ועשה לאחר שהאציל וברא כו'. והוא מ\"ש בפרקי ר\"א שקודם [שנ]ברה\"ע הי' הוא ושמו בלבד<sup data-n=\"2495\">238</sup> והיינו גם קודם שהאציל<sup data-n=\"2496\">239</sup> [כו' פי'] הוא ושמו היינו שמו העצמי שאנו או' אתה קדוש<sup data-n=\"2497\">240</sup> ושמך קדוש כו' ואע\"פ שאין שם בחי' אותיות יו\"ד כו', אך מקור הד' אותיות הללו הוא שמורה על העצמו' הנעלם, וז\"ש בי\"ג מדה\"ר ויקרא ה' ה'<sup data-n=\"2498\">241</sup> מן ההעלם דה' לגילוי כו' כמ\"ש במ\"א. וע\"ז א' הוא ושמו בלבד (כמשי\"ת) בעצמו'<sup data-n=\"2499\">242</sup> נק' יחיד לבדו קודם הצמצום הראשון (שהי' ממלא כל מקום החלל<sup data-n=\"2500\">243</sup> כו' ומקו\"פ כו' וכמ\"ש בע\"ח<sup data-n=\"2501\">244</sup> כו'), כך שמו שם ה' שבעצמו לבד<sup data-n=\"2502\">245</sup> מיוחד בעצמותו ממש כשם האדם שכלול בעצמו כך<sup data-n=\"2503\">246</sup> לא יצטרך לקרוא<sup data-n=\"2504\">247</sup> בשמו, דמה שקוראי' בשמו הוא רק להפנות לזולתו ממש. וכך שם ה' ע\"ש שמהוה",[["2480","223","<b>וחכ'</b>: ה: וח\"ס."],["2481","224","<b>קדוש. . מכה\"כ</b>: ישעי' ו, ג."],["2482","225","<b>והארץ האירה מכבודו</b>: יחזקאל מג, ב."],["2483","226","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["2484","227","<b>והנה</b>: ט: נרשם כאן פי\"א."],["2485","228","<b>להקרות</b>: הט: לקרותו."],["2486","229","<b>הללו את ה' מן הארץ</b>: תהלים קמז, ז."],["2487","230","<b>יהללו את שם ה'</b>: תהלים שם, יג."],["2488","231","<b>הריעו לה' כל הארץ</b>: תהלים ק, א."],["2489","232","<b>ע' אוה\"ע</b>: סוכה נה, ב."],["2490","233","<b>הללו את ה' כל גוים</b>: תהלים קיז, א."],["2491","234","<b>ה'. . שם העצם</b>: ראה כ\"מ לרמב\"ם הל' ע\"ז פ\"ב, ה\"ז. פרדס (שער שם בן ד) שי\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תכו."],["2492","235","<b>ה'. . הי' הוה ויהי'</b>: נסמן לעיל פ' יתרו רעא, ב."],["2493","236","<b>דאבי\"ע</b>: הט: דבי\"ע."],["2494","237","<b>ע\"ס. . בלי מהות</b>: ראה ס\"י פ\"א, מ\"ב ובמפרשים שם."],["2495","238","<b>שקודם [שנ]ברה\"ע. . בלבד</b>: ראה פדר\"א פ\"ג. לעיל פ' וארא נג, ב. וש\"נ."],["2496","239","<b>קודם שהאציל</b>: ראה עבודת הקדש לר\"מ גבאי חלק היחוד פ\"ב."],["2497","240","<b>שאנו או' אתה קדוש</b>: בשמו\"ע."],["2498","241","<b>ויקרא ה' ה'</b>: תשא לד, ו. ראה לעיל פ' בשלח קמט, ד. וש\"נ."],["2499","242","<b>(כמשי\"ת) בעצמו'</b>: ה: כמו שהוא ית' בעצמו. ט: כמו שהוא ממש בעצמותו."],["2500","243","<b>קודם הצמצום. . ממלא. . החלל</b>: ראה גם לעיל פ' יתרו רסב, א. וש\"נ."],["2501","244","<b>ממלא. . בע\"ח</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["2502","245","<b>שבעצמו לבד</b>: הט: שבעצמו' לבדו."],["2503","246","<b>כך</b>: שם: כאשר."],["2504","247","<b>לקרוא</b>: שם: לקריאה לקרות."]]],[2300550410,"ומחי' אינו רק לבחי'<sup data-n=\"2505\">248</sup> השתלשלו' העולמות כו' אבל עצמו' שמו נשגב לבדו ואינו בא גם בבחי' מקור למקור לעולמות אלא נשגב לבדו (כמשי\"ת<sup data-n=\"2506\">249</sup> ) בעצמו לבדו וז\"ש הוא ושמו בלבד כו'<sup data-n=\"2507\">250</sup>.\n(יו\"ד) <sup data-n=\"2508\">251</sup> <b>וזהו</b> כי נשגב שמו לבדו הודו על ארץ ושמים כו', פי' שמו שם ה'<sup data-n=\"2509\">252</sup> היינו שם ה' שכולם יהללו את שם ה' אך עצמו' שם ה' נשגב לבדו ממש כו' שהי' הוא ושמו בלבד וכתי' אני ה' לא שניתי כלל, וגם [עתה] אחר ההשתלשלו' הוא ושמו בלבד כמו שהוא<sup data-n=\"2510\">253</sup> קודם ההשתל' ממש בשוה וכמ\"ש כי נשגב שמו לבדו<sup data-n=\"2511\">254</sup> ורק הודו על ארץ ושמים כו'<sup data-n=\"2512\">255</sup>. ואמנם לישראל עם קרובו הרים קרן<sup data-n=\"2513\">256</sup> שקרבן לעצמו' שם ה' ע\"י תו\"מ שהן בפנימי' דשם ה' העצמי כשנק' תו' ה' מצות ה' כו', והיינו במ\"ת שהאיר<sup data-n=\"2514\">257</sup> שפב\"פ האיר פניו עליהם באו\"פ דה' באנכי<sup data-n=\"2515\">258</sup> ה' אלקיך<sup data-n=\"2516\">259</sup> דוקא כי<sup data-n=\"2517\">260</sup> כדי שיוכלו ביחודי'<sup data-n=\"2518\">261</sup> העצמי' שהוא יחיד לבדו ממש ולהיות קרובי' אליו בעצמו ממש עד שמחמת תו\"מ שיעשו ימשיכו מפנימי' אור דשם ה' בכלל<sup data-n=\"2519\">262</sup> העולמות גם בעולם האצי' כו', כידוע שע\"י המצות מוסיפי' אור<sup data-n=\"2520\">263</sup> חכ'<sup data-n=\"2521\">264</sup> מן העצמו' גם בע\"ס דאצי' באו\"כ כו' וד\"ל. והוא מה שאנו מוצאים בחי' התקשרות אה\"ר<sup data-n=\"2522\">265</sup> העצמיות מן העצמו' דאהבה<sup data-n=\"2523\">266</sup> לישראל כמ\"ש אה\"ר אהבתנו<sup data-n=\"2524\">267</sup> חמלה גדולה ויתירה חמלת [עלינו] כו' להיותם עם קרוב[ו] בפנימי' [ו]עצמיות, וכמ\"כ מכנ\"י להקב\"ה מה שיכול כאו\"א מישראל להשליך נפשו מנגד ולמס\"נ על קדה\"ש כמו אליך ה' נפשי אשא<sup data-n=\"2525\">268</sup> אליך ממש, וכן בהתלהבות ודביקות בתפלה שתצא הנפש ותכלה כמו צמאה לך נפשי כמה לך כו'<sup data-n=\"2526\">269</sup> שיש בכאו\"א [מישראל], וכן בדביקות והתקשרות במדותיו ית' [בתו\"מ] ובמחדו\"מ שזהו נק' אתדבקות רוחא ברוחא<sup data-n=\"2527\">270</sup> ממש ומחשבתו ודבורו ומעשיו יהיו מקושרים רק לה' לבדו בתו\"מ<sup data-n=\"2528\">271</sup> שהן מחדו\"מ <span data-k=\"pg\">870</span> ּ של הקב\"ה מעומקא דלבא בדביקה וחשיקה וכמו ונשמח בד\"ת<sup data-n=\"2529\">272</sup> וכידוע במ\"ש בזהר ע\"פ נפשי אויתיך בלילה<sup data-n=\"2530\">273</sup> בגלותא אף רוחי כו' וד\"ל.\n(יא) <sup data-n=\"2531\">274</sup> <b>וזהו</b> ותתפלל חנה על ה' למעלה משם ה' והל\"ל אל ה' מאחר שאל ה' נשאה נפשה בתפלתה כמו ולפני ה' ישפוך שיחו<sup data-n=\"2532\">275</sup> מאחר שהיתה מרת נפש. אך הענין הוא דאדרבה היא הנותנת משום דהיא מרת נפש ע\"כ אמר על ה', להיות",[["2505","248","<b>לבחי'</b>: שם: לגבי."],["2506","249","<b>(כמשי\"ת)</b>: שם: כמו שהוא ית'."],["2507","250","<b>כו'</b>: שם: וד\"ל."],["2508","251","<b>(יו\"ד)</b>: ט: יב. ראה לעיל הערה 227."],["2509","252","<b>שם ה'</b>: הט: ליתא."],["2510","253","<b>שהוא</b>: שם: ליתא."],["2511","254","<b>לבדו</b>: שם: ליתא."],["2512","255","<b>ושמים כו'</b>: הט: כו'. בתו\"ח ניתוסף כאן התיבות שבריש פרק זה: פי' שמו. . הוא ושמו. ואח\"כ באים התיבות: רק הודו על ארץ ושמים."],["2513","256","<b>לישראל עם קרובו הרים קרן</b>: תהלים קמח, יד."],["2514","257","<b>שהאיר</b>: הט: ליתא."],["2515","258","<b>באו\"פ דה' באנכי</b>: שם: בעצמות ופנימיות דשם הוי' באמרו אנכי."],["2516","259","<b>באנכי ה' אלקיך</b>: יתרו כ, ב."],["2517","260","<b>כי</b>: ה: ליתא. ט: כו'."],["2518","261","<b>שיוכלו ביחודי'</b>: הט: שיוכללו ביחודו."],["2519","262","<b>בכלל</b>: הט: בכל."],["2520","263","<b>שע\"י המצות מוסיפי' אור חדש</b>: ראה פע\"ח בהקדמה. לעיל פ' בשלח קנו, ב. וש\"נ."],["2521","264","<b>חכ'</b>: הט: חדש."],["2522","265","<b>אה\"ר</b>: שם: ליתא."],["2523","266","<b>דאהבה</b>: דאא\"ס ב\"ה."],["2524","267","<b>אה\"ר </b>[ט: אה\"ע]<b> אהבתנו</b>: ברכת ק\"ש שחרית (נוסח אשכנז)."],["2525","268","<b>אליך ה' נפשי אשא</b>: תהלים כה, א (פו, ד)."],["2526","269","<b>צמאה לך נפשי. . כו' </b>[הט: בשרי]: תהלים סג, ב."],["2527","270","<b>אתדבקות רוחא ברוחא</b>: ראה זהר משפטים קכד, ב."],["2528","271","<b>בתו\"מ</b>: הט: ליתא."],["2529","272","<b>ונשמח בד\"ת </b>[ט: בדברי תורתך]: ברכת ק\"ש דערבית."],["2530","273","<b>נפשי אויתיך בלילה</b>: ישעי' כו, ט. ראה זהר אחרי סז, רע\"ב. סידור שער החנוכה רעט, ג. ש\"א כט, א ואילך."],["2531","274","<b>(יא)</b>: ט: יג. ראה לעיל הערה 251."],["2532","275","<b>ולפני ה' ישפוך שיחו</b>: תהלים קב, א."]]],[2300550427,"דתפלה זו למעלה מכל תפלה שהוא בחי' התקשרות ודביקות באה\"ר בשם ה' המהווה את כל העולמות שאין זה רק ע\"פ הכנה רבה דהשגה וקליטה במוח ולב כו' דרוח אייתי רוח<sup data-n=\"2533\">276</sup> כו' ואמשיך [רוח] רק כפי אופן ההעלאה לבד. אבל תפלת חנה שהיא היתה מרת נפש בבחי' שפלות ומרירות גדולה שנוגע אל קירות<sup data-n=\"2534\">277</sup> הלב שלמעלה מכלי המוח והוא בעצמיות הנפש ממש שנק' יחידה שא\"א להתלבש בשכל ומדות כלל, שזהו למעלה משם ה' די\"ה חו\"ב<sup data-n=\"2535\">278</sup> כו' דהיינו שעי\"ז מעוררת למעלה גם מבחי' עצמיו' א\"ס<sup data-n=\"2536\">279</sup> שבפנימי' הכתר שלמעלה מכח\"ב<sup data-n=\"2537\">280</sup> ומדות, והוא בחי' המקיפי' דר\"ר העליוני' שא\"א שיתלבש בשכל ומדות העליוני' ונק' בחי' רעדכ\"ר שבמצחא דע\"י<sup data-n=\"2538\">281</sup>. וזהו על ה' בבחי' מקיף דה' דאצי' והוא בחי' מקיף דע\"י דאצי'<sup data-n=\"2539\">282</sup>, והוא בבחי' שם ה' שבעצמו' ממש כנ\"ל (שנמשך בי\"ג מדה\"ר לבד כמו ויקרא ה' ה' כו'<sup data-n=\"2540\">283</sup> ), [ו]בחי' ר\"ר העליוני' אינו נמשך כ\"א ע\"י ההעלא' דמרת נפש שהוא תכלית השפלות וההכנעה מקירות הלב (וע\"כ הי' שפתי' נעות וקולה לא ישמע<sup data-n=\"2541\">284</sup> להיותה למעלה מן הכוונה שבמוח ולב, וע\"כ המשמיע קולו בתפלתו<sup data-n=\"2542\">285</sup> ה\"ז מקטני אמנה שמצומצם בשכל ומדות בלבד כו'). וזהו עיקר ענין התפלה דכנ\"י בזמן הגלות שיש בה יתרון מעלה מתפלה שבזמן בהמ\"ק במה שבאה מצד [בחי'] המרירות והשפלות ביותר כתפלת חנה דכנ\"י נק' עקרה והיא מרת נפש בגלותא דוקא וכידוע שמעוררי' בזה מבחי' המקיפי' דר\"ר העליונים שא\"ז גם בתפלה שבדביקות וקירוב (כמ\"ש במ\"א עמ\"ש כן בקדש חזיתיך<sup data-n=\"2543\">286</sup> כו' הלואי כן בקדש חזיתיך כמו בגלות כו'). וכך הוא בכל ניצוץ קטן בפרט בתפלה, שמה שע\"י שפלות ומר[ירו]ת הנפש ביותר בלב נשבר ונדכה באמת עד שבכה יבכה במר נפשו מעורר בזה ממקור כל המקיפי' העליוני' דבחי' יחיד כמו שהוא לבדו ממש שלמעלה מההשתלשלו', שלא יוכל להגיע לזה כל תפלות הצדיקי' באה\"ר בתענוגי' במס\"נ כו' דרוח אייתי רוח כנ\"ל ולא יגיע רק לשם ה' שבא להיות מקור לד' עולמות דאבי\"ע ולא על ה' שהוא בחי' המקיף הכללי דר\"ר העליוני' הנ\"ל וד\"ל.\n(יב) <sup data-n=\"2544\">287</sup> <b>ולהבין</b> כל<sup data-n=\"2545\">288</sup> הנ\"ל, דהנה אנו אומרי' המלך המרומם<sup data-n=\"2546\">289</sup> לבדו [כו'] המתנשא מימות עולם ואח\"כ א[ומרים] אלקי עולם ברחמיך הרבים רחם עלינו אדון",[["2533","276","<b>דרוח אייתי רוח</b>: נסמן לעיל בפ' יתרו רנא, א."],["2534","277","<b>שנוגע אל קירות</b>: ה: שמגיע אל נקודת."],["2535","278","<b>די\"ה </b>[הט: דיו\"ד וה\"א]<b> חו\"ב</b>: נסמן לעיל רפז, א."],["2536","279","<b>א\"ס</b>: ט: אא\"ס."],["2537","280","<b>מכח\"ב</b>: הט: מחו\"ב."],["2538","281","<b>רעדכ\"ר שבמצחא דע\"י</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, ב."],["2539","282","<b>והוא בחי'. . דאצי'</b>: הט: ליתא."],["2540","283","<b>כו'</b>: שם: כנ\"ל."],["2541","284","<b>שפתי' נעות וקולה לא ישמע</b>: שמו\"א א, יג."],["2542","285","<b>המשמיע קולו בתפלתו</b>: ברכות כד, ב. ראה גם לעיל פ' בא קח, ב. וש\"נ."],["2543","286","<b>כן בקדש חזיתיך</b>: נסמן לעיל רפח, ב."],["2544","287","<b>(יב)</b>: ט: יד."],["2545","288","<b>כל</b>: הט: ביאור הדברים:"],["2546","289","<b>אנו אומרי' המלך המרומם</b>: בברכת יוצר [ושם: והמתנשא]."]]],[2300550443,"עוזינו צור משגבינו כו', ולכאורה אין ענין סמיכות שז\"ש אלקי עולם [ברחמיך] כו' למה שקדם תחלה שהוא ית' מלך מרומם לבדו ומתנשא מימו\"ע כו'. אך הענין הוא דבאמת יש להם סמיכות זה עם זה והא בהא תליא דוקא דמשום שנק' מלך מרומם לבדו ע\"כ או' <span data-k=\"pg\">תלה</span> ּ אח\"כ אלקי עולם ברחמיך הרבים רחם עלינו, והענין [הוא] כידוע בשרש ענין וסיבת מדה\"ר הגדולים בא[ה] מב' סבות שהן כא[חד], א' מצד הרוממות דמשפיע כל שהוא רם ומתנשא ביותר כמלך גדול ביותר. ו[ה]ב' מצד שפלות המקבל כמו עני ומדוכא ביותר שלפ\"ע הרוממות והשפלות כן יגדל מדה\"ר (כמו מחי' מתים בר\"ר<sup data-n=\"2547\">290</sup> ), ויש בזה שיעור ומדה עכ\"פ שאם אין ברוממות ע\"כ<sup data-n=\"2548\">291</sup> כשר קטן והמקבל אין שפע<sup data-n=\"2549\">292</sup> כ\"כ יתמעט הרחמי' ביותר, ולפ\"ע זה יתחלקו הרחמי' מן המלך על השרי' ועבדיו לפ\"ע הרוממות והשפלות. אבל יש בחי' רחמים שאינו בא בשיעור ומדה כלל ולכן הכל שוין בה כעני [כ]עשיר [כ]עבד והשר גדול, [ו]הוא [כאשר] הרוממות והתנשאו' דמשפיע הוא מלמעלה נבדל לגמרי בערך מהכל ולא באה בגדר וערך הרוממות וההתנשאו' על זולתו שאינו בערכו כלל, כמו האדם שנבדל בערך מן הצו\"ד<sup data-n=\"2550\">293</sup> ויש לו יחוס עם החי יותר עד שיתעורר ברחמים עליו ולא יתעורר ברחמים על הצו\"ד, ואם מרחם על איבוד מעשה ידיו בצו\"ד הרי יש בזה מדה לפ\"ע שיגיע אליו מבחי' היחוס והדבור<sup data-n=\"2551\">294</sup> דצו\"ד וכ\"ש החי שמתייחסי' עמדו וכלולי' במדבר (וכמ\"כ למעלה שחס על נינוה<sup data-n=\"2552\">295</sup> על האדם ובהמה רבה [ש]על האדם יש רחמים יותר כנ\"ל ). אבל כאשר נבדל בערך לגמרי לא יתכן לחלק הרחמים במדרגות שונות כ\"א על הכל יפול הרחמים בשוה על האדם כמו על הדומם, וכן במלך המרומם ביותר וערך נבדל לגמרי על הכל יפול הרחמים בשוה על השר ועבד הקטן בשוה דגם השר אין לו יחוס עמו בשוה ממש עם העבד כו' וכן על העשיר ועני מדוכה כו'.\n<b>וכן</b><sup data-n=\"2553\">296</sup> יובן למעלה בבחי' רחמים [רבים] העליונים שיש בזה ב' מדריגות, הא' הבא בשיעור ומדה בב' אופנים מחולקי' א' לפ\"ע הרוממות והשפלות שהוא הנק' עומ\"ר ועומ\"ת דלפ\"ע הרוממות דבחי' סוכ\"ע הכללי שמתנשא מימו\"ע ונשגב שמו מן הד' עולמות דאבי\"ע הרי נמשך בחי' הרחמים בהתחלקות. והב' לפ\"ע כל עולם ועולם ביחוס חבירו<sup data-n=\"2554\">297</sup> ע\"ד דוגמא בד' חלקי דצח\"מ שכלולי' בזה ד' עולמות דאבי\"ע<sup data-n=\"2555\">298</sup> בחי' אדם מדבר באצי' (שהוא יו\"ד דשם ה'), ובחי' החי בעולם הבריאה כשרפים וחיות ואופנים<sup data-n=\"2556\">299</sup> דבריאה כו' (והוא ה\"א<sup data-n=\"2557\">300</sup> ), ובחי' צומח עולם",[["2547","290","<b>מחי' מתים בר\"ר</b>: נוסח שמו\"ע."],["2548","291","<b>ע\"כ</b>: הט: כ\"כ."],["2549","292","<b>אין שפע</b>: שם: אינו שפל."],["2550","293","<b>הצו\"ד</b>: שם: הצומח ודומם:"],["2551","294","<b>והדבור</b>: שם: והחבור."],["2552","295","<b>שחס על נינוה</b>: יונה ד, יא."],["2553","296","<b>וכן</b>: ט: נרשם כאן פט\"ו. פט\"ז נרשם לקמן על יד הערה 334."],["2554","297","<b>ביחוס חבירו</b>: ה: ביחוד וקירוב כמו."],["2555","298","<b>דצח\"מ. . דאבי\"ע</b>: ראה סה\"ש ה'תשנ\"ב ע' 139 הערה 54. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680163\" data-slug=\"torat-chaim\" data-id=\"2300680163\">תו\"ח ויגש רלב, א</a> ובהערה 7. מאמרי אדה\"א דברים ח\"ג ע' תתסג. וש\"נ. הנחות תקע\"ז ע' חצר."],["2556","299","<b>ואופנים</b>: הט: ונשמות."],["2557","300","<b>ה\"א</b>: ה: ניתוסף: דבריאה כו'. ט: ניתוסף: דשם הוי'."]]],[2300550458,"היצי' ודומם הוא עולם העשי' וע\"ש זה נק' בשם ד' אותיות דה' כנ\"ל. וא\"כ יש בזה חילוקי מדריגות לפ\"ע בחי' החיבור והיחוס שמתייחסי' אל עצמו' אור המאציל שבא ונמשך בקו\"ח להאציל [ולברוא] כו' כמשל קירוב ויחוס דצ\"ח באדם הנ\"ל, שבחי' האצי' קרוב אליו ביותר מבחי' הבריאה שהוא כמו גדר חי רחוק יותר והיצי' בבחי' צומח רחוק עד עולם העשי' שהוא בערך הדומם שיתמעט שם בחי' הרחמים מחמת הריחוק ערך ביותר. וזהו מצד היחוס והקירוב, אבל מצד הרוממות והשפלות נהפוך הוא שכל [ש]הרוממות ביותר והשפלות ביותר יותר יוגדל מדה\"ר כמו אני מרום וקדוש<sup data-n=\"2558\">301</sup> את מי אשכון את דכא [ושפל רוח] כו', דעומ\"ר אינו מאיר רק בעומ\"ת<sup data-n=\"2559\">302</sup> דוקא כמו כי רם ה' ושפל יראה<sup data-n=\"2560\">303</sup>, א\"כ בחי' רוממות העליון ביותר שהוא מקיף הכללי דר\"ל<sup data-n=\"2561\">304</sup> דסובב לד' עולמות דאבי\"ע בשוה יותר יוגדל הרחמים <span data-k=\"pg\">872</span> ּ על עולם השפל ביותר מרחמי' שעל געה\"ע וגעה\"ת דבריאה ויצי' כו', ויהי' איך שיהי' עכ\"פ יצא האור הרחמי' דמקיף העליון הכללי בשיעור ומדה עכ\"פ. אבל מדריגה הב' דבחי' ר\"ר העליוני' יותר דהיינו ממהו\"ע<sup data-n=\"2562\">305</sup> א\"ס ב\"ה טרם שבא להאיר בקו\"ח בד' עולמו' שהוא למעלה גם מבחי' סובב הכללי (שנק' מקיף למקיף ונק' טה\"ע והוא שמי השמים<sup data-n=\"2563\">306</sup> העליוני' כידוע), שיובדל בערך לגמרי מכל ההשתלשלו' דמקיף ופנימי כו' משם יפול הר\"ר בלי התחלקות בשיעור ומדה וגם לא לפ\"ע הרוממות והשפלות, וכ\"ש שאין ל[א]בי\"ע יחוס אל העצמו' חילוק<sup data-n=\"2564\">307</sup> דצח\"מ דכתי' כי לא אדם הוא<sup data-n=\"2565\">308</sup> ושם שוה ומשוה קטן וגדול<sup data-n=\"2566\">309</sup> ממש דהיינו מראשית הקו\"ח עד סוף העשי' להיותו למעלה מבחי' עומ\"ר ועומ\"ת שזהו למעלה מבחי' מעלה ומטה שלמטה הוא כמו למעלה ממש וכמו שהי' קודם הצמצום שהי' הוא ושמו בלבד כו' (שהי' ממלא כל מקום החלל כו'). וא\"כ על הכל יומשך הר\"ר בשוה ממש על השפל כמו על הרם ביותר מאחר שאינו בא לפ\"ע הרוממות והשפלות כי שוין שם רוממות ושפלות וכמ\"ש המגביהי לשבת המשפילי [לראות]<sup data-n=\"2567\">310</sup> כו', והוא בבחי' התנשאו' שמצד עצמו ממש שלא<sup data-n=\"2568\">311</sup> נבדל בערך לגמרי [מ]התנשאו' שעל ימו\"ע הנ\"ל (ובבחי' ההתנשאו' דסובב הכללי יש חילוק מעלה ומטה עכ\"פ בב' אופני' הפכי' הנ\"ל). וכמו ע\"ד דוגמא שאו' אין ערוך לך<sup data-n=\"2569\">312</sup> בעוה\"ז שהוא ה\"א תתאה ואין זולתך לחיי עוה\"ב בה\"א עילאה דבינה ואפס בלתך ואין דומה לך כו' בתחה\"מ שכ\"א<sup data-n=\"2570\">313</sup> יש בהם חילוק מדריגות, אבל בעצמו' ההתנשאו' כולם שוין בבלתי ערך ונשגב מכולם בשוה ממש וכה\"ג וד\"ל.",[["2558","301","<b>אני </b>[ט: ליתא]<b> מרום וקדוש</b>: ישעי' נז, טו [בהוספת תיבת: אני — נסמן לעיל פ' בשלח קעא, ג]."],["2559","302","<b>דעומ\"ר. . בעומ\"ת</b>: ראה ס\"י פ\"א, מ\"ה. מאמרי אדה\"א דברים ח\"א ע' מג. וש\"נ. לעיל פ' וארא פג, ב. וש\"נ."],["2560","303","<b>כי רם ה' ושפל יראה</b>: תהלים קלח, ו."],["2561","304","<b>דר\"ל</b>: הט: דרחמים רבים."],["2562","305","<b>ממהו\"ע</b>: שם: מעצמות ומהות."],["2563","306","<b>טה\"ע והוא שמי השמים</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' שצה, וש\"נ. לעיל פ' בשלח קעא, ד. קעח, ג. לקמן פ' תרומה שטו, ג."],["2564","307","<b>חילוק</b>: הט: כד' חלקי."],["2565","308","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["2566","309","<b>שוה ומשוה קטן וגדול</b>: ע\"פ פיוט (לימים נוראים) האוחז ביד מדת משפט."],["2567","310","<b>המגביהי לשבת המשפילי [לראות]</b>: תהלים קיג, ה, ו."],["2568","311","<b>שלא</b>: הט: שהוא."],["2569","312","<b>אין ערוך לך</b>: ע\"פ ברכת יוצר לשבת."],["2570","313","<b>שכ\"א</b>: הט: שכל אלה."]]],[2300550473,"(יג) <sup data-n=\"2571\">314</sup> <b>ובכ\"ז</b> יובן סדר הדברים במ\"ש המלך המרומם לבדו [כו'] ואח\"כ אלקי עולם [כו'], דהנה בתחלה א[מר] המאיר לארץ ולדרים עליה ברחמים דמשמע דבחי' רחמים דמקיף זה<sup data-n=\"2572\">315</sup> מאיר בגילוי לארץ עילאה וארץ תתאה לכל עולם בפ\"ע<sup data-n=\"2573\">316</sup> עד עולם [הזה] השפל ומפרש משום ד[בטובו] מחדש בכל יום<sup data-n=\"2574\">317</sup> כי כולם בחכ' עשית<sup data-n=\"2575\">318</sup> שיש להם יחוס וקירוב [ולפ\"ע הקירוב והיחוס] נמשך שם הרחמים. ואח\"כ מפרש הדבר בב' ענינים הפכיי'<sup data-n=\"2576\">319</sup> שלפ\"ע הרוממות והשפלות יגדל או ימעט הרחמים שרחוק<sup data-n=\"2577\">320</sup> יותר ירוחם כנ\"ל [כ]מ\"ש כי רם ה' ושפל יראה. אמנם מפרש בזה ב' מדרגות, א' כשהוא המלך המרומם לבדו מאז כמו נכון כסאך מאז<sup data-n=\"2578\">321</sup> שהוא בחי' ההתנשאו' שמצד עצמו ממש שהי' הוא ושמו בלבד קודם הצמצום כו' שנק' מלך מרומם לבדו ממש והוא נבדל לגמרי גם מהיות בחי' סובב [ו]מקיף [ה]כללי שבא בגדר ההשפעה עכ\"פ כידוע דמקיף כללי הוא כמו הכלל אל הפרט שנק' מח' א' הכללי שצופה ומביט<sup data-n=\"2579\">322</sup> כו' כידוע, שמשם יפול הרחמים על הכל בשוה ושפל ורם יחד להיותו למעלה מעומ\"ר ועומ\"ת שנק' תחלה וסוף עכ\"פ והוא למעלה מבחי' תוס'<sup data-n=\"2580\">323</sup> מעלה ומטה כנ\"ל, ואח\"כ א[מר] מדרגה הב' שהוא משובח ומפואר ומתנשא מימו\"ע לבד שזהו בחי' סובב הכללי ששייך שם השבח ותפלה<sup data-n=\"2581\">324</sup> ונק' קדוש למעומ\"ט<sup data-n=\"2582\">325</sup> לגבי העולמות ומשם יומשך הרחמים להאיר בבחי' המקיף לכל עולם לפ\"ע כו' כנ\"ל בב' אופני' ההפכיי'. ולזאת אנו מבקשים <span data-k=\"pg\">תלו</span> ּ אח\"כ אלקי עולם ברחמיך הרבים דוקא רחם עלינו כו', פי' גם לאחר שנמשך ע\"י [ה]צמצום דקו\"ח להיות נק' אלקי עולם<sup data-n=\"2583\">326</sup> בבחי' סובב וממלא, עכ\"ז יומשך בחי' הרחמים הגדולים שמצד עצם הרוממות והתנשאות כמו שהוא בעצמותו ית' ממש שנק' רחמיך הרבים [רחמיך] דוקא, כמו זכור רחמיך וחסדיך<sup data-n=\"2584\">327</sup> כי מעולם המה מעולם הא\"ס עצמו ממש שלמעלה מרחמים דמקיף הכללי [הנ\"ל] והוא ושמו הנשגב שמו<sup data-n=\"2585\">328</sup> לבדו שנק' מלך מרומם<sup data-n=\"2586\">329</sup> לבדו שלמעלה מהתנשאו' שמימו\"ע לבד שהוא [ב]בחי' א\"ס ממש דאין לו שיעור למעלה ולמטה ולהיותו למעלה מבחי' מעלה ומטה כנ\"ל ואינו לפ\"ע המקבלים כלל שלזה הכל שוין שם קטן וגדול (והוא רחמים גדולים שבא[ים] בבחי' העלם שבלתי מורגש ונראה כלל למקבלים). וזהו רחם עלינו דוקא שיהיו [ה]רחמים גדולים הללו באים עלינו ביחוד דוקא, לפי שגם בעצם הרוממות הנ\"ל נבדל עם קרובו לרחם עליהם בעצם הרחמים ש[לא יכול ל]בא",[["2571","314","<b>(יג)</b>: ט: ליתא. וראה לעיל הערה 296."],["2572","315","<b>רחמים דמקיף זה</b>: הט: מקיף דרחמים אלה."],["2573","316","<b>בפ\"ע</b>: שם: לפ\"ע לפי ערכו."],["2574","317","<b>בכל יום</b>: שם: כו'."],["2575","318","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["2576","319","<b>בב' ענינים הפכיי'</b>: הט: בענין היפוכו."],["2577","320","<b>שרחוק</b>: שם: שהתחתון יותר."],["2578","321","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["2579","322","<b>מח' א' הכללי שצופה ומביט</b>: ראה ר\"ה יח, א. ברכת זכרונות. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' צ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680084\" data-slug=\"torat-chaim\" data-id=\"2300680084\">תו\"ח ויגש רל, ד</a>. לעיל פ' בשלח קסו, ג."],["2580","323","<b>תוס'</b>: הט: תחילה וסוף."],["2581","324","<b>ותפלה</b>: שם: ותהלה."],["2582","325","<b>למעומ\"ט</b>: שם: מלמעלה למטה."],["2583","326","<b>עולם</b>: ה: ניתוסף: בכלל. ט: ניתוסף: הכללי."],["2584","327","<b>זכור רחמיך וחסדיך</b>: תהלים כה, ו [בדילוג השם]. ראה גם לעיל פ' וארא סב, ב. וש\"נ."],["2585","328","<b>הנשגב שמו</b>: ה: של הנשגב. ט: נשגב."],["2586","329","<b>לבדו שנק' מלך מרומם</b>: ה: ליתא. ואולי נשמט מפני תיבות הדומות: לבדו. . לבדו."]]],[2300550488,"בהתלבשות [בעולמות] כלל כ\"א להיותר שפל בשפלות עצמו. כי יש בשפלות [ג\"כ] ב' אופנים<sup data-n=\"2587\">330</sup>, א' ביטול הישות והגסות<sup data-n=\"2588\">331</sup> כעני מדוכא שנעשה שפל ע\"י העוני. והב' שפלות עצמו בעצם הנפש כמו שפלות הכנ\"י בגלות שנק' מרת נפש בעצם וע\"ז א' כי רם ה' ושפל כו'<sup data-n=\"2589\">332</sup>, אך הוא בא מבחי' הרוממות שבעצמו' ממש שלמעלה מערך רוממות ושפלות דמשפיע ומקבל כי נעש[ים] כלי לעצמו' הרוממות אע\"פ ששם משוה קטן וגדול כנ\"ל מאחר שנבדל בערך לגמרי, אבל שפלות דאין העצמי שורה עליו מבחי' מקיף למקיף העליון ביותר<sup data-n=\"2590\">333</sup> [מ]על העולמות העליוני' [כו' וד\"ל].\n<b>וזהו</b><sup data-n=\"2591\">334</sup> ברחמיך הרבים שאין אנו משיגים הרחמים שעלינו כלל יותר [מן העליונים] שהם משיגים יותר הרחמנות והוא מצד שפלות העצמ[י]' ע\"כ ירחם עלינו מר\"ר<sup data-n=\"2592\">335</sup> העצמי' להיות באים בהתלבשות בבחי' מקיפים ממש. אמנם זהו הוראה על עצם מעלות מקיפים הללו שבאים מרוממות והתנשאו' העצמי' ממש במה שבאים בבחי' התלבשות בהגשמה יותר, והיינו כמו המקיפי' דענני כבוד שמקבלי' האבנים<sup data-n=\"2593\">336</sup> כו' ובעמוד ענן יומם<sup data-n=\"2594\">337</sup> כו' שזה הי' מצד הר\"ר שבעצמותו ממש ששורה בעננים לפי שהיו כנ\"י בשעבוד גלות מצרים בתכלית השפלות העצמו' ה'<sup data-n=\"2595\">338</sup>. וכך הוא ענין מ\"ש רחם עלינו להיות אדון עוזינו צור משגבינו כו' שהן ד' מקיפי'<sup data-n=\"2596\">339</sup> לנגד ד' עולמות דאבי\"ע, אדון עוזינו בחי' מקיף עליון בשרש נש\"י באצי', צור משגבינו בבחי' מקיף גשמי<sup data-n=\"2597\">340</sup> להגן ולחסות מן החיצונים בבחי' יצי', משגב [ממש] בעדינו בעולם העשי', והוא המקיף העליון יותר בשרשו בעצ[מות] הרוממו' עד שנעשה כמו חומה נשגבה מקפת להיות משגב בעדינו ממש שכל העליון יותר בא למטה בהתלבשות בהגשמה [ב]יותר<sup data-n=\"2598\">341</sup> כידוע וד\"ל.\n(יד) <sup data-n=\"2599\">342</sup> <b>ובכ\"ז</b> יובן בתוס' ביאור ענין הנ\"ל בתפלת חנה שא' והיא מרת נפש ותתפלל [חנה<sup data-n=\"2600\">343</sup> ] על ה' ובכה תבכה כו', דהנה מובן מכל הנ\"ל עכ\"פ דר\"ר העליונים נחלק לב' מדריגות, הא' הבא בשיעור ומדה לפ\"ע [ה]מקבלים בד' עולמות דאבי\"ע שהוא שם הוי' בכלל כידוע. והב' רחמים הגדולים שבא מצד [עצמות] הרוממות שנק' מלך מרומם לבדו כו', ומזה דוקא נעשה [בחי'] מקיף להיות משגב בעדינו כו'. וכך <span data-k=\"pg\">874</span> ּ הוא מ\"ש",[["2587","330","<b>אופנים</b>: הט: מדריגות."],["2588","331","<b>הישות והגסות</b>: שם: הגסות והישות."],["2589","332","<b>כו'</b>: שם: יראה."],["2590","333","<b>ביותר</b>: ה: דוקא והרבה יותר. ט: יותר."],["2591","334","<b>וזהו</b>: ט: נרשם כאן פט\"ז. פט\"ו נרשם לעיל על יד הערה 296. פי\"ז נרשם לקמן על יד הערה 350."],["2592","335","<b>מר\"ר</b>: הט: מרחמיך הרבים."],["2593","336","<b>דענני כבוד שמקבלי' </b>[שם: שקבלו]<b> האבנים</b>: ראה מכילתא בשלח יד, כ. הנסמן במאמרי אדה\"א קונטרסים ע' תלד."],["2594","337","<b>ובעמוד ענן יומם</b>: בשלח יד, כא. שלח יד, יד."],["2595","338","<b>ה'</b>: הט: כו'."],["2596","339","<b>אדון עוזינו. . ד' מקיפי'</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתנה. וש\"נ. הנסמן לעיל נג, א."],["2597","340","<b>גשמי</b>: ה: ניתוסף: יותר בבריאה מגן ישעינו. ט: דבריאה מגן ישעינו מקיף גשמי."],["2598","341","<b>שכל העליון יותר בא למטה. . [ב]יותר</b>: ראה הנסמן לעיל פ' שמות כא, ב הערה 863."],["2599","342","<b>(יד)</b>: ט: ליתא. ראה לעיל הערה 334."],["2600","343","<b>ותתפלל [חנה]</b>: נסמן לעיל הערה 208."]]],[2300550502,"ותתפלל על ה' להמשיך מרחמים [רבים] העליונים שנק' מקיף למקיף שזהו למעלה מסדר המדרג[ות] דה[וי]' שבאבי\"ע והוא למעלה מבחי' אדם. וזהו הטעם שלא [ה]גיע לשם אפי' תפלת הצדיקי' באה\"ר בתענוגי' במס\"נ כנ\"ל [כ\"א] בבחי' מרת נפש שהנפש מרה בעצם ושפלות בתכלית בעצם שזהו בחי' ההעלאה [ה]ו[א] בחי' הכלי לבחי' המקיף [דמקיף] העליון הזה שיומשך וישרה [עליו]. וזהו [ענין] והאכלתיך נחלת יעקב אביך<sup data-n=\"2601\">344</sup> שנק' נחלה בלי מצרים<sup data-n=\"2602\">345</sup> ונק' רחמים גדולים כמו ברגע קטן עזבתיך וברחמים גדולים אקבצך<sup data-n=\"2603\">346</sup> שאין נגאלין אלא בר\"ר הללו שנק' רחמים גדולים. וזהו [ו]בכה תבכה<sup data-n=\"2604\">347</sup> מעצמותה מצד בחי' מרירות העצמיות שבבחי' יחידה שבנפש (וענין ב' בכי' הללו מורים [א'] על בחי'<sup data-n=\"2605\">348</sup> דכנ\"י בזמן הגלות שנק' עקרה, ובכי' הב' לע\"ל דכתי' בבכי יבואו<sup data-n=\"2606\">349</sup> כו'). וזהו ענין התפלה דכנ\"י בזמן הגלות שיש בה יתרון מעלה מבזמן בהמ\"ק שבקירוב ודיבוק מפני שמעורר במקור כל המקיפי' דר\"ר העליונים כו' כידוע וד\"ל. והנה<sup data-n=\"2607\">350</sup> אחר שנת' בחי' המשכת הרחמים [רבים] הגדולים הנ\"ל שהי' בתפלת חנה יובן ג\"כ הטעם שנענית בתפל[ת]ה [ונפקדה] כמ\"ש עד עקרה ילדה שבעה כו', וכמו<sup data-n=\"2608\">351</sup> כנ\"י בזמן הגלות אע\"פ שנק' עקרה לא ילדה כלל ולע\"ל תפקד ותוליד כמ\"ש רני עקרה לא ילדה [בגלות] כו' וכמ\"ש שוש תשיש ותגל העקרה<sup data-n=\"2609\">352</sup> בקיבוץ בניה לתוכה בשמחה כו'. והענין הוא להיות מבואר לעיל בסיבת מניעת התולדה, א' מפני שאינה קולטת כלל. והב' הגם שקולטת אין בכחה כח התולדה כו' [ו]בעבודת ה' היינו הגם שיוקלט אור הזרוע לצ\"ע שהוא בחי' סוכ\"ע במוח ויומשך ללבו אין בזה בחי' תולדה באוי\"ר למעשה כו'.\n(טו) <sup data-n=\"2610\">353</sup> <b>אך</b> הנה כ\"ז הוא כאשר האור בא דרך שפע דמשפיע ומקבל מאור הזרוע לצ\"ע שהוא בבחי' סוכ\"ע כו' שאז העקרה לא תוליד אבל מעצמות א\"ס ב\"ה שלמעלה מכל ההשתלשלו' אבי\"ע (שהוא למעלה מבחי' אדם שכולל דו\"נ<sup data-n=\"2611\">354</sup> ) ה\"ז למעלה מבחי' משפיע ומקבל ומשם גם בחי' העקרה תלד, להיות שע\"י בחי' ר\"ר העליונים שבעצם הרוממות ששוה ומשוה הכל גדול וקטן כו' יוכל להיות המשכת כח התולדה גם לעקר[ו]ת כו' (וכמו האמהות שעקרות היו וילדו<sup data-n=\"2612\">355</sup> ) מפני שהי' בהם האור שלמעלה מן ההשתלשלו' מעין דלע\"ל שא[מר]ו עתידה אשה שתלד בכ\"י כו' כמו הארץ שתוציא צמחה",[["2601","344","<b>והאכלתיך נחלת יעקב אביך</b>: ישעי' נח, יד."],["2602","345","<b>נחלה בלי מצרים</b>: שבת קיח, סע\"א. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קח ואילך."],["2603","346","<b>כמו </b>[הט: כמ\"ש]<b> ברגע קטן. . אקבצך</b>: ישעי' נד, ז."],["2604","347","<b>[ו]בכה תבכה</b>: שמו\"א א, י."],["2605","348","<b>בחי'</b>: ט: בכי'."],["2606","349","<b>בבכי יבואו</b>: ירמי' לא, ח."],["2607","350","<b>והנה</b>: ט: נרשם כאן פי\"ז. פט\"ז נרשם לעיל על יד הערה 334. פי\"ח נרשם להלן על יד הערה 361."],["2608","351","<b>וכמו</b>: הט: וכן."],["2609","352","<b>שוש תשיש ותגל העקרה</b>: נוסח ברכת נשואין."],["2610","353","<b>(טו)</b>: ט: ליתא. ראה לעיל הערה 350."],["2611","354","<b>אדם שכולל דו\"נ</b>: ראה זהר בהקדמה יג, ב."],["2612","355","<b>(וכמו. . וילדו)</b>: הט: וכמו. . [ו]ילדו."]]],[2300550516,"[מעצמה] <b>בלי</b> זריעה וכמ\"ש עתידה ארץ שתוציא גלוסקאות<sup data-n=\"2613\">356</sup>. והוא מפני שנעשה בחי' כלי לעצמו' [ש]שם יכול לעשות כלי גם לעקרה שתלד וכמ\"ש לע\"ל רני עקרה שהוא כנ\"י בגלות כו'. והוא ע\"י בחי' השפלות העצמיו' שמעורר רחמים [רבים] גדולים הנ\"ל שהוא למעלה מאור הזרוע כו' והוא שעושה כח המוליד גם בעקרה שתקלט אור הזרוע כו' ותוליד אוי\"ר שנק' בנים בבחי' [חיים] נצחי' כמו הנצחי' דא\"ס ממש, והוא בחי' המשיח שנא' בו אני היום ילדתיך שיחי' חיים נצחי' כמ\"ש חיים נתת לו<sup data-n=\"2614\">357</sup> וכמ\"ש דוד מ\"י חי וקיים<sup data-n=\"2615\">358</sup> לפי שיהי' בדומה לעצמו'. ומ\"ש חיים נתת לו לפי שדוד מ\"י חיי[ם שלו] שאולים היו מאדה\"ר<sup data-n=\"2616\">359</sup> ונק' נפל וכמ\"ש אימתי אתי בר נפל[י]<sup data-n=\"2617\">360</sup> כו', אבל חיים נצחי[ם] נתת לו מטעם הנ\"ל וד\"ל.\n<span data-k=\"pg\">תלז</span> ּ<b>(טז)</b><sup data-n=\"2618\">361</sup> וזהו לא תהי' משכלה ועקרה בארציך כו'<sup data-n=\"2619\">362</sup> דקאי לע\"ל שתתעלה [בחי'] המל' שהיא כנ\"י ל[היות] אה\"ח למעלה מעלה לקבל מחיי החיים שהוא עצמו' [(א)א\"ס ב\"ה] מקור כל המקיפי' העליונים [כנ\"ל] שנק' רחמים הגדולים אז לא תהי' משכלה ולא עקרה בארציך מטעם [כל] הנ\"ל. אך עדיין י\"ל מ\"ש את מספר ימיך אמלא מה עני[נו] לכאן, ומשמעות פשוטו שלא די שלא תהי' משכלה יולדת וקוברת אלא יחי' חיים ארוכים ביותר מכפי המדה והשיעור שניתן לאדם [ל]חיות [ב]עולם, והוא מ\"ש את מספר ימיך אמלא למלאות הימי' למעלה מן המספר של הימים כו', שאם המדה הקצובה למספר הימים [ע' שנה] כמ\"ש ימי שנותינו בהם ע' שנה<sup data-n=\"2620\">363</sup> ימלא אותם שיאריך ימיו הרבה יותר ממדה הזאת וזהו את מספר ימיך אמלא, ואין זה מובן דאם הימים קצובים מהיכן יהיו מלאים בתוס' רב על המדה כו'. אך הנה י\"ל<sup data-n=\"2621\">364</sup> מה ענין הימים כו', והוא מ\"ש בזהר ע\"פ ואברהם זקן בא בימים<sup data-n=\"2622\">365</sup> באינון יומין עילאין וי\"ל מהו ההפרש בין יומין עילאין ליומין תתאין, והוא מובן מפשט הכתוב דימי הזקנה הוא שנק' יומין עילאין שז\"ש ואברהם זקן בא בימים ביומין עילאין<sup data-n=\"2623\">366</sup> הזקנה שמעלתם גבוה הרבה, והן בבחי' יומין עילאין כו'. וביאור הענין הנה פי' זקן היינו שקנה חכ'<sup data-n=\"2624\">367</sup> ממקור החכ' דוקא שעז\"א בזהר דסבא דעתי' סתים<sup data-n=\"2625\">368</sup> בבחי' העלם דמקור החכ' דוקא, והענין הוא כידוע שיש ב' מדרגות בחכ', א' כשבא מבחי' [ה]העלם ל[בחי' ה]גילוי מאין ליש בהשגה דבינה, [ואז] המדות דחו\"ג באים בגילוי [ו]בהתחלקות שונות ומשתנים מדבר להיפוכו כמו מחסד לדין ומדין לחסד פעם כך ופעם כך,",[["2613","356","<b>עתידה ארץ שתוציא גלוסקאות</b>: ראה שבת ל, ב. הנסמן לעיל פ' שמות כג, ב."],["2614","357","<b>המשיח. . חיים נתת לו</b>: תהלים כא, ה. סוכה נב, א. ראה הנסמן לעיל פ' בשלח רכז, ב."],["2615","358","<b>דוד מ\"י חי וקיים</b>: ר\"ה כה, א. נוסח קידוש לבנה."],["2616","359","<b>שדוד מ\"י חיי[ם שלו] שאולים היו מאדה\"ר</b>: ראה זהר וישלח קסח, א. בראשית נה, סע\"א. לך צא, ב. מאמרי אדה\"א קונטרסים ע' שנא. וש\"נ."],["2617","360","<b>אימתי אתי בר נפל[י]</b>: ראה סנהדרין צו, סע\"ב."],["2618","361","<b>(טז)</b>: ט: יח. ראה לעיל הערה 350."],["2619","362","<b>כו'</b>: הט: את מספר ימיך אמלא."],["2620","363","<b>ימי שנותינו בהם ע' שנה</b>: תהלים צ, י."],["2621","364","<b>י\"ל</b>: הט: יש להקדים."],["2622","365","<b>ואברהם זקן בא בימים</b>: נסמן לעיל רפה, ב."],["2623","366","<b>ביומין עילאין</b>: הט: בימי."],["2624","367","<b>זקן היינו שקנה חכ'</b>: ראה תו\"כ קדושים יט, לב. קדושין לב, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשמ."],["2625","368","<b>דסבא דעתי' סתים</b>: ראה זהר (אד\"ר) נשא קכח, ב. אמ\"ב שער התפילין קל, ד."]]],[2300550529,"לפי שיש משפט<sup data-n=\"2626\">369</sup> ג[י]לוי השכל שישתנה תמיד [מ]מקור השכל להטות כלפי חסד ומחסד לדין ונק' מדות שבחכ' טורי נהורא<sup data-n=\"2627\">370</sup> כו' (והוא עיקר בחי' אדם שדרכו וטבעו להנחם [כו')]. וזהו ימים שהם מדות דנר\"נ באדם<sup data-n=\"2628\">371</sup> עד ימי הזקנה שהן ע' שנה ז' מדות וכ\"א [ואחד] כלול מיו\"ד<sup data-n=\"2629\">372</sup> שיש בה[ם] שינוי' רבים מיום ליום שפעם עבודתו באהבה וחסד ופעם ביראה, ויש בהם טו\"ר כמו [ימי] נפילה ברע שנק' ימי הרעה<sup data-n=\"2630\">373</sup> ברוחני' ונפילה בגשמיות כו' ויש ימי הטוב בגשמי' ורוחני' כמ\"ש למה איר[א] בימי רע<sup data-n=\"2631\">374</sup> כמ\"ש בזהר דאית שנק' יומין<sup data-n=\"2632\">375</sup> למעלה<sup data-n=\"2633\">376</sup> לטב ולביש שהם חו\"ג שמשתנה תמיד כו', וזהו בחי' יומין תתאין דז\"א כו' שנק' אדם הקטן שמקבל מאו\"א כו' וד\"ל. והמדרגה הב' בחכ' שנק' אדם הגדול והוא בחי' ע\"י וא\"א<sup data-n=\"2634\">377</sup> שהוא למעלה מגילוי השכל עדיין לא באו<sup data-n=\"2635\">378</sup> בגילוי המדות כו', והוא בחי' זקן שקנה חכ' כמו שהוא במקורה שנק' תעלומות חכ'<sup data-n=\"2636\">379</sup> שהן ימי הזקנה שאין בחי' המדות דשם ה'<sup data-n=\"2637\">380</sup> בשינויי' להיות פעם [כך ופעם כך] כו'. והוא מצד בחי' [ה]שלימות [ה]אמיתי שבעצם מקור החכ' והוא [ב]בחי' המקיפים דנר\"נ באדם כו', כי כל שינוי וחילוף ותמורה אין זה שלימות. וע\"כ נק' ימי הזקנה ימים שלימים בבחי' השלימות בלי שינוי כלל וכמו בסנהדרין שהיו זקנים<sup data-n=\"2638\">381</sup> דוקא מטעם זה שלא יטה השכל [מ]דבר [ל]היפוכו. וזהו משום דסבא דעתי' סתים וכמא' דזקנים דעתן מתיישב[ת] עליהם<sup data-n=\"2639\">382</sup>, פי' מתיישבי' בישוב ודעת שיש בו קביעות בל[י] <span data-k=\"pg\">876</span> ּ יפול בו שינוי כי רתיחות הבחורים גם בתוכם<sup data-n=\"2640\">383</sup> יעשה שינוי להפוך מטוב לרע משא\"כ הזקן שקנה חכ' כו'.\n<b>וכך</b> הוא בעבודת ה' שיהי' עבודתו [תמה ו]שלימה במדת השלימות כמו בימי הזקנה בלתי שינויים והוא בקביעות ובישוב הדעת בלי נטי' לפעמים כך כו'. וז\"ש באברהם זקן בא בימים כו' גם שאברהם הי' בחי' מרכבה<sup data-n=\"2641\">384</sup> ממש גם כל ימיו מנעוריו<sup data-n=\"2642\">385</sup> שבן ג' שנים הכיר לבוראו<sup data-n=\"2643\">386</sup> כו', והיינו<sup data-n=\"2644\">387</sup> מדותיו שבלב נכללים בכח השכל וההשגה שבמוחו איך שהוא ית' בורא ומהוה מאין ליש ולא הי' בו שינוי במדותיו באהבה ודביקות תמידית כל היום וכמ\"ש התהלך לפני והי' תמים<sup data-n=\"2645\">388</sup>, עכ\"ז א' עליו ש[ל]עת זקנותו הגיע לבא לימים בחי' יומין עילאין הנ\"ל, שזהו נק' ימים שלימי' שבמקור החכ' כמו שהוא בבחי' [אין ו]העלם דבחי' מקיף [ד]חי' [ו]יחידה כו'. והוא כמו אה\"ר העצמי' שבעצם",[["2626","369","<b>משפט</b>: ט: שפע."],["2627","370","<b>מדות שבחכ' טורי נהורא</b>: ראה זהר פינחס רמט, ב. הנסמן לעיל פ' שמות טז, א."],["2628","371","<b>דנר\"נ באדם</b>: ט: דנה\"ט."],["2629","372","<b>כלול מיו\"ד</b>: הט: נחלק ליו\"ד."],["2630","373","<b>ימי הרעה</b>: קהלת יב, א."],["2631","374","<b>למה איר[א] בימי רע</b>: תהלים מט, ו."],["2632","375","<b>דאית שנק' יומין</b>: ראה זהר מקץ רד, א. ביאוה\"ז שם לג, ג."],["2633","376","<b>שנק' יומין למעלה</b>: הט: שנין ויומין ידיען לעילא."],["2634","377","<b>ע\"י וא\"א</b>: שם: א\"א וע\"י."],["2635","378","<b>לא באו</b>: שם: לבא."],["2636","379","<b>תעלומות חכ'</b>: איוב יא, ו. ראה גם לעיל פ' שמות לג, א. וש\"נ."],["2637","380","<b>ה'</b>: הט: באים."],["2638","381","<b>בסנהדרין שהיו זקנים</b>: ראה גם לעיל פ' בשלח רא, ג. וש\"נ."],["2639","382","<b>דזקנים </b>[ט: דזקנים ת\"ח]<b> דעתן מתיישב[ת] עליהם</b>: ראה קנים פ\"ג, מ\"ו. לעיל פ' בשלח רו, ג."],["2640","383","<b>בתוכם</b>: ה: בחכם גדול. ט: בחכם."],["2641","384","<b>שאברהם. . מרכבה</b>: ראה ב\"ר פמ\"ז, ו. פפ\"ב, ו. לעיל פ' יתרו רנא, ג הערה 55."],["2642","385","<b>גם כל ימיו מנעוריו</b>: הט: כל ימיו גם בנערותו."],["2643","386","<b>שבן ג' שנים הכיר לבוראו </b>[שם: את בוראו]: נדרים לב, סע\"א. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' פ. וש\"נ. הנחות תקע\"ז ע' קע. וש\"נ. סה\"מ ליקוט ח\"ב ע' מ. וראה גם לקמן פ' תצוה שעח, ג."],["2644","387","<b>והיינו</b>: הט: והיו."],["2645","388","<b>התהלך לפני והי' תמים</b>: לך יז, א."]]]]});
